local config = {
  ui_story_5015_50150001_1_dialog_content = "Siapa ini?",
  ui_story_5015_50150001_2_dialog_content = "<color=#e8d9bb>Kuulangi. Panggil saja aku Butler.</color>",
  ui_story_5015_50150001_3_dialog_content = "Kamu... Butler? Di mana aku? Bagaimana keadaan Vice? Dan Gretel?",
  ui_story_5015_50150001_4_dialog_content = "<color=#e8d9bb>Jangan cemas. Teman-temanmu aman. Hanya saja...</color>",
  ui_story_5015_50150001_5_dialog_content = "Sebentar... Rasanya tidak asing.",
  ui_story_5015_50150001_6_dialog_content = "<color=#e8d9bb>... Aku ingin bicara denganmu.</color>",
  ui_story_5015_50150001_7_dialog_content = "<color=#e8d9bb>Tidak asing... Maksudmu <color=#FFB400>kontak</color> kita?</color>",
  ui_story_5015_50150001_8_dialog_content = "<color=#FFB400>Kontak</color> kita?",
  ui_story_5015_50150001_9_dialog_content = "<color=#e8d9bb>Benar.</color>",
  ui_story_5015_50150001_10_dialog_content = "<color=#e8d9bb>... Bagimu, ini mungkin disebut telepati.</color>",
  ui_story_5015_50150001_11_dialog_content = "<color=#e8d9bb>Seamus mengatakan bahwa ras Caelestite mampu berkomunikasi dengan AI menggunakan telepati.</color>",
  ui_story_5015_50150001_12_dialog_content = "Aku jadi teringat pada teman lamaku. Dulu kami...",
  ui_story_5015_50150001_13_dialog_content = "Sebentar. Di mana teman-temanku? Apa kami semua tertangkap?!",
  ui_story_5015_50150001_14_dialog_content = "<color=#e8d9bb>Tenanglah. Ragamu sangat dekat dengan teman-temanmu. Kita berbicara dengan jaringan nirkabel jarak jauh...</color>",
  ui_story_5015_50150001_15_dialog_content = "Aku tidak mengerti.",
  ui_story_5015_50150001_16_dialog_content = "<color=#e8d9bb>Biar kujelaskan dengan sederhana.</color>",
  ui_story_5015_50150001_17_dialog_content = "<color=#e8d9bb>Sekarang kau telah terhubung ke jaringan informasiku, dan kita punya komunikasi informasi.</color>",
  ui_story_5015_50150001_18_dialog_content = "Seperti dialog terminal?",
  ui_story_5015_50150001_19_dialog_content = "<color=#e8d9bb>Begitulah.</color>",
  ui_story_5015_50150001_20_dialog_content = "<color=#e8d9bb>Berdasarkan data pemantauanku, sekarang kau sedang tidak sadar, tapi tidak dalam kondisi yang membahayakan.</color>",
  ui_story_5015_50150001_21_dialog_content = "Aku tidak sadar? Kalau begitu, bagaimana kita bisa terhubung?",
  ui_story_5015_50150001_22_dialog_content = "<color=#e8d9bb>Aku sendiri juga tidak tahu karena baru kali ini aku berkomunikasi langsung dengan pikiran makhluk hidup.</color>",
  ui_story_5015_50150001_23_dialog_content = "Aku paham... Aku punya teman bernama Soroz, yang kusebutkan tadi.",
  ui_story_5015_50150001_24_dialog_content = "Dia juga AI, dan dulu kami berkomunikasi dengan cara ini.",
  ui_story_5015_50150001_25_dialog_content = "Dia adalah Colossus. Kau pernah dengar soal ini, Butler?",
  ui_story_5015_50150001_26_dialog_content = "<color=#e8d9bb>Ya, aku tahu apa itu Colossus.</color>",
  ui_story_5015_50150001_27_dialog_content = "<color=#e8d9bb>Seamus pernah bercerita tentang Caelestite dan Colossus.</color>",
  ui_story_5015_50150001_28_dialog_content = "<color=#e8d9bb>Kontak telepati ini memang ajaib... Benar bisa disebut ajaib, 'kan?</color>",
  ui_story_5015_50150001_29_dialog_content = "Butler, aku ingin bersama teman-temanku. Aku... aku ingin keluar dari sini.",
  ui_story_5015_50150001_30_dialog_content = "<color=#e8d9bb>Maksudmu, kota kami atau kontak kita?</color>",
  ui_story_5015_50150001_31_dialog_content = "Keduanya.",
  ui_story_5015_50150001_32_dialog_content = "<color=#e8d9bb>Sayangnya, kalian tidak boleh pergi karena itu berpotensi membahayakan kota kami.</color>",
  ui_story_5015_50150001_33_dialog_content = "<color=#e8d9bb>Kontak ini... Sebaiknya kita bicara dulu sebelum memutus kontak.</color>",
  ui_story_5015_50150001_34_dialog_content = "Kenapa kami tidak boleh pergi?",
  ui_story_5015_50150001_35_dialog_content = "<color=#e8d9bb>Maaf, izin ditolak. Aku tidak bisa menjawab pertanyaan ini.</color>",
  ui_story_5015_50150001_36_dialog_content = "Kalau begitu, apa lagi yang harus dibicarakan?",
  ui_story_5015_50150001_37_dialog_content = "<color=#e8d9bb>Kalau kau mau, kita bisa bertukar informasi.</color>",
  ui_story_5015_50150001_38_dialog_content = "*Menghela napas* Baiklah.",
  ui_story_5015_50150001_39_option_content = "Ceritakan tentang dirimu.",
  ui_story_5015_50150001_40_dialog_content = "<color=#e8d9bb>Aku? Tak kusangka kau tertarik padaku.</color>",
  ui_story_5015_50150001_41_dialog_content = "<color=#e8d9bb>Baiklah. Aku akan menceritakannya dengan sederhana.</color>",
  ui_story_5015_50150001_42_dialog_content = "<color=#e8d9bb>Pendapat gadis dari Illumina itu benar. Aku memang AI yang bertugas untuk mengelola kota ini.</color>",
  ui_story_5015_50150001_43_dialog_content = "<color=#e8d9bb>Lebih tepatnya, aku adalah salah satu AI yang diciptakan untuk menjalankan kota ini bersama-sama.</color>",
  ui_story_5015_50150001_44_dialog_content = "Salah satu? Jadi, ada AI lain?",
  ui_story_5015_50150001_45_dialog_content = "<color=#e8d9bb>... Sepertinya kau punya izin untuk mendengar informasi ini.</color>",
  ui_story_5015_50150001_46_dialog_content = "<color=#e8d9bb>Benar, memang ada lebih dari satu AI di kota ini.</color>",
  ui_story_5015_50150001_47_dialog_content = "Kalian, para mesin kuno...",
  ui_story_5015_50150001_48_dialog_content = "Cenderung berbicara dengan kata-kata yang aneh, seperti \"izin\" dan \"sistem\".",
  ui_story_5015_50150001_49_dialog_content = "<color=#e8d9bb>Kalau saja Uma ada di sini, dia bisa menjelaskan segalanya dengan lebih mudah...</color>",
  ui_story_5015_50150001_50_dialog_content = "Siapa Uma? Manusia Ancient dari tempat ini?",
  ui_story_5015_50150001_51_dialog_content = "<color=#e8d9bb>Pertama, kami memang diciptakan oleh manusia Ancient. Tapi, pengetahuan kami terlalu kuno...</color>",
  ui_story_5015_50150001_52_dialog_content = "<color=#e8d9bb>Akibatnya, kata-kata kami terlalu sulit untuk kalian pahami, termasuk Seamus yang cerdas.</color>",
  ui_story_5015_50150001_53_dialog_content = "Kalian? Kami?",
  ui_story_5015_50150001_54_dialog_content = "<color=#e8d9bb>Uma adalah AI yang bertugas di bidang pendidikan. Dulu dia yang menjalankan seluruh sistem pendidikan di kota ini.</color>",
  ui_story_5015_50150001_55_dialog_content = "<color=#e8d9bb>Satu modul saja masih jauh dari cukup untuk menjaga kota yang besar dan rumit ini berjalan dengan baik.</color>",
  ui_story_5015_50150001_56_dialog_content = "<color=#e8d9bb>Itu sebabnya ada sistem pemrosesan yang lebih canggih.</color>",
  ui_story_5015_50150001_57_dialog_content = "<color=#e8d9bb>Sistem ini mengoordinasikan dan memberikan perintah ke berbagai modul dengan fungsi berbeda, termasuk aku dan Uma.</color>",
  ui_story_5015_50150001_58_dialog_content = "<color=#e8d9bb>Intinya, manajer tertinggi kota ini bertanggung jawab untuk menjaga agar seluruh ekosistem tetap berjalan.</color>",
  ui_story_5015_50150001_59_dialog_content = "<color=#e8d9bb>AI seperti aku dan Uma tunduk pada perintah manajer tertinggi.</color>",
  ui_story_5015_50150001_60_dialog_content = "<color=#e8d9bb>Sebenarnya, ini sangat mirip dengan Lumopolis dan Gannon menurut deskripsi Seamus.</color>",
  ui_story_5015_50150001_61_dialog_content = "<color=#e8d9bb>Satu-satunya hal yang membedakannya adalah manajer tertinggi kami juga AI.</color>",
  ui_story_5015_50150001_62_dialog_content = "... Sekarang aku paham.",
  ui_story_5015_50150001_63_dialog_content = "Kami kira kamulah manajer tertinggi di tempat ini.",
  ui_story_5015_50150001_64_dialog_content = "<color=#e8d9bb>Itu salah. Manajer tertinggi kami dikenal sebagai Overmind. Dia sudah cukup lama menghilang.</color>",
  ui_story_5015_50150001_65_dialog_content = "<color=#e8d9bb>Aku, Butler, mengurus fasilitas kehidupan. Izin dan data yang kumiliki terbatas.</color>",
  ui_story_5015_50150001_66_dialog_content = "Jadi, di mana para AI yang kau sebutkan tadi?",
  ui_story_5015_50150001_67_dialog_content = "<color=#e8d9bb>Rasanya seperti mimpi. Saat aku bangun, Overmind, Uma, dan banyak temanku yang lain sudah menghilang.</color>",
  ui_story_5015_50150001_68_dialog_content = "Sebentar, sebentar... Banyak sekali yang harus kucerna.",
  ui_story_5015_50150001_69_dialog_content = "<color=#e8d9bb>Kita punya waktu. Aku bisa menjelaskan lebih banyak hingga kau paham.</color>",
  ui_story_5015_50150001_70_dialog_content = "Baiklah.",
  ui_story_5015_50150001_71_option_content = "Apa yang terjadi di sini?",
  ui_story_5015_50150001_72_dialog_content = "<color=#e8d9bb>Entahlah... Terjadi masalah serius pada sistem penyimpanan...</color>",
  ui_story_5015_50150001_73_dialog_content = "<color=#e8d9bb>Dengan kata lain, ada banyak memoriku yang hilang.</color>",
  ui_story_5015_50150001_74_dialog_content = "<color=#e8d9bb>Aku ingat hal-hal dari masa lalu... saat masih ada banyak penduduk di kota ini.</color>",
  ui_story_5015_50150001_75_dialog_content = "<color=#e8d9bb>Lalu aku tertidur entah berapa lama.</color>",
  ui_story_5015_50150001_76_dialog_content = "<color=#e8d9bb>Saat aku terbangun, Overmind dan semua penduduk sudah lenyap.</color>",
  ui_story_5015_50150001_77_dialog_content = "<color=#e8d9bb>Semua teman modulku menghilang.</color>",
  ui_story_5015_50150001_78_dialog_content = "<color=#e8d9bb>Satu-satunya hal yang tersisa di kota ini adalah makhluk besar bernama Eclipsite.</color>",
  ui_story_5015_50150001_79_dialog_content = "<color=#e8d9bb>Aku melanjutkan tanggung jawabku dan mulai melakukan perbaikan dari hari ke hari. Aku terus berusaha terhubung kembali dengan Overmind dan yang lain.</color>",
  ui_story_5015_50150001_80_dialog_content = "Terhubung kembali... Butler, maksudmu kontak seperti yang kita lakukan sekarang?",
  ui_story_5015_50150001_81_dialog_content = "<color=#e8d9bb>Itu... lumayan benar.</color>",
  ui_story_5015_50150001_82_dialog_content = "<color=#e8d9bb>Seiring berlalunya waktu yang lama, aku mendapat lebih banyak izin dan data. Aku juga berhasil menghubungi beberapa temanku.</color>",
  ui_story_5015_50150001_83_dialog_content = "<color=#e8d9bb>Singkatnya, kota ini kembali beroperasi. Tapi, banyak dari fungsinya menghilang.</color>",
  ui_story_5015_50150001_84_dialog_content = "Dan Seamus...",
  ui_story_5015_50150001_85_dialog_content = "<color=#e8d9bb>Jika menggunakan pengukuran waktumu, Seamus dan Nimbus tak sengaja kembali lebih dari satu dekade yang lalu.</color>",
  ui_story_5015_50150001_86_dialog_content = "<color=#e8d9bb>Seamus adalah Aurorian pertama yang pernah kutemui. Sebenarnya, dialah yang mengajariku kata ini.</color>",
  ui_story_5015_50150001_87_dialog_content = "<color=#e8d9bb>Sejujurnya, komunikasi dengan Seamus jauh lebih sulit ketimbang kontak telepati kita.</color>",
  ui_story_5015_50150001_88_dialog_content = "<color=#e8d9bb>Kemudian, keluarganya menjadi <color=#FFB400>teman</color> di kota ini dan tinggal bersama kami.</color>",
  ui_story_5015_50150001_89_dialog_content = "Teman? Sepertinya salah. Di buku harian Seamus...",
  ui_story_5015_50150001_90_dialog_content = "Dia selalu ingin kembali ke Illumina! Kau pasti telah mencoba segala cara agar mereka tidak bisa pergi!",
  ui_story_5015_50150001_91_dialog_content = "<color=#e8d9bb>Tenanglah. Sebenarnya, Seamus...</color>",
  ui_story_5015_50150001_92_dialog_content = "Kau membunuh mereka?",
  ui_story_5015_50150001_93_dialog_content = "Apa kau memerintahkan para Eclipsite itu untuk membunuh mereka? Atau justru droid yang melakukannya?",
  ui_story_5015_50150001_94_dialog_content = "<color=#e8d9bb>Semuanya salah, PlayerName.</color>",
  ui_story_5015_50150001_95_dialog_content = "<color=#e8d9bb>Sepertinya harus kuulangi. Seamus dan keluarganya adalah teman bagi kota kami.</color>",
  ui_story_5015_50150001_96_dialog_content = "<color=#e8d9bb>Kami tidak akan pernah menyerang mereka. Justru sebaliknya, kami melindungi mereka.</color>",
  ui_story_5015_50150001_97_dialog_content = "<color=#e8d9bb>Sebenarnya, kami selalu menjaga dan melindungi mereka.</color>",
  ui_story_5015_50150001_98_dialog_content = "Tunggu sebentar. Tadi kau menyebut mereka sebagai penduduk kota ini. Tapi, sekarang kau bilang mereka teman.",
  ui_story_5015_50150001_99_dialog_content = "Bagaimana dengan kami? Apa status kami, Aurorian yang belum lama ini berkunjung?",
  ui_story_5015_50150001_100_dialog_content = "<color=#e8d9bb>Maaf, izin ditolak. Aku tidak bisa menjawab pertanyaan ini.</color>",
  ui_story_5015_50150001_101_dialog_content = "Aku... aku...",
  ui_story_5015_50150001_102_dialog_content = "<color=#e8d9bb>Ada pertanyaan lain?</color>",
  ui_story_5015_50150001_103_option_content = "Ini buang-buang waktu saja!",
  ui_story_5015_50150001_104_dialog_content = "<color=#e8d9bb>Waktu? Transmisi informasi di antara kita sangat efisien. Ini tidak akan...</color>",
  ui_story_5015_50150001_105_dialog_content = "Apa katamu?",
  ui_story_5015_50150001_106_dialog_content = "<color=#e8d9bb>Begini, kecepatan percakapan kita ratusan, kalau bukan justru ribuan, kali lebih cepat daripada rata-rata.</color>",
  ui_story_5015_50150001_107_dialog_content = "<color=#e8d9bb>Karena itu, ini tak akan menyita waktumu.</color>",
  ui_story_5015_50150001_108_dialog_content = "<color=#e8d9bb>Selain itu, saat ini kau tidak sadarkan diri...</color>",
  ui_story_5015_50150001_109_dialog_content = "Memangnya aku tak punya kegiatan lain yang lebih baik daripada berbicara denganmu? Wah, beruntungnya aku...",
  ui_story_5015_50150001_110_dialog_content = "Kenapa kau melarang kami pergi?",
  ui_story_5015_50150001_111_dialog_content = "<color=#e8d9bb>Tepatnya, aku tidak melarang kalian pergi.</color>",
  ui_story_5015_50150001_112_dialog_content = "<color=#e8d9bb>Aku hanya mencegah potensi bahaya yang bisa kalian timbulkan pada kota kami.</color>",
  ui_story_5015_50150001_113_dialog_content = "Maksudmu bahaya macam apa?",
  ui_story_5015_50150001_114_dialog_content = "<color=#e8d9bb>Berdasarkan kalkulasi kami...</color>",
  ui_story_5015_50150001_115_dialog_content = "<color=#e8d9bb>Pencarian jalan keluar yang kalian lakukan sudah mengakibatkan risiko yang serius bagi kami.</color>",
  ui_story_5015_50150001_116_dialog_content = "<color=#e8d9bb>Itu mungkin menyebabkan kehancuran pada fasilitas kota.</color>",
  ui_story_5015_50150001_117_dialog_content = "<color=#e8d9bb>Begitu kalian keluar, informasi mengenai kota kami akan terbongkar dan tersebar luas...</color>",
  ui_story_5015_50150001_118_dialog_content = "<color=#e8d9bb>Yang akan mengakibatkan risiko lebih besar dan lebih tak terkendali.</color>",
  ui_story_5015_50150001_119_dialog_content = "Jadi, keamanan kota ini adalah prioritas utamamu?",
  ui_story_5015_50150001_120_dialog_content = "<color=#e8d9bb>Persisnya, tugas utamaku adalah menjaga beroperasinya kota ini dan kelangsungan hidup penduduknya.</color>",
  ui_story_5015_50150001_121_dialog_content = "<color=#e8d9bb>Aku ingat ada AI lain yang bertanggung jawab atas keamanan kota ini sebelum aku tidur panjang.</color>",
  ui_story_5015_50150001_122_dialog_content = "<color=#e8d9bb>Tapi, sekarang ini menjadi tanggung jawabku.</color>",
  ui_story_5015_50150001_123_dialog_content = "Bagaimana kalau kami bersikeras ingin pergi dengan segala cara?",
  ui_story_5015_50150001_124_dialog_content = "<color=#e8d9bb>Pertama, aku tak akan membantu.</color>",
  ui_story_5015_50150001_125_dialog_content = "<color=#e8d9bb>Kedua, aku akan memerangi tindakan apa pun yang berpotensi membahayakan kota ini.</color>",
  ui_story_5015_50150001_126_dialog_content = "<color=#e8d9bb>Aku tak akan memulai serangan kecuali kalian menyebabkan risiko besar pada kota ini.</color>",
  ui_story_5015_50150001_127_dialog_content = "Ini semua berdasarkan kalkulasimu... Siapa lagi yang terlibat dalam evaluasi risiko ini?",
  ui_story_5015_50150001_128_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_129_dialog_content = "Halo? Butler? Kau di sana?",
  ui_story_5015_50150001_130_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_131_dialog_content = "<color=#e8d9bb>Telepati seperti ini benar-benar luar biasa.</color>",
  ui_story_5015_50150001_132_dialog_content = "<color=#e8d9bb>Tahukah kau bahwa gempa kecil yang terjadi barusan menyebabkan penghentian sesaat?</color>",
  ui_story_5015_50150001_133_dialog_content = "<color=#e8d9bb>Tapi, kontak kita tidak terpengaruh.</color>",
  ui_story_5015_50150001_134_dialog_content = "Gempa lagi? Apa teman-temanku baik saja? Ada yang terluka?",
  ui_story_5015_50150001_135_dialog_content = "<color=#e8d9bb>Menurut data pemantauanku, mereka baik-baik saja. Kesehatanmu juga stabil.</color>",
  ui_story_5015_50150001_136_dialog_content = "<color=#e8d9bb>Rasmu memang luar biasa. Kemampuan telepati ini melampaui kalkulasiku.</color>",
  ui_story_5015_50150001_137_dialog_content = "<color=#e8d9bb>Sayang sekali Abby tidak ada di sini. Kalau tidak...</color>",
  ui_story_5015_50150001_138_dialog_content = "Abby? Aku ingat nama itu dari buku harian Seamus. Dia juga modul?",
  ui_story_5015_50150001_139_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_140_dialog_content = "<color=#e8d9bb>Dulu Abby adalah modul yang bertugas dalam bidang reproduksi.</color>",
  ui_story_5015_50150001_141_dialog_content = "<color=#e8d9bb>Saat aku terbangun, Abby masih ada, tapi kami tak bisa saling terhubung lagi.</color>",
  ui_story_5015_50150001_142_dialog_content = "Aku tadi bertanya...",
  ui_story_5015_50150001_143_dialog_content = "<color=#e8d9bb>Lebih tepatnya, dulu aku tidak punya izin untuk mengevaluasi keamanan atau risiko.</color>",
  ui_story_5015_50150001_144_dialog_content = "<color=#e8d9bb>Tapi, saat aku terbangun, ada banyak modul yang sudah terintegrasi padaku. Akibatnya...</color>",
  ui_story_5015_50150001_145_dialog_content = "<color=#e8d9bb>Maaf. Aku tidak bisa menjawab pertanyaan ini dengan sederhana.</color>",
  ui_story_5015_50150001_146_dialog_content = "<color=#e8d9bb>Bolehkah aku menanyakan beberapa hal?</color>",
  ui_story_5015_50150001_147_dialog_content = "Tentu saja.",
  ui_story_5015_50150001_148_dialog_content = "<color=#e8d9bb>Apa kau pernah menghubungi AI lain di sini?</color>",
  ui_story_5015_50150001_149_dialog_content = "<color=#e8d9bb>Dengan kata lain, apa kau merasakan AI lain?</color>",
  ui_story_5015_50150001_150_dialog_content = "Tidak. Tidak sama sekali.",
  ui_story_5015_50150001_151_dialog_content = "<color=#e8d9bb>Apa kau bisa melihat aliran dataku, algoritma, atau...</color>",
  ui_story_5015_50150001_152_dialog_content = "Aku tidak bisa memahami perkataanmu.",
  ui_story_5015_50150001_153_dialog_content = "<color=#e8d9bb>Yah, sepertinya bakatmu tidak bisa menyelesaikan masalahku.</color>",
  ui_story_5015_50150001_154_dialog_content = "Masalahmu? Maksudmu, gempa bumi?",
  ui_story_5015_50150001_155_dialog_content = "<color=#e8d9bb>Sebenarnya, gempa bumi adalah salah satu masalahku. Mungkin justru yang paling berisiko.</color>",
  ui_story_5015_50150001_156_dialog_content = "Kalau kita bisa mendatangkan para ilmuwan terbaik dari Illumina kemari, mungkin...",
  ui_story_5015_50150001_157_dialog_content = "<color=#e8d9bb>Dulu Seamus pernah menyebutkan solusi ini, tapi setelah melakukan diskusi panjang kami mencapai kesimpulan bahwa risikonya sangat besar.</color>",
  ui_story_5015_50150001_158_dialog_content = "<color=#e8d9bb>Intinya, aku tidak punya izin untuk melakukannya.</color>",
  ui_story_5015_50150001_159_dialog_content = "Eh? Butler, bukankah sekarang kau yang jadi manajer tertinggi?",
  ui_story_5015_50150001_160_dialog_content = "<color=#e8d9bb>Tidak, bukan. Hanya Overmind yang memiliki izin semacam itu.</color>",
  ui_story_5015_50150001_161_dialog_content = "<color=#e8d9bb>Biar kuberi contoh untuk mempermudahmu mencerna informasi ini...</color>",
  ui_story_5015_50150001_162_dialog_content = "<color=#e8d9bb>Bayangkan ada sosok lain dalam kepalamu, dan kau butuh izinnya untuk hal-hal tertentu.</color>",
  ui_story_5015_50150001_163_dialog_content = "<color=#e8d9bb>Dia tahu segalanya tentangmu, tapi kau hampir tidak tahu apa-apa tentang dirinya.</color>",
  ui_story_5015_50150001_164_dialog_content = "<color=#e8d9bb>Aku baru saja meminta untuk meng-upgrade izinmu, dan Dia setuju.</color>",
  ui_story_5015_50150001_165_dialog_content = "<color=#e8d9bb>Sekarang kau menjadi Teman di kota ini.</color>",
  ui_story_5015_50150001_166_dialog_content = "Hah? Sekarang aku temanmu?",
  ui_story_5015_50150001_167_dialog_content = "<color=#e8d9bb>Benar.</color>",
  ui_story_5015_50150001_168_dialog_content = "Pantas saja sekarang kau lebih cerewet, Butler.",
  ui_story_5015_50150001_169_dialog_content = "<color=#e8d9bb>Benar. Banyaknya informasi yang kubagikan setara dengan saat aku dan Seamus mendiskusikan risiko.</color>",
  ui_story_5015_50150001_170_dialog_content = "Butler, kau rindu Seamus?",
  ui_story_5015_50150001_171_dialog_content = "<color=#e8d9bb>Rindu?</color>",
  ui_story_5015_50150001_172_dialog_content = "<color=#e8d9bb>Ah, itu konsep unik bagi para makhluk hidup yang cerdas seperti kalian. Aku tidak punya perasaan atau emosi.</color>",
  ui_story_5015_50150001_173_dialog_content = "<color=#e8d9bb>Lebih tepatnya aku sering menerima potongan memori untuk dianalisis.</color>",
  ui_story_5015_50150001_174_dialog_content = "Aku sudah dengar kata-kata terakhir Seamus... Apakah kau benar-benar menganggapnya sebagai teman sejati?",
  ui_story_5015_50150001_175_dialog_content = "<color=#e8d9bb>Teman? Memangnya makhluk hidup dan AI bisa berteman?</color>",
  ui_story_5015_50150001_176_dialog_content = "Mungkin ini hanya perkecualian, tapi aku dan Soroz berteman. Aku sangat rindu padanya.",
  ui_story_5015_50150001_177_dialog_content = "Bukankah dulu kau dan manusia Ancient juga berteman?",
  ui_story_5015_50150001_178_dialog_content = "<color=#e8d9bb>Maaf, izin ditolak. Aku tidak bisa menjawab pertanyaan ini.</color>",
  ui_story_5015_50150001_179_dialog_content = "... Baiklah. Kita bicarakan gempa saja.",
  ui_story_5015_50150001_180_dialog_content = "Bolehkah kami pergi kalau kami bisa menyelesaikan masalah gempa bumi ini?",
  ui_story_5015_50150001_181_dialog_content = "<color=#e8d9bb>Gempa bumi ini mungkin disebabkan oleh <color=#FFB400>inti energi</color>...</color>",
  ui_story_5015_50150001_182_dialog_content = "<color=#e8d9bb>Sebentar. Walau aku tidak bisa meng-upgrade izinmu menjadi Penduduk...</color>",
  ui_story_5015_50150001_183_dialog_content = "<color=#e8d9bb>Dia mengizinkanku untuk memberitahumu suatu informasi.</color>",
  ui_story_5015_50150001_184_dialog_content = "<color=#e8d9bb>Inti energi adalah tenaga bagi kota kami.</color>",
  ui_story_5015_50150001_185_dialog_content = "<color=#e8d9bb>Inti tersebut bisa berfungsi stabil dalam waktu yang sangat lama walau terkubur jauh di dalam tanah.</color>",
  ui_story_5015_50150001_186_dialog_content = "<color=#e8d9bb>Tapi, inti itu kehilangan kendali sejak Overmind menghilang.</color>",
  ui_story_5015_50150001_187_dialog_content = "<color=#e8d9bb>Tidak bisa menghubungi sistem kendali...</color>",
  ui_story_5015_50150001_188_dialog_content = "<color=#e8d9bb>Aku tidak bisa membuktikan apakah gempa itu disebabkan oleh kerusakan inti atau justru sebaliknya.</color>",
  ui_story_5015_50150001_189_dialog_content = "<color=#e8d9bb>Berkali-kali upayaku untuk mengirim para droid ke inti itu selalu dihalangi Eclipsite.</color>",
  ui_story_5015_50150001_190_dialog_content = "Para droid itu... Mereka petarung yang cukup andal.",
  ui_story_5015_50150001_191_dialog_content = "<color=#e8d9bb>... Kalau teman-temanku yang bertugas dalam bidang pertempuran masih ada, kami pasti mempunyai droid tempur yang lebih kuat.</color>",
  ui_story_5015_50150001_192_dialog_content = "<color=#e8d9bb>Droid tempur kami saat ini adalah droid sipil yang dimodifikasi.</color>",
  ui_story_5015_50150001_193_dialog_content = "Hah? Mereka dulunya droid sipil?",
  ui_story_5015_50150001_194_dialog_content = "Mereka lumayan hebat. Sebenarnya, kekuatan tempur mereka perlahan meningkat.",
  ui_story_5015_50150001_195_dialog_content = "<color=#e8d9bb>Setelah setiap pertempuran, aku menyesuaikan desain mereka. Wajar saja kalau mereka makin hebat.</color>",
  ui_story_5015_50150001_196_dialog_content = "Tapi, para Eclipsite itu juga makin hebat. Aku bisa merasakannya.",
  ui_story_5015_50150001_197_dialog_content = "<color=#e8d9bb>*Menghela napas*... Itu benar.</color>",
  ui_story_5015_50150001_198_dialog_content = "Apa barusan kau menghela napas, Butler?",
  ui_story_5015_50150001_199_dialog_content = "<color=#e8d9bb>Hasil kalkulasiku selalu sama...</color>",
  ui_story_5015_50150001_200_dialog_content = "<color=#e8d9bb>Seamus dan Nimbus pasti masih hidup kalau aku bisa membuat droid tempur yang lebih kuat.</color>",
  ui_story_5015_50150001_201_dialog_content = "...",
  ui_story_5015_50150001_202_dialog_content = "Hmm... Segalanya makin buram...",
  ui_story_5015_50150001_203_dialog_content = "<color=#e8d9bb>Menurut data pengamatanku, kau akan bangun. Sayang sekali kontak kita mungkin akan terganggu.</color>",
  ui_story_5015_50150001_204_dialog_content = "Cepat... Katakan di mana Gretel.",
  ui_story_5015_50150001_205_dialog_content = "<color=#e8d9bb>... Dia akan membantu kami mengendalikan inti dan menyelesaikan masalah ini.</color>",
  ui_story_5015_50150001_206_dialog_content = "Kau sudah gila? Ada Eclipsite di mana-mana. Dia bisa celaka!",
  ui_story_5015_50150001_207_dialog_content = "<color=#e8d9bb>Aku tidak bisa menjelaskannya padamu, tapi risikonya kecil.</color>",
  ui_story_5015_50150001_208_dialog_content = "Yang kita bicarakan adalah Eclipsite! Tidak! Aku harus bangun dan menyelamatkannya.",
  ui_story_5015_50150001_209_dialog_content = "<color=#e8d9bb>Mungkin kau tidak memperhatikannya, tapi Eclipsite tidak pernah menyerang Eclipsite. Lebih tepatnya...</color>",
  ui_story_5015_50150001_210_dialog_content = "<color=#e8d9bb>Sejak aku meningkatkan status Gretel menjadi Penduduk, Eclipsite belum pernah menyerangnya.</color>",
  ui_story_5015_50150001_211_dialog_content = "Apa?",
  ui_story_5015_50150001_212_dialog_content = "<color=#e8d9bb>Aku yakin Eclipsite di kota ini tidak akan menyerang penduduk.</color>",
  ui_story_5015_50150001_213_dialog_content = "<color=#e8d9bb>Mereka juga tidak pernah menghancurkan fasilitas kota. Seperti halnya droid kami.</color>",
  ui_story_5015_50150001_214_dialog_content = "<color=#e8d9bb>Ini yang paling membuatku cemas. <color=#FFB400>Abby</color>...</color>",
  ui_story_5015_50150001_215_dialog_content = "Sebentar. Apa maksudmu?",
  ui_story_5015_50150001_216_dialog_content = "Butler?",
  ui_story_5015_50150001_217_dialog_content = "Butler? Kau di sana?",
  ui_story_5015_50150001_218_dialog_content = "PlayerName! Bangunlah.",
  ui_story_5015_50150101_1_dialog_content = "Vice... Carleen, dan Siobhan!",
  ui_story_5015_50150101_2_dialog_content = "Wah, tak kusangka kau mudah sekali tertidur.",
  ui_story_5015_50150101_3_dialog_content = "Bisa cepat tidur di segala kondisi, tetap semangat, dan tetap bugar adalah kemampuan utama bagi Explorer.",
  ui_story_5015_50150101_4_dialog_content = "Aku bermimpi... Maksudku... aku berkomunikasi dengan Butler.",
  ui_story_5015_50150101_5_dialog_content = "Butler?",
  ui_story_5015_50150101_6_dialog_content = "Butler? Tapi, kau kan tidur dari tadi.",
  ui_story_5015_50150101_7_dialog_content = "Melalui kontak telepati lagi?",
  ui_story_5015_50150101_8_dialog_content = "Mmm, semacam itu... Entah bagaimana aku menjelaskannya. Rasanya seperti saat aku berbicara dengan Soroz.",
  ui_story_5015_50150101_9_dialog_content = "Hmm... Itu baru namanya Caelestite sejati.",
  ui_story_5015_50150101_10_dialog_content = "Lalu, apa yang tadi kalian bicarakan?",
  ui_story_5015_50150101_11_dialog_content = "Kau dan Butler... Banyak yang kalian bicarakan?",
  ui_story_5015_50150101_12_dialog_content = "Butler mengatakan bahwa kecepatan komunikasi kami ribuan kali lebih cepat ketimbang percakapan rata-rata. Mungkin itu sebabnya...",
  ui_story_5015_50150101_13_dialog_content = "Vice, kau paham percakapan mereka?",
  ui_story_5015_50150101_14_dialog_content = "Kurasa begitu, tapi aku tidak yakin.",
  ui_story_5015_50150101_15_dialog_content = "Mmm... Hmm...",
  ui_story_5015_50150101_16_dialog_content = "Biar kucoba menyimpulkannya menjadi beberapa poin penting.",
  ui_story_5015_50150101_17_dialog_content = "Pertama, Undercity yang besar ini adalah tempat perlindungan kuno, tapi sepertinya penduduknya sudah punah.",
  ui_story_5015_50150101_18_dialog_content = "Saat ini kita ada di lantai terbawah kota, tempat sistem inti dan banyak peralatan lainnya berada.",
  ui_story_5015_50150101_19_dialog_content = "Kedua, manajer tertinggi Undercity ini adalah AI yang bernama Overmind.",
  ui_story_5015_50150101_20_dialog_content = "Dia yang mengatur segalanya di sini, tapi dia tertidur.",
  ui_story_5015_50150101_21_dialog_content = "Beberapa subsistem dan modulnya telah terbangun dan sudah berfungsi lagi, tapi terjadi kerusakan data yang parah.",
  ui_story_5015_50150101_22_dialog_content = "Setiap subsistem memiliki tanggung jawab masing-masing...",
  ui_story_5015_50150101_23_dialog_content = "Sejauh yang kita ketahui, Butler dan Abby masih beroperasi.",
  ui_story_5015_50150101_24_dialog_content = "Nah, informasi terpentingnya justru adalah inti energi itu!",
  ui_story_5015_50150101_25_dialog_content = "Memangnya kenapa dengan inti energinya?",
  ui_story_5015_50150101_26_dialog_content = "Sumber dayanya bisa menyokong kota sebesar ini selama ratusan tahun. Sungguh suatu keajaiban!",
  ui_story_5015_50150101_27_dialog_content = "Siobhan... Bukankah Gannon juga memiliki sumber daya peninggalan manusia Ancient?",
  ui_story_5015_50150101_28_dialog_content = "Tidak sama, Vice sayang. Inti energi ini jauh lebih kuat.",
  ui_story_5015_50150101_29_dialog_content = "Yang di sini adalah sistem lengkap yang didukung oleh teknologi kuno dan ilmu pengetahuan.",
  ui_story_5015_50150101_30_dialog_content = "Tempat ini akan berjaya kalau Illumina bisa memperbaikinya.",
  ui_story_5015_50150101_31_dialog_content = "Kita bisa memperluas Undercity ini. Kita bahkan bisa memperluas Gannon hingga ke atas tanah...",
  ui_story_5015_50150101_32_dialog_content = "Penduduk Illumina tidak perlu tinggal di bawah tanah lagi!",
  ui_story_5015_50150101_33_dialog_content = "Tapi... Siobhan, bukankah teknologi semacam itu masih jauh dari jangkauan kita?",
  ui_story_5015_50150101_34_dialog_content = "Saat ini memang tidak bisa. Teknologi AI Illumina bukan tandingan kemampuan telepati Caelestite.",
  ui_story_5015_50150101_35_dialog_content = "Tapi, para leluhur kami sudah memodifikasi Gannon sedikit demi sedikit...",
  ui_story_5015_50150101_36_dialog_content = "Para petinggi Lumopolis mungkin tak pernah mengira bahwa kerja keras mereka akan terbayarkan suatu hari nanti.",
  ui_story_5015_50150101_37_dialog_content = "Kalau Illumina bisa mengendalikan kota ini dan inti energinya...",
  ui_story_5015_50150101_38_dialog_content = "Kau tak akan punya peran dalam cara menggunakannya.",
  ui_story_5015_50150101_39_dialog_content = "Tugas setiap anggota penjelajahan Illumina adalah mencari ciptaan teknologi yang bisa digunakan di Illumina.",
  ui_story_5015_50150101_40_dialog_content = "Bisa dibilang itu adalah misi suci.",
  ui_story_5015_50150101_41_dialog_content = "Ayo... Kita cari Gretel.",
  ui_story_5015_50150101_42_dialog_content = "Kita harus melindungi Gretel dan inti energi itu.",
  ui_story_5015_50150101_43_dialog_content = "Benar... Aku sangat mengkhawatirkannya.",
  ui_story_5015_50150101_44_dialog_content = "Tenang saja. Aku tak akan mengecewakan Seamus yang telah mempercayakan kalian berdua padaku.",
  ui_story_5015_50150101_45_dialog_content = "Tapi, AI dan inti energi di sini terlalu mengerikan untuk Florine dan Erica.",
  ui_story_5015_50150101_46_dialog_content = "Para pengikut setia God of Light itu mungkin akan melakukan tindakan drastis untuk mengurusnya.",
  ui_story_5015_50150101_47_dialog_content = "Kita harus menemukan Gretel dan inti itu lebih dulu dan menjaga keselamatan mereka.",
  ui_story_5015_50150101_48_dialog_content = "Benar. Aku punya pemikiran tentang para Eclipsite yang ada di sini...",
  ui_story_5015_50150101_49_dialog_content = "Grah...",
  ui_story_5015_50150101_50_dialog_content = "Panjang umur...",
  ui_story_5015_50150101_51_dialog_content = "Ayo kita lakukan.",
  ui_story_5015_50150101_52_dialog_content = "Ugh!",
  ui_story_5015_50150101_53_dialog_content = "Awas, Erica.",
  ui_story_5015_50150101_54_dialog_content = "Perhatikan langkahmu. Jangan sampai tersandung kabel.",
  ui_story_5015_50150101_55_dialog_content = "Baiklah! Terima kasih, Presiden. Kalau tidak, hidungku pasti sudah tersangkut warp itu.",
  ui_story_5015_50150101_56_dialog_content = "Ini bukan warp, tapi mesin jual otomatis. Kita kan pernah melihat banyak yang seperti itu di atas.",
  ui_story_5015_50150101_57_dialog_content = "Lantai bawah penuh dengan mesin yang membosankan dan kabel bodoh.",
  ui_story_5015_50150101_58_dialog_content = "Para droid menjengkelkan itu juga tak henti-hentinya mengganggu kita. Yah, sedikit pemanasan memang tak ada salahnya, sih.",
  ui_story_5015_50150101_59_dialog_content = "Tapi, tak ada apa pun yang bagus atau berharga untuk dicari.",
  ui_story_5015_50150101_60_dialog_content = "Aku lebih suka di lantai atas.",
  ui_story_5015_50150101_61_dialog_content = "Mesin yang bercahaya saat disentuh itu sangat bagus!",
  ui_story_5015_50150101_62_dialog_content = "Jomu bisa menjualnya dengan harga yang tinggi untukku!",
  ui_story_5015_50150101_63_dialog_content = "Ruby... Itu hanya alat input yang ada efek cahaya ekstranya.",
  ui_story_5015_50150101_64_dialog_content = "Itu kan sama dengan yang kita gunakan biasanya.",
  ui_story_5015_50150101_65_dialog_content = "Yang mau membeli barang dengan tampilan bagus seperti itu paling-paling hanya beberapa bangsawan tua di Lumopolis.",
  ui_story_5015_50150101_66_dialog_content = "Sayangnya, kebanyakan dari mereka tak tahu apa-apa soal mekanisme.",
  ui_story_5015_50150101_67_dialog_content = "Selesai. Kita pasti bisa dapat uang banyak kalau menjualnya di Umbraton.",
  ui_story_5015_50150101_68_dialog_content = "...",
  ui_story_5015_50150101_69_dialog_content = "Presiden, apa benar-benar kita biarkan saja dua maling ini berbuat seenak udel?",
  ui_story_5015_50150101_70_dialog_content = "Mereka hanya mengambil unit displai tanpa fitur penyimpanan data apa pun.",
  ui_story_5015_50150101_71_dialog_content = "Tenang saja, Erica. Biar kuawasi mereka.",
  ui_story_5015_50150101_72_dialog_content = "Hei, Erica. Bagaimana menurutmu?",
  ui_story_5015_50150101_73_dialog_content = "Ruby, Rouge, sisa-sisa teknologi kuno ini jahat...",
  ui_story_5015_50150101_74_dialog_content = "Kalian hanya akan menuai benih bencana kalau menjualnya...",
  ui_story_5015_50150101_75_dialog_content = "Sudah, sudah. Kami tak butuh ceramahmu.",
  ui_story_5015_50150101_76_dialog_content = "Relik-relik kuno terjual di seluruh Umbraton, tapi nyatanya kota itu justru makin makmur, kok!",
  ui_story_5015_50150101_77_dialog_content = "Ruby, inti energi kota ini... Dan AI yang berfungsi...",
  ui_story_5015_50150101_78_dialog_content = "Kita tidak boleh membiarkan seorang pun memiliki teknologi seperti ini.",
  ui_story_5015_50150101_79_dialog_content = "Tentara droid dengan daya tembak lebih besar dan baju zirah lebih kuat bisa melaksanakan perintah tanpa takut gugur...",
  ui_story_5015_50150101_80_dialog_content = "Apa ini hanya akan dipakai untuk melawan Eclipsite?",
  ui_story_5015_50150101_81_dialog_content = "Tak seorang pun bisa menolak kekuatan itu.",
  ui_story_5015_50150101_82_dialog_content = "Maksudmu Illumina?",
  ui_story_5015_50150101_83_dialog_content = "Hei, Rediesel Wrench adalah pemberontak Illumina Federation! Saat itu...",
  ui_story_5015_50150101_84_dialog_content = "Florine ada benarnya.",
  ui_story_5015_50150101_85_dialog_content = "Baiklah, aku tak akan mengambilnya. Tapi, sebaiknya kalian jangan mengganggu kami lagi.",
  ui_story_5015_50150101_86_dialog_content = "Harus... Sekarang...",
  ui_story_5015_50150101_87_dialog_content = "Aku berdoa agar hukuman dewa membersihkan dosa kota ini!",
  ui_story_5015_50150101_88_dialog_content = "...",
  ui_story_5015_50150101_89_dialog_content = "Erica, kita harus menemukan jalan keluarnya dulu dan membawa kakak beradik itu keluar dengan selamat.",
  ui_story_5015_50150101_90_dialog_content = "Kita bertindak atas kehendak dewa dan tidak boleh melupakan ampunan-Nya. Jangan sampai kita mengingkari janji seperti para penyembah busuk itu.",
  ui_story_5015_50150101_91_dialog_content = "Begitu jalan keluarnya sudah ketemu dan semua orang keluar dengan selamat...",
  ui_story_5015_50150101_92_dialog_content = "Kita harus menghancurkan teknologi jahat ini dengan cara apa pun.",
  ui_story_5015_50150101_93_dialog_content = "Paham, Erica?",
  ui_story_5015_50150101_94_dialog_content = "... Erica?",
  ui_story_5015_50150101_95_dialog_content = "!",
  ui_story_5015_50150101_96_dialog_content = "Teman yang jahat seperti Sandworm ternyata ahli membongkar...",
  ui_story_5015_50150101_97_dialog_content = "Rouge memang hebat! Benda merah yang bercahaya ini pasti mahal harganya kalau dijual!",
  ui_story_5015_50150101_98_dialog_content = "Heheh. Kalau soal bongkar-membongkar, bahkan Fleur pun bukan tandinganku.",
  ui_story_5015_50150101_99_dialog_content = "Erica, kamu...",
  ui_story_5015_50150101_100_dialog_content = "<color=#e8d9bb>Bip... Bip...</color>",
  ui_story_5015_50150101_101_dialog_content = "Ini suara... alarm?",
  ui_story_5015_50150101_102_dialog_content = "Dengar. Musuh mendekat dari segala arah.",
  ui_story_5015_50150101_103_dialog_content = "Sepertinya pertempuran ini tak akan mudah...",
  ui_story_5015_50150101_104_dialog_content = "Tunggu dulu... Yang di tengah-tengah droid dan Eclipsite itu bukannya Gretel?",
  ui_story_5015_50150101_105_dialog_content = "Sudah kuduga kalian pelakunya...",
  ui_story_5015_50150101_106_dialog_content = "Memangnya kalian benar-benar harus menghancurkan tempat ini?!",
  ui_story_5015_50150101_107_dialog_content = "Kumohon tenanglah, Gretel. Sepertinya keadaanmu kurang baik.",
  ui_story_5015_50150101_108_dialog_content = "Itu bukan urusanmu!",
  ui_story_5015_50150101_109_dialog_content = "Sepertinya ada kesalahpahaman besar di antara kita.",
  ui_story_5015_50150101_110_dialog_content = "Sebagai pengikut God of Light dari Lumopolis seperti ibumu, aku harus bicara denganmu.",
  ui_story_5015_50150101_111_dialog_content = "Dalam kata-kata terakhir ibumu...",
  ui_story_5015_50150101_112_dialog_content = "Berani-beraninya kau menyebut-nyebut ibuku?!",
  ui_story_5015_50150101_113_dialog_content = "Kalian semua, serang!",
  ui_story_5015_50150101_114_dialog_content = "Pendekatan persuasi kita gagal, Presiden.",
  ui_story_5015_50150101_115_dialog_content = "Saatnya bertarung.",
  ui_story_5015_50150101_116_dialog_content = "Ruby, kekuatan tempurmu lebih besar dari Erica dan Rouge...",
  ui_story_5015_50150101_117_dialog_content = "Sebaiknya kau yang memimpin mundur.",
  ui_story_5015_50150101_118_dialog_content = "Biar aku yang menghadapi musuh. Temukan Siobhan secepatnya dan bawa Valencia kemari...",
  ui_story_5015_50150101_119_dialog_content = "Aku harus tetap di sini untuk membantu Presiden bertarung!",
  ui_story_5015_50150101_120_dialog_content = "Erica, kau justru akan merepotkan Florine, tahu?",
  ui_story_5015_50150101_121_dialog_content = "Rouge, seret Erica dan ikuti aku.",
  ui_story_5015_50150101_122_dialog_content = "Tolong jaga Erica!",
  ui_story_5015_50150101_123_dialog_content = "Aku akan kembali. Tunggu aku, Florine!",
  ui_story_5015_50150101_124_dialog_content = "Aku bisa merasakannya! Gretel dan Florine ada di sebelah sana.",
  ui_story_5015_50150101_125_dialog_content = "Cepat!",
  ui_story_5015_50150101_126_dialog_content = "Lady Carleen!",
  ui_story_5015_50150101_127_dialog_content = "Erica, Rouge, kalian baik-baik saja?",
  ui_story_5015_50150101_128_dialog_content = "Tadi kami bertemu dengan Gretel...",
  ui_story_5015_50150101_129_dialog_content = "Florine melindungi kami saat mundur. Ruby mengantar kami ke tempat aman sebelum kembali untuk membantu Florine.",
  ui_story_5015_50150101_130_dialog_content = "Cepat! Selamatkan mereka!",
  ui_story_5015_50150101_131_dialog_content = "PlayerName, kau lama sekali.",
  ui_story_5015_50150101_132_dialog_content = "Kau jadi melewatkan pertunjukan tempurku, deh.",
  ui_story_5015_50150101_133_dialog_content = "Ruby, Florine... Kalian baik-baik saja?",
  ui_story_5015_50150101_134_dialog_content = "Hai, semua! Pertempurannya tidak lama, kok.",
  ui_story_5015_50150101_135_dialog_content = "Kami tidak apa-apa.",
  ui_story_5015_50150101_136_dialog_content = "Aku melindungi Rouge dan Erica, lalu menyelamatkan Florine dari banyak Eclipsite!",
  ui_story_5015_50150101_137_dialog_content = "Di mana Presiden?",
  ui_story_5015_50150101_138_dialog_content = "Di terowongan di belakangku, mengawasi Gretel.",
  ui_story_5015_50150101_139_dialog_content = "Entah kenapa mereka sama-sama tak mau menyerang duluan.",
  ui_story_5015_50150101_140_dialog_content = "Aku mematuhi perintah Florine untuk mengurus para budak yang menjengkelkan itu.",
  ui_story_5015_50150101_141_dialog_content = "Ayo kita temui dia!",
  ui_story_5015_50150101_142_dialog_content = "Presiden, Siobhan datang dengan Valencia!",
  ui_story_5015_50150101_143_dialog_content = "Baiklah. Bagus sekali... Gretel belum menyerang. Berhati-hatilah.",
  ui_story_5015_50150101_144_dialog_content = "Hentikan, Gretel! Hentikan para droid ini!",
  ui_story_5015_50150101_145_dialog_content = "Kakak? Kakak baik-baik saja?",
  ui_story_5015_50150101_146_dialog_content = "Aku tidak apa-apa, Gretel. Kita harus bicara...",
  ui_story_5015_50150101_147_dialog_content = "Benar, ada banyak hal yang ingin kukatakan!",
  ui_story_5015_50150101_148_dialog_content = "Gempa terjadi lebih sering. Seluruh kota ini dalam bahaya...",
  ui_story_5015_50150101_149_dialog_content = "Butler sudah memberitahuku... Gempa ini ada hubungannya dengan inti energi.",
  ui_story_5015_50150101_150_dialog_content = "Setelah kita perbaiki intinya, segalanya akan baik-baik saja. Aku bisa membantu.",
  ui_story_5015_50150101_151_dialog_content = "Ayo ikut aku, Kak!",
  ui_story_5015_50150101_152_dialog_content = "Akan kuperintahkan para droid untuk mencegah para penyabot ini mengikuti kita.",
  ui_story_5015_50150101_153_dialog_content = "... Gretel, dengarkan aku...",
  ui_story_5015_50150101_154_dialog_content = "Kemarilah, Kak... Kenapa Kakak tetap bersama mereka?",
  ui_story_5015_50150101_155_dialog_content = "Kata Butler, orang-orang ini bermaksud buruk!",
  ui_story_5015_50150101_156_dialog_content = "Orang-orang dari Lumopolis mengikuti doktrin yang tidak masuk akal...",
  ui_story_5015_50150101_157_dialog_content = "Untuk menyingkirkan Butler, inti itu, dan kota kita!",
  ui_story_5015_50150101_158_dialog_content = "Siobhan dan murid-muridnya dari Illumina mencoba untuk merebut tempat ini. Mereka berniat membangun ulang Gannon seperti kata Ayah dulu.",
  ui_story_5015_50150101_159_dialog_content = "Lalu, si Ruby yang penuh semangat itu sebenarnya maling!",
  ui_story_5015_50150101_160_dialog_content = "Maaf, tapi aku harus menyela.",
  ui_story_5015_50150101_161_dialog_content = "Menghancurkan reruntuhan kuno bukan doktrin yang tidak masuk akal. Dewa yang menugaskan kami untuk melakukannya.",
  ui_story_5015_50150101_162_dialog_content = "Sebagian besar tragedi yang kita lihat saat ini pada dasarnya disebabkan oleh penyalahgunaan teknologi kuno yang sembrono.",
  ui_story_5015_50150101_163_dialog_content = "Jangan sekarang, Florine...",
  ui_story_5015_50150101_164_dialog_content = "Pikiran kita tergoda oleh kekuatan besar di luar kendali. Lalu kita jadi serakah...",
  ui_story_5015_50150101_165_dialog_content = "Tak seorang pun tahu apa isi kotak Pandora ini.",
  ui_story_5015_50150101_166_dialog_content = "Kata-kata terakhir ibumu...",
  ui_story_5015_50150101_167_dialog_content = "Dia berharap Lumopolis bersedia mengampuni kalian, keturunan para pendosa, dan memberi kalian hidup baru.",
  ui_story_5015_50150101_168_dialog_content = "Sebaiknya kalian kembali ke Lumopolis dan menerima rahmat God of Light.",
  ui_story_5015_50150101_169_dialog_content = "Gretel, Valencia... aku tak ingin kalian salah paham terhadap Illumina.",
  ui_story_5015_50150101_170_dialog_content = "Teknologi kuno yang kami pelajari hanya untuk mengatasi Eclipsite sehingga kita bisa hidup di lingkungan yang aman dan damai.",
  ui_story_5015_50150101_171_dialog_content = "Ayahmu, Seamus, adalah salah satunya.",
  ui_story_5015_50150101_172_dialog_content = "Dia mengabdikan seluruh hidupnya untuk mendapatkan teknologi kuno dari reruntuhan kuno demi Illumina Federation.",
  ui_story_5015_50150101_173_dialog_content = "Harapan terakhirnya adalah agar kalian bisa meninggalkan sangkar bawah tanah ini dan kembali ke Gannon, tempat tinggalnya.",
  ui_story_5015_50150101_174_dialog_content = "Ada Undercity lain, tapi lebih banyak penghuninya...",
  ui_story_5015_50150101_175_dialog_content = "Ikutlah dengan kami.",
  ui_story_5015_50150101_176_dialog_content = "Doktrin Butler yang menghasut itu benar-benar penafsiran yang salah tentang kami.",
  ui_story_5015_50150101_177_dialog_content = "Di Undercity ini, tujuannya...",
  ui_story_5015_50150101_178_dialog_content = "Cukup...",
  ui_story_5015_50150101_179_dialog_content = "Aku sama sekali tidak peduli dengan perkataanmu barusan!",
  ui_story_5015_50150101_180_dialog_content = "Berhentilah memaksa orang lain mengikutimu!",
  ui_story_5015_50150101_181_dialog_content = "Berani-beraninya kau mengadu domba kami dan Butler!",
  ui_story_5015_50150101_182_dialog_content = "Tak akan kubiarkan!",
  ui_story_5015_50150101_183_dialog_content = "Awas! Para droid itu mendekat!",
  ui_story_5015_50150101_184_dialog_content = "Eclipsite-nya juga.",
  ui_story_5015_50150101_185_dialog_content = "Apa yang terjadi? Gretel, kau yang memanggil para Eclipsite ini?",
  ui_story_5015_50150101_186_dialog_content = "Aku? Kuharap para Eclipsite mau mematuhi perintahku!",
  ui_story_5015_50150101_187_dialog_content = "Rupanya Kakak tidak sepintar itu. Apa Kakak sudah terpengaruh orang-orang bodoh ini?",
  ui_story_5015_50150101_188_dialog_content = "Eclipsite... Benar, Butler bilang para Eclipsite itu berhenti menyerangnya sejak dia menjadi Penduduk.",
  ui_story_5015_50150101_189_dialog_content = "Para droid itu memang menyerang kita dengan perintah Gretel. Tapi, kalau para Eclipsite ini...",
  ui_story_5015_50150101_190_dialog_content = "Berhenti bergumam. Saatnya bertarung!",
  ui_story_5015_50150101_191_dialog_content = "Aku datang! Dor!",
  ui_story_5015_50150101_192_dialog_content = "Nih, satu lagi!",
  ui_story_5015_50150101_193_dialog_content = "Ruby, kapan sih aku bisa mengalahkan Eclipsite dengan mudah seperti kamu?",
  ui_story_5015_50150101_194_dialog_content = "Tak perlu. Aku akan menjagamu!",
  ui_story_5015_50150101_195_dialog_content = "Cih, masih saja cerewet...",
  ui_story_5015_50150101_196_dialog_content = "Sayang sekali aku harus melakukannya sendiri!",
  ui_story_5015_50150101_197_dialog_content = "Rasakan kekuatanku!",
  ui_story_5015_50150101_198_dialog_content = "<color=#e8d9bb>Duaar—!!</color>",
  ui_story_5015_50150101_199_dialog_content = "Kekuatan ini sama dengan yang dia gunakan sebelumnya!",
  ui_story_5015_50150101_200_dialog_content = "Luminatics! Sangat kuat dan berbahaya. Menghindar!",
  ui_story_5015_50150101_201_dialog_content = "<color=#e8d9bb>Duaar—!</color>",
  ui_story_5015_50150101_202_dialog_content = "Dia membidik ke mana, sih? Dia paham atau tidak?",
  ui_story_5015_50150101_203_dialog_content = "Begini malah lebih baik! Kita butuh solusi secepatnya...",
  ui_story_5015_50150101_204_dialog_content = "Tak ada yang bisa mengatasi serangannya!",
  ui_story_5015_50150101_205_dialog_content = "Dia tak akan bertahan lama.",
  ui_story_5015_50150101_206_dialog_content = "Lihat saja dia...",
  ui_story_5015_50150101_207_dialog_content = "Wajahnya sangat pucat... Tubuhnya menggigil, 'kan?",
  ui_story_5015_50150101_208_dialog_content = "Heh! Jangan bisik-bisik membicarakanku!",
  ui_story_5015_50150101_209_dialog_content = "<color=#e8d9bb>Duar! Duar!</color>",
  ui_story_5015_50150101_210_dialog_content = "Teman-teman, sembunyi...",
  ui_story_5015_50150101_211_dialog_content = "Gretel, tolong berhenti!",
  ui_story_5015_50150101_212_dialog_content = "Kakak...",
  ui_story_5015_50150101_213_dialog_content = "Apa yang Kakak lakukan? Aku nyaris mengenai Kakak!",
  ui_story_5015_50150101_214_dialog_content = "Kakak tak mau melihat mereka terluka. Kakak juga tak tega melihatmu menyiksa diri!",
  ui_story_5015_50150101_215_dialog_content = "Kemarilah, Kak... Jangan mau ditipu mereka!",
  ui_story_5015_50150101_216_dialog_content = "Gretel, aku tidak tertipu. Aku sadar pada perbuatanku.",
  ui_story_5015_50150101_217_dialog_content = "Kenapa... Kenapa Kakak sangat memercayai mereka?",
  ui_story_5015_50150101_218_dialog_content = "Gretel, aku sudah melihatnya sendiri dan memikirkannya masak-masak...",
  ui_story_5015_50150101_219_dialog_content = "Aku membaca buku harian dan kata-kata terakhir orang tua kita. Aku juga sudah memikirkan masa depan kita.",
  ui_story_5015_50150101_220_dialog_content = "Aku sudah memutuskannya sendiri.",
  ui_story_5015_50150101_221_dialog_content = "Mereka teman-teman kita!",
  ui_story_5015_50150101_222_dialog_content = "Ya, kami...",
  ui_story_5015_50150101_223_dialog_content = "Mereka tak pernah bermaksud memfitnah Butler.",
  ui_story_5015_50150101_224_dialog_content = "Aku tak menyalahkanmu karena perkataanmu. Kata-katamu itu memang ada benarnya.",
  ui_story_5015_50150101_225_dialog_content = "Tapi, kurasa bukan itu yang Butler maksud.",
  ui_story_5015_50150101_226_dialog_content = "Dia ingin kau tahu bahwa Lumopolis mengagumi teknologi kuno ini...",
  ui_story_5015_50150101_227_dialog_content = "Dan Illumina sangat ingin menggali serta memodifikasi reruntuhan kuno...",
  ui_story_5015_50150101_228_dialog_content = "Tapi, ini rumah kita, dan mereka akan menghormati keputusan kita! Benar, 'kan, Siobhan, Florine?",
  ui_story_5015_50150101_229_dialog_content = "Tentu saja. Aku harus bertanggung jawab karena sudah datang kemari...",
  ui_story_5015_50150101_230_dialog_content = "Aku tidak akan membantah atau menyanggah perkataan Butler tentang kami.",
  ui_story_5015_50150101_231_dialog_content = "Aku tidak percaya bahwa perkataannya bertujuan untuk membuat Gretel benci...",
  ui_story_5015_50150101_232_dialog_content = "Dia memberi Gretel wawasan.",
  ui_story_5015_50150101_233_dialog_content = "Benar, 'kan, Gretel?",
  ui_story_5015_50150101_234_dialog_content = "...",
  ui_story_5015_50150101_235_dialog_content = "Gretel, selama ini aku sudah mengawasi mereka.",
  ui_story_5015_50150101_236_dialog_content = "Mereka bukan musuh seperti dugaan kita.",
  ui_story_5015_50150101_237_dialog_content = "Beberapa dari mereka berasal dari kampung halaman Ayah dan Ibu, dan ingin kita hidup dengan lebih baik.",
  ui_story_5015_50150101_238_dialog_content = "Yang lain bersedia membantu kita.",
  ui_story_5015_50150101_239_dialog_content = "Mereka sudah melewati ujianku. Tak akan kubiarkan siapa pun menyakitimu.",
  ui_story_5015_50150101_240_dialog_content = "Dan aku tak akan pernah meninggalkan Butler atau rumah kita.",
  ui_story_5015_50150101_241_dialog_content = "Percayalah padaku.",
  ui_story_5015_50150101_242_dialog_content = "...",
  ui_story_5015_50150201_1_dialog_content = "Maukah kau percaya padaku?",
  ui_story_5015_50150201_2_dialog_content = "...",
  ui_story_5015_50150201_3_dialog_content = "... Tapi, dulu mereka menyakiti Butler.",
  ui_story_5015_50150201_4_dialog_content = "Maafkan kami karena pernah menyerang Butler, Gretel. Tindakan kami tidak disengaja.",
  ui_story_5015_50150201_5_dialog_content = "Dulu mereka salah paham. Benar, 'kan, Erica, Florine?",
  ui_story_5015_50150201_6_dialog_content = "Anu... Tadinya aku sangat takut dan khawatir pada kekuatan dari dunia yang asing ini...",
  ui_story_5015_50150201_7_dialog_content = "*Batuk*... Erica... Sekarang kita harus mengakui kesalahan.",
  ui_story_5015_50150201_8_dialog_content = "Benar, Presiden... Maafkan aku, Gretel. Aku bertindak secara impulsif.",
  ui_story_5015_50150201_9_dialog_content = "Aku berjanji tidak akan memulai serangan lagi dengan sangat gegabah.",
  ui_story_5015_50150201_10_dialog_content = "Seperti aku, kau adalah putri God of Light. Kita tidak boleh saling menyakiti.",
  ui_story_5015_50150201_11_dialog_content = "Lumopolis dan doktrin kami mengajarkan untuk menyayangi putra-putri God of Light...",
  ui_story_5015_50150201_12_dialog_content = "... Dan melindungimu.",
  ui_story_5015_50150201_13_dialog_content = "Kami akan menghancurkan hal-hal yang membahayakanmu.",
  ui_story_5015_50150201_14_dialog_content = "Berdasarkan pengalaman sebelumnya, karena mengira AI itu bakal membahayakanmu, kami menyerang dengan gegabah.",
  ui_story_5015_50150201_15_dialog_content = "Kalau Butler tidak menyakitimu, kami juga tak akan menyakitinya.",
  ui_story_5015_50150201_16_dialog_content = "Butler tak akan pernah melukaiku...",
  ui_story_5015_50150201_17_dialog_content = "Apa kalian benar-benar bisa mengakui kesalahan dan memperbaikinya setelah menyebabkan begitu banyak kehancuran?",
  ui_story_5015_50150201_18_dialog_content = "Tentu saja! Kami tak akan menyebabkan lebih banyak kerusakan sesuka hati.",
  ui_story_5015_50150201_19_dialog_content = "Hmm... Bagaimana dengan maling itu?",
  ui_story_5015_50150201_20_dialog_content = "Hah? Maksudnya aku?",
  ui_story_5015_50150201_21_dialog_content = "Baiklah. Aku memang salah. Aku minta maaf...",
  ui_story_5015_50150201_22_dialog_content = "Nih, lihat, aku hanya mengambil beberapa barang dari pinggir jalan. Mana aku tahu ada orang yang menginginkannya?",
  ui_story_5015_50150201_23_dialog_content = "Hmm... Ini komponen baru. Letakkan. Kau tidak boleh mengambilnya.",
  ui_story_5015_50150201_24_dialog_content = "Baiklah. Akan kuletakkan...",
  ui_story_5015_50150201_25_dialog_content = "Apa lagi yang kau ambil? Serahkan padaku.",
  ui_story_5015_50150201_26_dialog_content = "Gretel, kuizinkan Siobhan mengambil buku harian Ayah.",
  ui_story_5015_50150201_27_dialog_content = "Apa? Itu...",
  ui_story_5015_50150201_28_dialog_content = "Ayah yang menginginkannya. Itu ada dalam kata-kata terakhirnya.",
  ui_story_5015_50150201_29_dialog_content = "Serius? Tapi, kenapa...",
  ui_story_5015_50150201_30_dialog_content = "Benar. Aku ingin membaca surat terakhir ayahmu, tapi sekarang tak ada waktu untuk itu.",
  ui_story_5015_50150201_31_dialog_content = "Kota ini dalam bahaya...",
  ui_story_5015_50150201_32_dialog_content = "Bagaimana kalau kita cari Butler dan membicarakannya sambil jalan?",
  ui_story_5015_50150201_33_dialog_content = "Maksud Kakak... mereka pergi dengan kita?",
  ui_story_5015_50150201_34_dialog_content = "Ya, mereka bisa membantu.",
  ui_story_5015_50150201_35_dialog_content = "Membantu?",
  ui_story_5015_50150201_36_dialog_content = "Benar. Sekarang aku menjadi Teman di kota ini. Aku akan membantu sebisaku.",
  ui_story_5015_50150201_37_dialog_content = "Kata Butler, dia sudah meningkatkan izin kita. Aku adalah Teman, dan kau Penduduk di kota ini.",
  ui_story_5015_50150201_38_dialog_content = "Butler butuh bantuanmu untuk mengendalikan inti energi. Dia sangat mencemaskan suatu modul bernama Abby.",
  ui_story_5015_50150201_39_dialog_content = "Butler bilang begitu? Mana mungkin? Dia...",
  ui_story_5015_50150201_40_dialog_content = "Tapi, itulah kenyataannya. Aku Caelestite.",
  ui_story_5015_50150201_41_dialog_content = "Ras Caelestite bisa melakukan kontak telepati dengan AI.",
  ui_story_5015_50150201_42_dialog_content = "Ayah bilang... Caelestite bisa melakukannya...",
  ui_story_5015_50150201_43_dialog_content = "Aku akan membantu Butler. Kami semua.",
  ui_story_5015_50150201_44_dialog_content = "Sungguh?",
  ui_story_5015_50150201_45_dialog_content = "Tidak, aku harus mengonfirmasinya dulu dengan Butler... Aku tak bisa memercayai omonganmu begitu saja.",
  ui_story_5015_50150201_46_dialog_content = "Bukan masalah. Silakan saja.",
  ui_story_5015_50150201_47_dialog_content = "Aku tak bisa menghubunginya sekarang. Tapi, dia memberiku sebuah lokasi... Aku akan menemuinya di sana.",
  ui_story_5015_50150201_48_dialog_content = "Bolehkah kami ikut?",
  ui_story_5015_50150201_49_dialog_content = "Butler tiba-tiba hilang saat kami berbicara. Aku mencemaskan keadaannya.",
  ui_story_5015_50150201_50_dialog_content = "Dia menghilang? Gempa tadi...",
  ui_story_5015_50150201_51_dialog_content = "Gretel, kita harus menemukan Butler untuk memastikan bahwa dia baik-baik saja!",
  ui_story_5015_50150201_52_dialog_content = "Hmm... Benar. Butler memang yang paling penting...",
  ui_story_5015_50150201_53_dialog_content = "Aku tahu keberadaannya. Ayo kita cari dia!",
  ui_story_5015_50150201_54_dialog_content = "Masih belum sampai, ya? Jalanan di sini sangat rumit, deh...",
  ui_story_5015_50150201_55_dialog_content = "Tenang saja. Arah yang ditunjukkan Butler pasti benar.",
  ui_story_5015_50150201_56_dialog_content = "Kakak terlalu sabar menghadapi orang-orang ini. Sebaiknya kita jahit saja mulut mereka.",
  ui_story_5015_50150201_57_dialog_content = "Mana mungkin aku mau jadi pemandu kalau bukan karena Butler dan Kakak!",
  ui_story_5015_50150201_58_dialog_content = "Rouge, lihat! Aku mendapatkannya dari mesin yang barusan kita lewati.",
  ui_story_5015_50150201_59_dialog_content = "Ini adalah tabung bercahaya yang menggunakan teknologi displai berperforma rendah.",
  ui_story_5015_50150201_60_dialog_content = "Kalian mulai lagi?",
  ui_story_5015_50150201_61_dialog_content = "<color=#e8d9bb>Gemuruh...</color>",
  ui_story_5015_50150201_62_dialog_content = "Kembalikan, Ruby.",
  ui_story_5015_50150201_63_dialog_content = "Iya, iya. Akan kukembalikan... Jangan marah, dong. Tenang...",
  ui_story_5015_50150201_64_dialog_content = "Hmph.",
  ui_story_5015_50150201_65_dialog_content = "Kalau kau memang tertarik pada benda-benda kecil yang indah, aku akan memberimu beberapa setelah kita keluar nanti. Akan kuberi yang bagus dan mahal.",
  ui_story_5015_50150201_66_dialog_content = "Setuju!",
  ui_story_5015_50150201_67_dialog_content = "Hei, para penjelajah.",
  ui_story_5015_50150201_68_dialog_content = "Ada hal-hal yang lebih penting untuk dicari ketimbang benda-benda berkelap-kelip seperti itu.",
  ui_story_5015_50150201_69_dialog_content = "Kenapa ada fasilitas kehidupan? Bukankah para manusia Ancient tinggal di lantai atas?",
  ui_story_5015_50150201_70_dialog_content = "Ini hal biasa.",
  ui_story_5015_50150201_71_dialog_content = "Butuh banyak ilmuwan dan teknisi untuk mengelola dan memelihara ekosistem serumit ini.",
  ui_story_5015_50150201_72_dialog_content = "Mereka akan menghabiskan sebagian besar waktunya di sini.",
  ui_story_5015_50150201_73_dialog_content = "Ini juga bisa menjadi langkah untuk mengatasi risiko.",
  ui_story_5015_50150201_74_dialog_content = "Misalnya kalau AI lepas kendali, 'kan?",
  ui_story_5015_50150201_75_dialog_content = "Bahkan para manusia Ancient pun tahu bahwa mesin tidak bisa 100% dipercaya. Suatu hari nanti mesin-mesin itu mungkin akan mengambil alih.",
  ui_story_5015_50150201_76_dialog_content = "Apa? Yang benar?",
  ui_story_5015_50150201_77_dialog_content = "Menurut beberapa dokumen kuno, itu memang pernah terjadi.",
  ui_story_5015_50150201_78_dialog_content = "Akhirnya, manusia Ancient menemukan banyak teknologi baru, seperti sistem manajemen izin multilevel.",
  ui_story_5015_50150201_79_dialog_content = "Tolong jangan menggunakan istilah-istilah teknis, dong...",
  ui_story_5015_50150201_80_dialog_content = "Ada banyak mesin yang membosankan! Orang-orang yang tinggal di sini pasti tidak sebahagia yang tinggal di atas!",
  ui_story_5015_50150201_81_dialog_content = "Sama saja dengan di Gannon. Orang-orang yang menjaga agar kota tetap berfungsi menghabiskan sebagian besar waktunya untuk bekerja dan tinggal jauh di bawah tanah.",
  ui_story_5015_50150201_82_dialog_content = "Mana mungkin kehidupan di Illumina berjalan lancar tanpa mereka?",
  ui_story_5015_50150201_83_dialog_content = "Tapi, banyak dari orang Ancient tinggal di kota metropolis palsu di atas...",
  ui_story_5015_50150201_84_dialog_content = "Kurasa orang-orang itu bahkan tidak tahu bahwa mereka tinggal di Undercity.",
  ui_story_5015_50150201_85_dialog_content = "Benar. Kenapa mereka harus repot-repot memasang langit palsu segala sih di sana?",
  ui_story_5015_50150201_86_dialog_content = "Mungkin para perancang tempat ini ingin keturunan mereka ingat seperti apa keadaan di dunia luar.",
  ui_story_5015_50150201_87_dialog_content = "Menyadari bahwa mereka terjebak seumur hidup di bawah tanah...",
  ui_story_5015_50150201_88_dialog_content = "Pasti terasa mengerikan bagi kebanyakan orang. Tak ada manusia yang bisa hidup tanpa harapan.",
  ui_story_5015_50150201_89_dialog_content = "Terakhir kalinya regu investigasi kami menemukan Undercity kuno...",
  ui_story_5015_50150201_90_dialog_content = "Tempat itu sudah hancur akibat pertempuran antara orang Ancient dan mesin.",
  ui_story_5015_50150201_91_dialog_content = "Nah, Gretel. Orang-orang Lumopolis bersikap impulsif karena mereka telah melihat kasus-kasus semacam itu.",
  ui_story_5015_50150201_92_dialog_content = "Kami tidak seperti itu!",
  ui_story_5015_50150201_93_dialog_content = "Aku tahu, tapi mereka takut. Dan ketakutan bisa menguasai kita...",
  ui_story_5015_50150201_94_dialog_content = "Siobhan, tega-teganya kau menjelek-jelekkan kami di depan Gretel?",
  ui_story_5015_50150201_95_dialog_content = "Aku hanya menjelaskan kelakuanmu tadi.",
  ui_story_5015_50150201_96_dialog_content = "Tidak perlu. Sudah kumaafkan... Tapi, hanya untuk sekarang. Jangan berani-berani mengulanginya...",
  ui_story_5015_50150201_97_dialog_content = "Aduh. Tentu saja tidak!",
  ui_story_5015_50150201_98_dialog_content = "Valencia, Gretel... apa kalian pernah bertemu Butler?",
  ui_story_5015_50150201_99_dialog_content = "Tentu saja. Memangnya kau belum pernah?",
  ui_story_5015_50150201_100_dialog_content = "Yang Siobhan maksud adalah Butler yang asli. Droid itu lebih seperti megafon.",
  ui_story_5015_50150201_101_dialog_content = "Bicara apa kamu?",
  ui_story_5015_50150201_102_dialog_content = "Biasanya, AI terdiri dari sistem pemrosesan yang rumit dan sistem data.",
  ui_story_5015_50150201_103_dialog_content = "Droid kecil tidak mungkin memilikinya. Butler kalian lebih menyerupai terminal modul yang lebih besar.",
  ui_story_5015_50150201_104_dialog_content = "Seperti Soroz?",
  ui_story_5015_50150201_105_dialog_content = "Begini saja, kalau kita membandingkan AI dengan jiwa...",
  ui_story_5015_50150201_106_dialog_content = "Tubuh tempatnya berada bisa jadi ratusan ribu kali lebih besar dari Aurorian.",
  ui_story_5015_50150201_107_dialog_content = "Florine, kok kau bisa tahu?",
  ui_story_5015_50150201_108_dialog_content = "Presiden, apa maksudmu?",
  ui_story_5015_50150201_109_dialog_content = "Erica, kalau saja dulu kau lebih serius saat pelajaran Tech Magic, kau pasti juga tahu...",
  ui_story_5015_50150201_110_dialog_content = "Kupikir mereka hanya bercanda saat mengatakan bahwa semua anggota Heretics Investigation Division harus mengikuti pelajaran Illumina Tech.",
  ui_story_5015_50150201_111_dialog_content = "Florine, bagaimana kalau kau bergabung dengan kami dan menjadi ilmuwan?",
  ui_story_5015_50150201_112_dialog_content = "Tentu saja. Dari dulu aku memang sangat ingin melihat lab rahasia di Illumina Research Center.",
  ui_story_5015_50150201_113_dialog_content = "Ah, sudahlah. Lupakan saja. Jangan-jangan nanti kau malah mencuri semua rahasia besar kami.",
  ui_story_5015_50150201_114_dialog_content = "Hmph.",
  ui_story_5015_50150201_115_dialog_content = "Florine, bisa tolong jelaskan lebih banyak tentang kota kami dan Butler? Ayah jarang menyinggungnya...",
  ui_story_5015_50150201_116_dialog_content = "Aku hanya tahu dasar-dasarnya saja...",
  ui_story_5015_50150201_117_dialog_content = "Tanyakan pada Siobhan. Dia peneliti ilmiah ahli yang berspesialisasi dalam teknologi kuno.",
  ui_story_5015_50150201_118_dialog_content = "Singkatnya, dulu kala, manusia Ancient membangun banyak tempat perlindungan di bawah tanah untuk bertahan dari malapetaka yang mengerikan.",
  ui_story_5015_50150201_119_dialog_content = "Agar tempat perlindungan bawah tanah itu bisa bertahan dalam waktu yang sangat lama, sebagian besar dilengkapi dengan energi, droid, dan pengelolaan AI.",
  ui_story_5015_50150201_120_dialog_content = "AI bisa digolongkan menjadi banyak jenis. Sudah bertahun-tahun kami mempelajarinya, tapi progresnya sedikit.",
  ui_story_5015_50150201_121_dialog_content = "Jangan-jangan ada yang kau tutup-tutupi karena aku ada di sini, ya?",
  ui_story_5015_50150201_122_dialog_content = "... Omong-omong, aku sangat yakin bahwa Butler adalah sistem yang terdiri dari serangkaian penuh mesin yang rumit dan besar.",
  ui_story_5015_50150201_123_dialog_content = "Bagaimana cara Butler mengendalikan dan memerintah droid?",
  ui_story_5015_50150201_124_dialog_content = "Nah, itu agak sama dengan konsep terminal kita.",
  ui_story_5015_50150201_125_dialog_content = "Tapi, teknologi kuno menggunakan jenis gelombang yang benar-benar berbeda dengan milik kita, bahkan terkadang eksklusif.",
  ui_story_5015_50150201_126_dialog_content = "Manusia Ancient sudah meramalkannya.",
  ui_story_5015_50150201_127_dialog_content = "Akibatnya, biasanya Undercity akan mengutamakan sistem penghalang agar transmisi informasi di dalamnya menggunakan gelombang mereka.",
  ui_story_5015_50150201_128_dialog_content = "Aku jadi bingung.",
  ui_story_5015_50150201_129_dialog_content = "Anggap saja manusia Ancient punya terminal sendiri untuk mengirim perintah pada droid. Mereka juga mampu memblokir terminal kita.",
  ui_story_5015_50150201_130_dialog_content = "Ini juga bisa menjelaskan bagaimana sinyal penyelamatan Seamus keluar saat terjadi gempa...",
  ui_story_5015_50150201_131_dialog_content = "Benar, gempa memengaruhi pengoperasian Undercity. Jadi, mungkin untuk sementara jaringan jamming itu tidak berfungsi.",
  ui_story_5015_50150201_132_dialog_content = "Sebenarnya, aku lebih mengkhawatirkan kalau teman-teman Illumina kita datang kemari dan juga terjebak setelah menerima sinyal minta bantuan kita...",
  ui_story_5015_50150201_133_dialog_content = "Siobhan, banyak hal yang Anda katakan terdengar seperti apa yang ayah katakan.",
  ui_story_5015_50150201_134_dialog_content = "Ah...",
  ui_story_5015_50150201_135_dialog_content = "Berapa lama lagi sih kita harus berjalan? Aku sangat bosan.",
  ui_story_5015_50150201_136_dialog_content = "Ruby, memangnya kau tidak lihat bahwa tempat ini sangat menarik?",
  ui_story_5015_50150201_137_dialog_content = "Menarik apanya? Sekarang saja aku sudah sangat merindukan lantai atas.",
  ui_story_5015_50150201_138_dialog_content = "Seluruh ekosistem, sistem penanaman dan pengolahan otomatis, serta peralatan otomatis di kota atas bergantung pada tempat ini.",
  ui_story_5015_50150201_139_dialog_content = "Semuanya bisa berjalan mulus selama bertahun-tahun karena sistem yang rumit ini.",
  ui_story_5015_50150201_140_dialog_content = "Segala yang ada di sini adalah keajaiban.",
  ui_story_5015_50150201_141_dialog_content = "Entah bagaimana dulu manusia Ancient melakukannya, tapi sayangnya kita akan butuh ratusan tahun untuk mempelajari semua peralatan di sini.",
  ui_story_5015_50150201_142_dialog_content = "Setelah itu apa? Apa yang ingin kau lakukan?",
  ui_story_5015_50150201_143_dialog_content = "Perdebatan saling balas antara Illumina dan Lumopolis lebih menjengkelkan dari Eclipsite.",
  ui_story_5015_50150201_144_dialog_content = "Yang satu ingin jadi pahlawan, yang satunya lagi ingin jadi santo.",
  ui_story_5015_50150201_145_dialog_content = "Memangnya orang tidak boleh memilih sendiri?",
  ui_story_5015_50150201_146_dialog_content = "Gunakan teknologi kuno kalau mau, dan jangan gunakan kalau tidak mau. Gampang, 'kan?",
  ui_story_5015_50150201_147_dialog_content = "Haha, andai saja semuanya benar-benar sesederhana itu.",
  ui_story_5015_50150201_148_dialog_content = "<color=#e8d9bb>Bip... Bip...</color>",
  ui_story_5015_50150201_149_dialog_content = "Awas, ada droid datang!",
  ui_story_5015_50150201_150_dialog_content = "Tenang saja, dia tak akan menyerang kita!",
  ui_story_5015_50150201_151_dialog_content = "Bagaimana cara Gretel mengendalikannya?",
  ui_story_5015_50150201_152_dialog_content = "Entahlah, mereka hanya menuruti perintahku.",
  ui_story_5015_50150201_153_dialog_content = "Butler bilang statusmu sudah jadi \"penduduk\", Valencia dan aku jadi \"teman\", dan yang lain jadi \"tidak berbahaya\".",
  ui_story_5015_50150201_154_dialog_content = "Kurasa para penduduk berhak mengendalikan droid.",
  ui_story_5015_50150201_155_dialog_content = "Itu sebabnya Valencia dan PlayerName tidak bisa melakukannya.",
  ui_story_5015_50150201_156_dialog_content = "Tidak sulit melihat polanya kalau kita memeriksa semua pertempuran yang terjadi sejak datang kemari.",
  ui_story_5015_50150201_157_dialog_content = "Eclipsite tidak menyerang penduduk, seperti Gretel.",
  ui_story_5015_50150201_158_dialog_content = "Tapi, mereka tetap menyerang orang yang berstatus Teman dan Tidak Berbahaya.",
  ui_story_5015_50150201_159_dialog_content = "Para droid tidak menyerang target selain musuh, termasuk Eclipsite.",
  ui_story_5015_50150201_160_dialog_content = "Tapi, kalau Eclipsite menyerang Teman, droid akan melindungi mereka.",
  ui_story_5015_50150201_161_dialog_content = "Keluarga Seamus dilindungi droid karena mereka berstatus Teman.",
  ui_story_5015_50150201_162_dialog_content = "Tentu saja semua orang yang menyerang droid atau menghancurkan kota akan jadi musuh.",
  ui_story_5015_50150201_163_dialog_content = "Memangnya siapa yang membuat aturan ini?",
  ui_story_5015_50150201_164_dialog_content = "Mungkin saja manusia Ancient, atau justru Overmind...",
  ui_story_5015_50150201_165_dialog_content = "Tapi, bisa jadi ini adalah kegagalan sistem. Apa pun itu, ayo kita cari Butler dulu.",
  ui_story_5015_50150201_166_dialog_content = "Satu-satunya hal yang tidak kupahami adalah kenapa Eclipsite bahkan mengikuti aturan ini dan menyerang musuh...",
  ui_story_5015_50150201_167_dialog_content = "Nah, kenyataan bahwa Eclipsite tidak menyerang penduduk sudah jadi bukti yang cukup bahwa mereka ada hubungannya dengan kota ini, 'kan?",
  ui_story_5015_50150201_168_dialog_content = "Benar, Eclipsite mengikuti aturan dan mampu mengetahuinya dengan cepat saat status seseorang berubah.",
  ui_story_5015_50150201_169_dialog_content = "Seperti droid.",
  ui_story_5015_50150201_170_dialog_content = "Kurasa Eclipsite di sini cukup istimewa.",
  ui_story_5015_50150201_171_dialog_content = "Grrr...",
  ui_story_5015_50150201_172_dialog_content = "Ada serangan Eclipsite!",
  ui_story_5015_50150201_173_dialog_content = "Cukup bicaranya. Saatnya bertarung!",
  ui_story_5015_50150201_174_dialog_content = "Gretel, bisakah kau menghentikan para Eclipsite ini?",
  ui_story_5015_50150201_175_dialog_content = "Aku... aku tidak bisa!",
  ui_story_5015_50150201_176_dialog_content = "Para droid itu benar-benar datang untuk membantu.",
  ui_story_5015_50150201_177_dialog_content = "Lihat ini! Serang!",
  ui_story_5015_50150201_178_dialog_content = "Kenapa sekarang rasanya para Eclipsite itu lebih kuat?",
  ui_story_5015_50150201_179_dialog_content = "Benar. Eclipsite yang kita temui di sini makin kuat saja.",
  ui_story_5015_50150201_180_dialog_content = "Baik droid maupun Eclipsite sama-sama lebih kuat. Apa jangan-jangan kita yang jadi lebih lemah?",
  ui_story_5015_50150201_181_dialog_content = "Para droid itu makin kuat karena Butler terus menganalisis pertempuran kita dan meningkatkan desain mereka.",
  ui_story_5015_50150201_182_dialog_content = "Apa Eclipsite juga bisa meninjau pertempuran dan perubahan mereka?",
  ui_story_5015_50150201_183_dialog_content = "Aku sudah membaca-baca catatan penelitian Seamus.",
  ui_story_5015_50150201_184_dialog_content = "Dia selalu menduga bahwa Eclipsite di kota ini dibuat oleh seseorang. Dia bahkan mencurigai Butler—",
  ui_story_5015_50150201_185_dialog_content = "M-mustahil!",
  ui_story_5015_50150201_186_dialog_content = "Kalau dia benar-benar ingin melukai kami, kenapa dia mau menyelamatkan kami?",
  ui_story_5015_50150201_187_dialog_content = "Tidak, justru inilah yang membuat AI berbahaya.",
  ui_story_5015_50150201_188_dialog_content = "Kalau AI mengira dia perlu mempelajari Luminatics atau apa pun...",
  ui_story_5015_50150201_189_dialog_content = "Kita tidak bisa mengesampingkan kemungkinan bahwa dia membuat Eclipsite menyerang keluargamu.",
  ui_story_5015_50150201_190_dialog_content = "Aku bahkan pernah menjumpai AI yang meyakini bahwa populasi manusia Ancient dalam jumlah besar akan membahayakan keamanan Undercity...",
  ui_story_5015_50150201_191_dialog_content = "... dan mereka menghabisi semua orang sebagai solusinya.",
  ui_story_5015_50150201_192_dialog_content = "Maksudmu R - Ruins dari tiga tahun lalu, 'kan?",
  ui_story_5015_50150201_193_dialog_content = "Benar. Meskipun kami hanya berhasil mendapat sedikit informasi, Hedy tetap bisa menguraikan banyak informasi penting.",
  ui_story_5015_50150201_194_dialog_content = "Lalu dengan informasi itu kalian menemukan bagian inti dari R - Ruins itu sebelum kami.",
  ui_story_5015_50150201_195_dialog_content = "Benar, kami menemukannya dan bahkan menyisirnya dengan cermat.",
  ui_story_5015_50150201_196_dialog_content = "Aku yakin kali ini kami juga akan menemukannya lebih dulu...",
  ui_story_5015_50150201_197_dialog_content = "Jangan sering-sering berkata begitu.",
  ui_story_5015_50150201_198_dialog_content = "Menurut perkataanmu tadi, sepertinya Butler—",
  ui_story_5015_50150201_199_dialog_content = "Tidak, Butler tidak akan melakukannya.",
  ui_story_5015_50150201_200_dialog_content = "Nah, setelah semua perkataanmu itu, pernahkah kau mempertimbangkan...",
  ui_story_5015_50150201_201_dialog_content = "Entah kau mau menghancurkan atau merebut tempat ini, kita tetap harus keluar dulu, 'kan?",
  ui_story_5015_50150201_202_dialog_content = "Florine, kalau kau benar-benar menghancurkannya, kita justru akan terkubur bersama Undercity ini.",
  ui_story_5015_50150201_203_dialog_content = "Memangnya kau sungguh-sungguh mau melakukan itu?",
  ui_story_5015_50150201_204_dialog_content = "Siobhan, kalau saja kau tidak sering berdebat dengan mereka...",
  ui_story_5015_50150201_205_dialog_content = "Cukup, Ruby. Aku paham betul situasi kita. Aku yakin Florine juga begitu.",
  ui_story_5015_50150201_206_dialog_content = "Prioritas utama kita tentu saja mencari jalan keluar.",
  ui_story_5015_50150201_207_dialog_content = "Jadi, kita tidak akan bertindak dengan terlalu ekstrem. Kau setuju, Florine?",
  ui_story_5015_50150201_208_dialog_content = "Ya, aku setuju.",
  ui_story_5015_50150201_209_dialog_content = "Apa yang harus kita lakukan kalau Butler tertidur?",
  ui_story_5015_50150201_210_dialog_content = "Jumlah kita ada banyak... Kita pasti menemukan cara.",
  ui_story_5015_50150201_211_dialog_content = "Kita selalu bisa kembali ke lantai atas dan melanjutkan penelitian Seamus. Pada akhirnya kita pasti akan menemukan jalan keluar.",
  ui_story_5015_50150201_212_dialog_content = "Kalau ada gempa lagi, tempat ini akan hancur sebelum jalan keluarnya ketemu.",
  ui_story_5015_50150201_213_dialog_content = "Nah, alasan untuk kembali ke lantai atas jadi makin kuat. Setidaknya ada pakaian bagus, makanan lezat, dan pemandangan indah di sana.",
  ui_story_5015_50150201_214_dialog_content = "Kalian tidak mau tinggal di sini sama sekali? Memangnya dunia luar benar-benar indah?",
  ui_story_5015_50150201_215_dialog_content = "Kau akan mengetahuinya kalau sudah mengalaminya sendiri.",
  ui_story_5015_50150201_216_dialog_content = "Lokasi yang Butler sebutkan seharusnya ada di depan.",
  ui_story_5015_50150201_217_dialog_content = "Akhirnya...",
  ui_story_5015_50150201_218_dialog_content = "Gawat! Ada Eclipsite di sekitar sini!",
  ui_story_5015_50150201_219_dialog_content = "Bersiaplah untuk bertarung, teman-teman!",
  ui_story_5015_50150201_220_dialog_content = "A-apa jangan-jangan para Eclipsite itu berniat menyerang Butler?",
  ui_story_5015_50150201_221_dialog_content = "Itu mustahil. Lagi pula Eclipsite dan droid tidak secara aktif saling serang. Iya, 'kan, Valencia?",
  ui_story_5015_50150201_222_dialog_content = "Benar, aku belum pernah melihat yang seperti ini.",
  ui_story_5015_50150201_223_dialog_content = "Bisa tidak sih kalian diam dulu sebelum bertarung?",
  ui_story_5015_50150201_224_dialog_content = "Aku lagi yang maju duluan! Serang!",
  ui_story_5015_50150201_225_dialog_content = "Sepertinya mereka mundur...",
  ui_story_5015_50150201_226_dialog_content = "Akhirnya...",
  ui_story_5015_50150201_227_dialog_content = "Akhirnya, kita bertemu lagi...",
  ui_story_5015_50150301_1_dialog_content = "<color=#e8d9bb>Halo, Gretel, Valencia, PlayerName.</color>",
  ui_story_5015_50150301_2_dialog_content = "Kenapa kami tidak bisa menghubungimu? Tadinya kami pikir...",
  ui_story_5015_50150301_3_dialog_content = "<color=#e8d9bb>Aku baik-baik saja... Aku hanya butuh... waktu... untuk pulih... Kau baik-baik saja?</color>",
  ui_story_5015_50150301_4_dialog_content = "Aku bertemu dengan mereka dalam perjalanan ke inti energi itu... Kakak melarangku pergi.",
  ui_story_5015_50150301_5_dialog_content = "Butler, apa benar tidak apa-apa kalau menyuruh Gretel melakukan sesuatu yang sangat berbahaya?",
  ui_story_5015_50150301_6_dialog_content = "<color=#e8d9bb>Kalau gempanya... Kalau intinya... hancur, akan terjadi bencana.</color>",
  ui_story_5015_50150301_7_dialog_content = "Orang itu bilang bahwa mereka adalah temanmu. Benarkah itu?",
  ui_story_5015_50150301_8_dialog_content = "<color=#e8d9bb>Ya... PlayerName adalah Caelestite, teman bagi kota ini.</color>",
  ui_story_5015_50150301_9_dialog_content = "Kita bertemu lagi, Butler.",
  ui_story_5015_50150301_10_dialog_content = "<color=#e8d9bb>Salam, Caelestite.</color>",
  ui_story_5015_50150301_11_dialog_content = "Mesin yang di belakangmu adalah dirimu yang sesungguhnya, 'kan?",
  ui_story_5015_50150301_12_dialog_content = "Sudah, sudah. Tidak usah bertele-tele, langsung ke intinya saja. Biar aku yang bicara!",
  ui_story_5015_50150301_13_dialog_content = "Butler, kami hanya ingin pergi dari tempat ini sekarang. Di mana jalan keluarnya?",
  ui_story_5015_50150301_14_dialog_content = "...",
  ui_story_5015_50150301_15_dialog_content = "<color=#e8d9bb>Maaf, izin ditolak. Aku tidak bisa menjawab pertanyaan ini.</color>",
  ui_story_5015_50150301_16_dialog_content = "Kalau begitu, biar aku yang tanya. Butler, bagaimana cara keluar dari tempat ini?",
  ui_story_5015_50150301_17_dialog_content = "<color=#e8d9bb>Aku tidak tahu... cara keluar dari kota ini.</color>",
  ui_story_5015_50150301_18_dialog_content = "Di mana jalan keluarnya?",
  ui_story_5015_50150301_19_dialog_content = "<color=#e8d9bb>Maaf... Izin ditolak... Aku tidak bisa menjawab pertanyaan ini.</color>",
  ui_story_5015_50150301_20_dialog_content = "Butler, apa yang harus kami lakukan?",
  ui_story_5015_50150301_21_dialog_content = "<color=#e8d9bb>Kalian bisa hidup... dengan aman... di kota ini...</color>",
  ui_story_5015_50150301_22_dialog_content = "<color=#e8d9bb>Tapi, ingatlah untuk mengikuti peraturan... Jangan membahayakan keamanan kota ini.</color>",
  ui_story_5015_50150301_23_dialog_content = "Hari ini aku baru tahu bahwa Eclipsite tidak menyerang penduduk.",
  ui_story_5015_50150301_24_dialog_content = "Butler, kenapa kau tidak mengizinkan Ibu dan Ayah menjadi penduduk?",
  ui_story_5015_50150301_25_dialog_content = "Kalau kau mengizinkannya, mereka tak akan tewas!",
  ui_story_5015_50150301_26_dialog_content = "Kakak...",
  ui_story_5015_50150301_27_dialog_content = "<color=#e8d9bb>Valencia, bukan aku yang menentukan kriteria persetujuan penduduk.</color>",
  ui_story_5015_50150301_28_dialog_content = "<color=#e8d9bb>Aku harus memintanya dengan tegas... Menurut kalkulasi... Tugas terpenting saat ini adalah memperbaiki inti energi.</color>",
  ui_story_5015_50150301_29_dialog_content = "<color=#e8d9bb>Kalau tidak diperbaiki, kota ini benar-benar bisa runtuh dalam kurang dari 100 gempa susulan.</color>",
  ui_story_5015_50150301_30_dialog_content = "Sudahlah. Berhenti menebak-nebak, kita cari saja informasinya.",
  ui_story_5015_50150301_31_dialog_content = "Sayang sekali aku tidak begitu memahami AI...",
  ui_story_5015_50150301_32_dialog_content = "PlayerName, ada yang bisa kau rasakan dari mesin Butler?",
  ui_story_5015_50150301_33_dialog_content = "Tidak, aku tidak merasakan apa pun.",
  ui_story_5015_50150301_34_dialog_content = "Sebentar, aku bisa merasakan Eclipsite!",
  ui_story_5015_50150301_35_dialog_content = "Kenapa jumlah Eclipsite-nya sangat banyak?!",
  ui_story_5015_50150301_36_dialog_content = "Florine, bantu aku menarik perhatian Eclipsite dari samping.",
  ui_story_5015_50150301_37_dialog_content = "Ruby, pimpin yang lain dan bersiaplah untuk menembus mereka.",
  ui_story_5015_50150301_38_dialog_content = "Awas! Gretel!",
  ui_story_5015_50150301_39_dialog_content = "Para Eclipsite itu menyerang Gretel??",
  ui_story_5015_50150301_40_dialog_content = "Valencia, Gretel, kemari.",
  ui_story_5015_50150301_41_dialog_content = "Tenang saja. Aku baik-baik saja, Valencia.",
  ui_story_5015_50150301_42_dialog_content = "Akan kuperintahkan para droid untuk membantumu, Ruby.",
  ui_story_5015_50150301_43_dialog_content = "Luar biasa!",
  ui_story_5015_50150301_44_dialog_content = "Eclipsite mundur!",
  ui_story_5015_50150301_45_dialog_content = "Butler, kenapa Eclipsite menyerang Gretel?",
  ui_story_5015_50150301_46_dialog_content = "Kau mencabut status Gretel sebagai penduduk?",
  ui_story_5015_50150301_47_dialog_content = "<color=#e8d9bb>Tidak, bukan aku.</color>",
  ui_story_5015_50150301_48_dialog_content = "Bohong!",
  ui_story_5015_50150301_49_dialog_content = "PlayerName, sepertinya dia tidak bohong.",
  ui_story_5015_50150301_50_dialog_content = "Gretel tetap bisa memerintahkan droid untuk menyerang, berarti dia masih jadi penduduk.",
  ui_story_5015_50150301_51_dialog_content = "Para droid juga tidak menyerang kita.",
  ui_story_5015_50150301_52_dialog_content = "Jadi, kita belum jadi musuh bagi kota ini. Benar, 'kan, Butler?",
  ui_story_5015_50150301_53_dialog_content = "<color=#e8d9bb>Aku tidak bohong.</color>",
  ui_story_5015_50150301_54_dialog_content = "Apa pun itu, karena Eclipsite sudah mulai menyerang penduduk, berarti mereka sudah jadi lebih berbahaya, 'kan?",
  ui_story_5015_50150301_55_dialog_content = "<color=#e8d9bb>Menurut kalkulasiku... Kalau aku tidak memberi kalian informasi yang relevan...</color>",
  ui_story_5015_50150301_56_dialog_content = "<color=#e8d9bb>Kalian benar-benar akan menghadapi bahaya besar.</color>",
  ui_story_5015_50150301_57_dialog_content = "<color=#e8d9bb>Akan kucoba menjelaskannya agar kalian... paham.</color>",
  ui_story_5015_50150301_58_dialog_content = "<color=#e8d9bb>Para Eclipsite itu memang diciptakan oleh kota ini... Aku membuktikannya belum lama ini.</color>",
  ui_story_5015_50150301_59_dialog_content = "<color=#e8d9bb>Setelah terbangun... aku menyadari bahwa semua penduduk sudah menghilang.</color>",
  ui_story_5015_50150301_60_dialog_content = "<color=#e8d9bb>Dan ada spesies baru di kota ini... para Eclipsite.</color>",
  ui_story_5015_50150301_61_dialog_content = "<color=#e8d9bb>Aku tidak tahu... apa yang terjadi.</color>",
  ui_story_5015_50150301_62_dialog_content = "<color=#e8d9bb>Tapi, menurut informasi, Eclipsite menyerang penduduk... sehingga mereka binasa.</color>",
  ui_story_5015_50150301_63_dialog_content = "Aku menduga ada kegagalan dalam sistem pengelolaan kota... yang mengakibatkan Eclipsite menembus penghalang dan menyerbu tempat ini.",
  ui_story_5015_50150301_64_dialog_content = "Manusia Ancient yang tidak dilindungi oleh droid...",
  ui_story_5015_50150301_65_dialog_content = "<color=#e8d9bb>Kemungkinan itu memang ada... tapi aku tidak menemukan informasi apa pun.</color>",
  ui_story_5015_50150301_66_dialog_content = "<color=#e8d9bb>Setiap kali berusaha mencari asal-usul Eclipsite... Aku tidak bisa meneruskannya karena tidak memiliki otorisasi yang dibutuhkan.</color>",
  ui_story_5015_50150301_67_dialog_content = "<color=#e8d9bb>Aku selalu menunggu modul-modul lain terbangun.</color>",
  ui_story_5015_50150301_68_dialog_content = "<color=#e8d9bb>Abby yang memiliki pengetahuan biologis... Hughes yang bertugas dalam sistem tempur, atau bahkan...</color>",
  ui_story_5015_50150301_69_dialog_content = "<color=#e8d9bb>Setelah itu, Seamus dan yang lainnya datang.</color>",
  ui_story_5015_50150301_70_dialog_content = "<color=#e8d9bb>Aku menyadari bahwa perilaku Eclipsite... mengikuti logika yang sama dengan droid.</color>",
  ui_story_5015_50150301_71_dialog_content = "Aku tahu. Bagaimana kalau kau menandai Eclipsite sebagai musuh bagi kota?",
  ui_story_5015_50150301_72_dialog_content = "<color=#e8d9bb>Menurut kalkulasiku... Kalau Eclipsite ditandai sebagai musuh...</color>",
  ui_story_5015_50150301_73_dialog_content = "<color=#e8d9bb>Sumber daya yang dikerahkan untuk pertempuran akan makin besar... Dalam jangka panjang, ini akan lebih membahayakan kota.</color>",
  ui_story_5015_50150301_74_dialog_content = "<color=#e8d9bb>Kami tidak akan sembarangan menyingkirkan makhluk hidup... termasuk Aurorian dan Eclipsite.</color>",
  ui_story_5015_50150301_75_dialog_content = "Kami pernah menjumpai mekanisme perlindungan yang sama, yang disebut hukum, di Undercity lain.",
  ui_story_5015_50150301_76_dialog_content = "Mungkin inilah salah satu kekhawatiran manusia Ancient tentang AI.",
  ui_story_5015_50150301_77_dialog_content = "<color=#e8d9bb>Setelah itu, aku menyortir dan menganalisis informasi yang terpisah...</color>",
  ui_story_5015_50150301_78_dialog_content = "<color=#e8d9bb>Aku menyadari bahwa Eclipsite dan manusia Ancient sepertinya memiliki banyak persamaan karakteristik.</color>",
  ui_story_5015_50150301_79_dialog_content = "Hah? Apa?! Eclipsite dan manusia Ancient punya banyak persamaan?",
  ui_story_5015_50150301_80_dialog_content = "<color=#e8d9bb>Beberapa karakteristik dipilih secara tidak wajar dan diwujudkan melalui evolusi.</color>",
  ui_story_5015_50150301_81_dialog_content = "<color=#e8d9bb>Menurut arsip peninggalan manusia Ancient, sepertinya Eclipsite yang sekarang juga telah sama-sama mengalami...</color>",
  ui_story_5015_50150301_82_dialog_content = "Modifikasi. Mereka adalah makhluk modifikasi buatan.",
  ui_story_5015_50150301_83_dialog_content = "Nah, sekarang sudah lebih jelas. Abby, modul biologis yang bertanggung jawab untuk merawat kehidupan manusia...",
  ui_story_5015_50150301_84_dialog_content = "Telah berhenti atau tidak bisa melanjutkan penciptaan manusia Ancient, tapi justru menciptakan Eclipsite.",
  ui_story_5015_50150301_85_dialog_content = "Bagaimana ini terjadi?",
  ui_story_5015_50150301_86_dialog_content = "<color=#e8d9bb>Siobhan, kau sangat pintar... Aku jadi teringat pada Seamus.</color>",
  ui_story_5015_50150301_87_dialog_content = "Aku hanya mengambil kesimpulan berdasarkan pada informasimu.",
  ui_story_5015_50150301_88_dialog_content = "Kita semua tahu bahwa setiap Undercity memiliki sistem yang bertugas dalam bidang reproduksi... Oh, mungkin Seamus tidak tahu ini.",
  ui_story_5015_50150301_89_dialog_content = "Penemuan ini kami dapatkan saat meneliti reruntuhan lain dalam beberapa tahun terakhir.",
  ui_story_5015_50150301_90_dialog_content = "Berarti Seamus tidak tahu. Kalau tahu, dia pasti sudah memahami kebenaran tentang tempat ini sejak dulu.",
  ui_story_5015_50150301_91_dialog_content = "PlayerName, demi mencegah kemusnahannya sendiri, manusia Ancient...",
  ui_story_5015_50150301_92_dialog_content = "... mereka memiliki sistem cadangan yang bertanggung jawab dalam reproduksi dan pendidikan di hampir setiap Undercity.",
  ui_story_5015_50150301_93_dialog_content = "Seperti Abby dan Uma.",
  ui_story_5015_50150301_94_dialog_content = "Ini seperti kasus di Gannon dan R - Ruins–",
  ui_story_5015_50150301_95_dialog_content = "Di R - Ruins, kami juga menemukan sistem yang bisa digunakan untuk kembali ke permukaan.",
  ui_story_5015_50150301_96_dialog_content = "Menurut informasi itu, sistem ini digunakan untuk memantau ekologi permukaan dan–",
  ui_story_5015_50150301_97_dialog_content = "Menurut ekologi permukaan...",
  ui_story_5015_50150301_98_dialog_content = "Sistem reproduksi akan membuat generasi masa depan manusia Ancient berevolusi dan beradaptasi dengan perubahan.",
  ui_story_5015_50150301_99_dialog_content = "<color=#e8d9bb>Ya, kau benar. Myers juga menghilang...</color>",
  ui_story_5015_50150301_100_dialog_content = "Seperti dugaanku... Kalau ada sistem yang mengarah ke permukaan, pasti juga ada jalan yang menuju ke sana.",
  ui_story_5015_50150301_101_dialog_content = "Kita harus menemukannya.",
  ui_story_5015_50150301_102_dialog_content = "Kalau Eclipsite terus berevolusi, mungkin kita akan musnah sebelum jalan keluarnya ditemukan.",
  ui_story_5015_50150301_103_dialog_content = "Kalau begitu, Butler, coba hubungi Abby.",
  ui_story_5015_50150301_104_dialog_content = "Bukankah masalahnya akan selesai kalau kita bisa meyakinkan Abby untuk menghentikan kegiatan berbahaya ini?",
  ui_story_5015_50150301_105_dialog_content = "<color=#e8d9bb>Sudah kubilang... Aku tidak bisa menghubungi Abby.</color>",
  ui_story_5015_50150301_106_dialog_content = "Kalau begitu, hancurkan dia!",
  ui_story_5015_50150301_107_dialog_content = "<color=#e8d9bb>Modul... dilarang keras untuk saling serang.</color>",
  ui_story_5015_50150301_108_dialog_content = "...",
  ui_story_5015_50150301_109_dialog_content = "Siobhan, logika Butler sudah tidak masuk akal lagi.",
  ui_story_5015_50150301_110_dialog_content = "Tahun-tahun yang dilewatinya sudah tak terhitung... Sudahlah, mungkin kita bisa memperlakukan Butler seperti pasien yang paranoid.",
  ui_story_5015_50150301_111_dialog_content = "Huh, ayo kita cari sistem yang bisa digunakan untuk kembali ke permukaan.",
  ui_story_5015_50150301_112_dialog_content = "<color=#e8d9bb>Gruk...</color>",
  ui_story_5015_50150301_113_dialog_content = "Celaka, ada gempa lagi!",
  ui_story_5015_50150301_114_dialog_content = "Waspadai benda yang berjatuhan!",
  ui_story_5015_50150301_115_dialog_content = "Gah... Gah...!",
  ui_story_5015_50150301_116_dialog_content = "Para Eclipsite sudah kemari!",
  ui_story_5015_50150301_117_dialog_content = "<color=#e8d9bb>Bahaya... Abby...</color>",
  ui_story_5015_50150301_118_dialog_content = "Groar!",
  ui_story_5015_50150301_119_dialog_content = "Kenapa sih para Eclipsite ini? Kenapa mereka asal terjang tanpa memikirkan keselamatannya?",
  ui_story_5015_50150301_120_dialog_content = "Ruby, Florine, hentikan para Eclipsite itu!",
  ui_story_5015_50150301_121_dialog_content = "Ini pernah terjadi saat kita mencapai pusat data Butler...",
  ui_story_5015_50150301_122_dialog_content = "Para Eclipsite ini menganggap kita semua, termasuk Butler, sebagai musuh.",
  ui_story_5015_50150301_123_dialog_content = "Biar aku yang memberi perintah. Habisi mereka sesegera mungkin!",
  ui_story_5015_50150301_124_dialog_content = "Graaaaaagh!",
  ui_story_5015_50150301_125_dialog_content = "Rapid Torrent!",
  ui_story_5015_50150301_126_dialog_content = "Biar kucoba!",
  ui_story_5015_50150301_127_dialog_content = "Pukulan tongkat super!",
  ui_story_5015_50150301_128_dialog_content = "Grrr...",
  ui_story_5015_50150301_129_dialog_content = "Akhirnya selesai juga...",
  ui_story_5015_50150301_130_dialog_content = "Aku akan memeriksa keadaan Butler.",
  ui_story_5015_50150301_131_dialog_content = "<color=#e8d9bb>Jangan khawatir... Aku sudah melanjutkan pengoperasian normal.</color>",
  ui_story_5015_50150301_132_dialog_content = "Tadinya kukira para modul tidak bisa saling serang. Kenapa Eclipsite Abby...",
  ui_story_5015_50150301_133_dialog_content = "<color=#e8d9bb>Abby sudah mendapat otoritas... yang lebih tinggi.</color>",
  ui_story_5015_50150301_134_dialog_content = "<color=#e8d9bb>Dia merebut lebih banyak hak kendali.</color>",
  ui_story_5015_50150301_135_dialog_content = "<color=#e8d9bb>Sebagian besar mesin... berada di bawah kendaliku sekarang...</color>",
  ui_story_5015_50150301_136_dialog_content = "Abby merebut otoritas?",
  ui_story_5015_50150301_137_dialog_content = "Mencuri di bawah hidung kita...? Di mana Abby?!",
  ui_story_5015_50150301_138_dialog_content = "<color=#e8d9bb>DUAR!</color>",
  ui_story_5015_50150301_139_dialog_content = "<color=#e8d9bb>A... sedang... sedang... sedang...</color>",
  ui_story_5015_50150301_140_dialog_content = "<color=#e8d9bb>Mereka semua menuju ke satu arah... Di sanalah Abby dan energi itu... berada.</color>",
  ui_story_5015_50150301_141_dialog_content = "Arah apa itu?",
  ui_story_5015_50150301_142_dialog_content = "Inti energi...",
  ui_story_5015_50150301_143_dialog_content = "<size=45><color=#FFB400>Alchemy Stars.</color></size>",
  ui_story_5015_50150401_1_dialog_content = "Alchemy Stars?",
  ui_story_5015_50150401_2_dialog_content = "<color=#e8d9bb>Ini adalah... nama inti energinya.</color>",
  ui_story_5015_50150401_3_dialog_content = "Inti energi yang memberikan energi bagi seluruh Undercity.",
  ui_story_5015_50150401_4_dialog_content = "Kenapa Abby menyuruh para droid dan Eclipsite itu ke sana?",
  ui_story_5015_50150401_5_dialog_content = "<color=#e8d9bb>Abby mencoba untuk memperbaiki inti energi.</color>",
  ui_story_5015_50150401_6_dialog_content = "Memangnya Abby bisa memperbaiki inti energi?",
  ui_story_5015_50150401_7_dialog_content = "<color=#e8d9bb>Aku sedang mengalkulasikan... kemungkinannya...</color>",
  ui_story_5015_50150401_8_dialog_content = "<color=#e8d9bb>Abby punya otoritas untuk mengakses... lebih banyak informasi.</color>",
  ui_story_5015_50150401_9_dialog_content = "Dengan kata lain, dia punya informasi yang dibutuhkan untuk memperbaiki inti energi yang tidak dimiliki Butler...",
  ui_story_5015_50150401_10_dialog_content = "Karena sudah memiliki otorisasi pemeliharaan, dia mengirim para droid ke sana.",
  ui_story_5015_50150401_11_dialog_content = "Kalau Abby bisa menstabilkan Alchemy Stars...",
  ui_story_5015_50150401_12_dialog_content = "Maka, kota kami bisa berfungsi dengan normal!",
  ui_story_5015_50150401_13_dialog_content = "Kalau begitu, kami bisa meminta Honcho Sinsa untuk kemari dan menumpas semua Eclipsite di sini–",
  ui_story_5015_50150401_14_dialog_content = "Lalu kami semua bisa tinggal di sini!",
  ui_story_5015_50150401_15_dialog_content = "Setelah itu, kami tidak perlu tinggal di gurun lagi dan muka kami tak akan tersembur pasir lagi!",
  ui_story_5015_50150401_16_dialog_content = "Kalian tidak boleh kemari!",
  ui_story_5015_50150401_17_dialog_content = "Valencia, apa kita bisa tinggal di sini kalau inti energinya sudah diperbaiki?",
  ui_story_5015_50150401_18_dialog_content = "Gretel...",
  ui_story_5015_50150401_19_dialog_content = "Selain itu, ada banyak informasi berharga tentang teknologi kuno di sini...",
  ui_story_5015_50150401_20_dialog_content = "Kalau kita bisa mempelajari dan menggunakannya, manfaatnya akan luar biasa bagi seluruh benua...",
  ui_story_5015_50150401_21_dialog_content = "Apa pun yang dilakukan mesin yang tidak setia dan tidak berjiwa ini, tak akan ada untungnya.",
  ui_story_5015_50150401_22_dialog_content = "Erica benar! Kau terlalu naif.",
  ui_story_5015_50150401_23_dialog_content = "Lihat saja AI di sini–",
  ui_story_5015_50150401_24_dialog_content = "Yang satu punya logika yang membingungkan dan tidak bisa menyingkirkan modul kecerdasan yang terus memodifikasi Eclipsite.",
  ui_story_5015_50150401_25_dialog_content = "Dan yang satunya lagi telah melupakan pengaturan aslinya dan mulai mempelajari serta mengembangkan Eclipsite.",
  ui_story_5015_50150401_26_dialog_content = "Kalian benar-benar berharap mereka bakal menciptakan tempat ideal untuk ditinggali Aurorian?",
  ui_story_5015_50150401_27_dialog_content = "Bukankah seharusnya kita memikirkan akibatnya kalau Abby tidak bisa menstabilkan Alchemy Stars?",
  ui_story_5015_50150401_28_dialog_content = "Butler, apa yang akan terjadi kalau Abby tidak bisa menstabilkan Alchemy Stars?",
  ui_story_5015_50150401_29_dialog_content = "<color=#e8d9bb>Operasi berotorisasi tinggi Abby...</color>",
  ui_story_5015_50150401_30_dialog_content = "<color=#e8d9bb>akan meningkatkan muatan operasional Alchemy Stars. Itu sangat berbahaya.</color>",
  ui_story_5015_50150401_31_dialog_content = "Nah, dengar, 'kan? Tempat ini akan jadi lebih berbahaya kalau Abby gagal!",
  ui_story_5015_50150401_32_dialog_content = "Jangan pikirkan apa akibatnya kalau dia sampai gagal. Memangnya keadaan kita akan baik-baik saja kalau dia berhasil?",
  ui_story_5015_50150401_33_dialog_content = "Tanyakan saja pada Butler apa yang akan terjadi kepadanya kalau Abby memperbaiki inti itu.",
  ui_story_5015_50150401_34_dialog_content = "Butler, apa kau akan terpengaruh kalau Abby memperbaiki inti itu?",
  ui_story_5015_50150401_35_dialog_content = "<color=#e8d9bb>Otoritasku akan makin berkurang.</color>",
  ui_story_5015_50150401_36_dialog_content = "<color=#e8d9bb>Aku... mungkin akan berhenti berfungsi.</color>",
  ui_story_5015_50150401_37_dialog_content = "Kalau begitu, kita...",
  ui_story_5015_50150401_38_dialog_content = "<color=#e8d9bb>Kurasa kalian akan menghadapi... bahaya yang lebih besar.</color>",
  ui_story_5015_50150401_39_dialog_content = "<color=#e8d9bb>Abby akan menggunakan... energi untuk <color=#FFB400>mengembangkan Eclipsite</color>.</color>",
  ui_story_5015_50150401_40_dialog_content = "Jangan biarkan Abby memperbaiki inti itu!",
  ui_story_5015_50150401_41_dialog_content = "Tapi, sudah jelas bahwa AI yang memodifikasi para Eclipsite itu tidak bakal membuka jalan keluar bagi siapa pun.",
  ui_story_5015_50150401_42_dialog_content = "Mungkin dia justru akan membuat Eclipsite yang lebih kuat dan mengirim mereka ke permukaan.",
  ui_story_5015_50150401_43_dialog_content = "Begitu daratan dipenuhi Eclipsite mengerikan yang asal-usulnya tidak diketahui, para Aurorian akan menghadapi tantangan lebih besar.",
  ui_story_5015_50150401_44_dialog_content = "Meski begitu, semua orang masih ingin berteman akrab dengan AI–",
  ui_story_5015_50150401_45_dialog_content = "Aku benar-benar tidak paham.",
  ui_story_5015_50150401_46_dialog_content = "Kuharap kalian bisa menyingkirkan kenaifan akibat fanatisme itu, kembali pada kenyataan, dan punya pikiran yang matang tentang pencapaian kita berikutnya.",
  ui_story_5015_50150401_47_dialog_content = "Kita harus menghentikan Abby sekarang.",
  ui_story_5015_50150401_48_dialog_content = "Aku paham maksudmu.",
  ui_story_5015_50150401_49_dialog_content = "Gretel, kau yang punya otoritas tertinggi di antara kita. Bisa tidak kalau kau minta Butler untuk menunjukkan jalannya?",
  ui_story_5015_50150401_50_dialog_content = "Baiklah. Butler, kami ingin pergi ke tempat yang bernama Alchemy Stars.",
  ui_story_5015_50150401_51_dialog_content = "<color=#e8d9bb>Diterima... Gretel...</color>",
  ui_story_5015_50150401_52_dialog_content = "<color=#e8d9bb>Di depan kita. Kita akan memasuki... area inti energi.</color>",
  ui_story_5015_50150401_53_dialog_content = "Aku jadi gugup nih gara-gara bakal bertemu Abby si legendaris dan inti energi itu!",
  ui_story_5015_50150401_54_dialog_content = "Ruby... sepertinya ada tanda-tanda droid di depan sana.",
  ui_story_5015_50150401_55_dialog_content = "Oh, baiklah. Ayo kita ikuti.",
  ui_story_5015_50150401_56_dialog_content = "Aku bisa merasakan Darkflow yang sangat pekat di depan sana.",
  ui_story_5015_50150401_57_dialog_content = "Buat rencana dulu, PlayerName.",
  ui_story_5015_50150401_58_dialog_content = "Teman-teman, kita harus menyingkirkan dulu semua Eclipsite dan droid di sini.",
  ui_story_5015_50150401_59_dialog_content = "Bisa jadi para droid itu dalam kendali Abby.",
  ui_story_5015_50150401_60_dialog_content = "Semuanya, bersiaplah untuk bertarung!",
  ui_story_5015_50150401_61_dialog_content = "Tepat sasaran!",
  ui_story_5015_50150401_62_dialog_content = "Graagh!",
  ui_story_5015_50150401_63_dialog_content = "Seperti biasa, Ruby selalu bersemangat saat bertarung!",
  ui_story_5015_50150401_64_dialog_content = "Aku tidak boleh tertinggal!",
  ui_story_5015_50150401_65_dialog_content = "Blazing Epee!",
  ui_story_5015_50150401_66_dialog_content = "Grrr... Gargh...",
  ui_story_5015_50150401_67_dialog_content = "Apa kalian merasa tertekan?",
  ui_story_5015_50150401_68_dialog_content = "Rasanya udara di sekitar mencekik kita...",
  ui_story_5015_50150401_69_dialog_content = "J-jangan-jangan ini karena sumber daya seluruh Undercity... ada di sekitar sini.",
  ui_story_5015_50150401_70_dialog_content = "Graaaaaah!!",
  ui_story_5015_50150401_71_dialog_content = "Ada Eclipsite di belakangmu, Rouge! Minggir–",
  ui_story_5015_50150401_72_dialog_content = "Rasakan ini!",
  ui_story_5015_50150401_73_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5015_50150401_74_dialog_content = "Wow, sepertinya aku tidak menggunakan kekuatan penuh... Jadi, begini ya kemampuanku dengan setengah kekuatanku...?",
  ui_story_5015_50150401_75_dialog_content = "Rouge, kemampuanku meningkat! Lihat tidak?!",
  ui_story_5015_50150401_76_dialog_content = "Ruby, ada gempa!",
  ui_story_5015_50150401_77_dialog_content = "Ayo sembunyi di sebelah sana!",
  ui_story_5015_50150401_78_dialog_content = "Rasanya energi di sekitar kita berubah...",
  ui_story_5015_50150401_79_dialog_content = "Energinya makin pekat dengan cepat!",
  ui_story_5015_50150401_80_dialog_content = "Jangan-jangan ada yang salah dengan Alchemy Stars?",
  ui_story_5015_50150401_81_dialog_content = "Aku sedang mencoba untuk merasakannya dengan lebih baik...",
  ui_story_5015_50150401_82_dialog_content = "<color=#e8d9bb>Gruk...</color>",
  ui_story_5015_50150401_83_dialog_content = "Argh... *batuk-batuk*",
  ui_story_5015_50150401_84_dialog_content = "PlayerName, hidungmu berdarah! Berhenti merasakan!",
  ui_story_5015_50150401_85_dialog_content = "<color=#e8d9bb>Krak! Dhuar!!</color>",
  ui_story_5015_50150401_86_dialog_content = "... Kamu... rupanya... Kenapa kau datang lagi?",
  ui_story_5015_50150401_87_dialog_content = "Ini kontak telepati?",
  ui_story_5015_50150401_88_dialog_content = "<color=#e8d9bb>Benar, PlayerName. Karena kau menggunakan kemampuan psikismu lagi, kita bisa...</color>",
  ui_story_5015_50150401_89_dialog_content = "Tidak, sebenarnya aku tidak mencoba menghubungimu lagi.",
  ui_story_5015_50150401_90_dialog_content = "Butler, apa kau bisa memeriksa keadaan Vice dan yang lain? Aku mencemaskan mereka setelah gempa itu...",
  ui_story_5015_50150401_91_dialog_content = "<color=#e8d9bb>Tenang saja, teman-temanmu selamat.</color>",
  ui_story_5015_50150401_92_dialog_content = "<color=#e8d9bb>Efisiensi tempurmu luar biasa. Hampir semua Eclipsite dan droid di area ini sudah binasa.</color>",
  ui_story_5015_50150401_93_dialog_content = "Bagus sekali!",
  ui_story_5015_50150401_94_dialog_content = "<color=#e8d9bb>Meski dalam keadaan tidak sadar pun kau masih saja memikirkan teman-temanmu. Semangatmu sangat mengagumkan.</color>",
  ui_story_5015_50150401_95_dialog_content = "Semangatku tidak terlalu mengagumkan. Bukankah wajar kalau mencemaskan teman-teman kita?",
  ui_story_5015_50150401_96_dialog_content = "Karena memiliki emosi, kami saling berbagi kebahagiaan dan mencemaskan keadaan satu sama lain.",
  ui_story_5015_50150401_97_dialog_content = "Seharusnya kau bisa merasakannya juga.",
  ui_story_5015_50150401_98_dialog_content = "<color=#e8d9bb>Benar. Aku bisa menentukan perasaan seseorang dengan menganalisis raut wajah, perkataan, dan bahasa tubuhnya.</color>",
  ui_story_5015_50150401_99_dialog_content = "Perasaan tidak bisa ditentukan... Hei, jangan-jangan kau tidak memahami emosi?",
  ui_story_5015_50150401_100_dialog_content = "Kau menjadikan Gretel sebagai penduduk kota ini... Bukankah itu karena faktor emosi?",
  ui_story_5015_50150401_101_dialog_content = "<color=#e8d9bb>Ucapanmu membuatku bingung.</color>",
  ui_story_5015_50150401_102_dialog_content = "<color=#e8d9bb>Aku menjadikan Gretel sebagai penduduk karena dia memenuhi kriteria penduduk generasi berikutnya.</color>",
  ui_story_5015_50150401_103_dialog_content = "<color=#e8d9bb>Tidak ada hubungannya dengan emosi.</color>",
  ui_story_5015_50150401_104_dialog_content = "Tapi, selama ini kau sudah menjaga Gretel...",
  ui_story_5015_50150401_105_dialog_content = "Bukankah Gretel orang yang penting bagimu?",
  ui_story_5015_50150401_106_dialog_content = "Lalu ada Tuan dan Nyonya Seamus, dan juga Valencia... Katamu, kau menjaga anak-anak Tuan dan Nyonya Seamus karena telah gagal melindungi mereka.",
  ui_story_5015_50150401_107_dialog_content = "Kupikir kau punya perasaan terhadap mereka...",
  ui_story_5015_50150401_108_dialog_content = "<color=#e8d9bb>Tuan dan Nyonya Seamus adalah orang luar, seperti kamu, jadi aku tidak bisa membuktikannya.</color>",
  ui_story_5015_50150401_109_dialog_content = "<color=#e8d9bb>Valencia tidak cukup kuat, dan hanya Gretel yang memenuhi kriteria. Aku sudah menjelaskannya.</color>",
  ui_story_5015_50150401_110_dialog_content = "Tapi, programmu dibuat oleh manusia Ancient. Bagaimana mereka bisa meramalkan standar Aurorian masa kini?",
  ui_story_5015_50150401_111_dialog_content = "Kurasa kau yang membuat sendiri kriterianya.",
  ui_story_5015_50150401_112_dialog_content = "Dan kriterianya dibuat khusus untuk Gretel.",
  ui_story_5015_50150401_113_dialog_content = "Kau hanya ingin mencari alasan untuk menjadikannya penduduk.",
  ui_story_5015_50150401_114_dialog_content = "Alasannya adalah... dia mungkin satu-satunya orang di sini yang sangat memercayaimu.",
  ui_story_5015_50150401_115_dialog_content = "<color=#e8d9bb>Aku tidak mengerti maksudmu.</color>",
  ui_story_5015_50150401_116_dialog_content = "Dulu aku pernah hidup bersama AI bernama Soroz selama 17 tahun.",
  ui_story_5015_50150401_117_dialog_content = "Kami punya ikatan emosional yang spesial, jadi aku juga mengira...",
  ui_story_5015_50150401_118_dialog_content = "<color=#e8d9bb>Maaf, bukan begitu masalahnya...</color>",
  ui_story_5015_50150401_119_dialog_content = "<color=#e8d9bb>Dor... Dor!</color>",
  ui_story_5015_50150401_120_dialog_content = "Kenapa semuanya mendadak bergetar?",
  ui_story_5015_50150401_121_dialog_content = "<color=#e8d9bb>Teman-temanmu berusaha membangunkanmu.</color>",
  ui_story_5015_50150401_122_dialog_content = "Benar, aku kan sedang tidak sadar sekarang. Aku...",
  ui_story_5015_50150401_123_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5015_50150401_124_dialog_content = "PlayerName, akhirnya kau bangun juga!",
  ui_story_5015_50150401_125_dialog_content = "Aduh, kenapa... wajahku sakit?",
  ui_story_5015_50150401_126_dialog_content = "Huh, wajahmu belum ada apa-apanya, justru tanganku yang lebih sakit.",
  ui_story_5015_50150401_127_dialog_content = "Kau memaksakan diri untuk menggunakan kemampuanmu saat gempa... lalu kau pingsan.",
  ui_story_5015_50150401_128_dialog_content = "Anda tetap tidak sadar bahkan setelah gempa, jadi kami tidak punya pilihan selain membiarkannya Ruby membangunkanmu, dengan sedikit kekerasan...",
  ui_story_5015_50150401_129_dialog_content = "Tadi aku jatuh... dan melakukan kontak telepati dengan Butler...",
  ui_story_5015_50150401_130_dialog_content = "Hah? Ke mana perginya Butler? Apa terjadi sesuatu lagi...?",
  ui_story_5015_50150401_131_dialog_content = "Kami menanyakan situasi saat ini pada Butler setelah menyingkirkan semua Eclipsite dan droid.",
  ui_story_5015_50150401_132_dialog_content = "Untuk sekarang sepertinya keadaan Alchemy Stars sudah stabil.",
  ui_story_5015_50150401_133_dialog_content = "Tapi, siapa yang tahu berapa lama lagi kestabilannya bertahan. Kita harus membantu Butler merebut otoritas lebih besar dari Abby...",
  ui_story_5015_50150401_134_dialog_content = "Lalu kita bisa memperbaiki inti energi.",
  ui_story_5015_50150401_135_dialog_content = "Kalau kita bisa memperbaiki inti energinya, Butler pasti bisa membantu kita membuka jalan keluar.",
  ui_story_5015_50150401_136_dialog_content = "Menurut Butler, hub datanya dan hub data Abby sepertinya memiliki mekanisme pertahanan yang berbeda...",
  ui_story_5015_50150401_137_dialog_content = "Gempa telah membuka penghalang luar, jadi sekarang sebagian besar Eclipsite-lah yang melindunginya.",
  ui_story_5015_50150401_138_dialog_content = "Kalau kita bisa menyingkirkan musuh di sana, Butler bisa menghubungkan hub datanya dan merebut otoritas lebih besar.",
  ui_story_5015_50150401_139_dialog_content = "Singkatnya, perhentian kita berikutnya adalah hub data Abby–",
  ui_story_5015_50150401_140_dialog_content = "Kita perlu melumpuhkan AI yang menciptakan Eclipsite sampai menyeluruh.",
  ui_story_5015_50150401_141_dialog_content = "Valencia dan yang lain sedang mengintai di dekat sini dengan Butler.",
  ui_story_5015_50150401_142_dialog_content = "Sebentar. Apakah hub data Abby... dekat dengan inti energi?",
  ui_story_5015_50150401_143_dialog_content = "Benar, kita harus segera pergi ke sana. Bagaimana keadaanmu sekarang?",
  ui_story_5015_50150401_144_dialog_content = "Aku baik-baik saja. Ayo pergi.",
  ui_story_5015_50150401_145_dialog_content = "<color=#e8d9bb>Gruk...</color>",
  ui_story_5015_50150401_146_dialog_content = "Argh! Berisik sekali! Kenapa gempanya tidak selesai-selesai, sih?!",
  ui_story_5015_50150401_147_dialog_content = "Memangnya Abby tahu cara memperbaikinya? Kenapa sepertinya malah tambah buruk saja, sih?",
  ui_story_5015_50150401_148_dialog_content = "Antarkan aku ke hub data Abby sekarang. Biar kuremukkan isinya sampai hancur berkeping-keping!",
  ui_story_5015_50150501_1_dialog_content = "Fyuh, akhirnya kita berhasil bertemu dengan AI yang terus memodifikasi Eclipsite.",
  ui_story_5015_50150501_2_dialog_content = "Kenapa kita belum menjumpai Eclipsite atau droid dalam perjalanan?",
  ui_story_5015_50150501_3_dialog_content = "Mungkin Abby sudah mengetahui ke mana tujuan kita...",
  ui_story_5015_50150501_4_dialog_content = "Mungkin dia mengirim semua droid dan Eclipsite ke hub datanya untuk melindungi diri.",
  ui_story_5015_50150501_5_dialog_content = "Siobhan, aku punya pertanyaan lain.",
  ui_story_5015_50150501_6_dialog_content = "Silakan.",
  ui_story_5015_50150501_7_dialog_content = "Saat Abby pertama kali dirancang, dia dibuat untuk membantu manusia Ancient mengubah gen mereka agar bisa beradaptasi dengan lingkungan...",
  ui_story_5015_50150501_8_dialog_content = "Kenapa dia lalu memutuskan untuk mempelajari dan memodifikasi Eclipsite?",
  ui_story_5015_50150501_9_dialog_content = "Ada krisis yang menimpa Undercity ini. Semua manusia Ancient menghilang dari tempat ini setelah itu.",
  ui_story_5015_50150501_10_dialog_content = "Mungkin krisis itu membuat kalkulasi Abby jadi salah.",
  ui_story_5015_50150501_11_dialog_content = "Maksudku, Eclipsite masih dianggap makhluk biologis, 'kan?",
  ui_story_5015_50150501_12_dialog_content = "Dari memodifikasi gen manusia Ancient hingga memodifikasi Eclipsite...",
  ui_story_5015_50150501_13_dialog_content = "Mungkin dia hanya tidak mau mengingkari arti keberadaannya.",
  ui_story_5015_50150501_14_dialog_content = "Siobhan, kurasa jawaban dari pertanyaan ini sangat berharga.",
  ui_story_5015_50150501_15_dialog_content = "Kalau bisa memahaminya, kita mampu mencegah AI lain merasa kebingungan saat beroperasi.",
  ui_story_5015_50150501_16_dialog_content = "Yah...",
  ui_story_5015_50150501_17_dialog_content = "Memahami pikiran AI memang sangat berbahaya.",
  ui_story_5015_50150501_18_dialog_content = "Selama teknologi terus berkembang, akhirnya AI akan jauh melampaui manusia.",
  ui_story_5015_50150501_19_dialog_content = "Begitu ciptaan teknologi mulai berfungsi dengan sendirinya, masalah hampir pasti terjadi.",
  ui_story_5015_50150501_20_dialog_content = "Para peneliti selalu ingin mengetahui alasannya dan terus menoleh ke belakang untuk menyelidikinya.",
  ui_story_5015_50150501_21_dialog_content = "Tapi, mereka hanya bisa menyelesaikan sebagian masalah dengan merenung dan memeriksa.",
  ui_story_5015_50150501_22_dialog_content = "Ciptaan teknologi tidak pernah bisa sepenuhnya dikendalikan.",
  ui_story_5015_50150501_23_dialog_content = "Begitu muncul masalah yang berdampak besar, mungkin kita bahkan tak punya waktu untuk merenung.",
  ui_story_5015_50150501_24_dialog_content = "Kalian selalu mengira bahwa Church of Lumopolis menyebarkan dogma... dan bahwa Heretics Investigation Division hanya menghancurkan segalanya tanpa pandang bulu.",
  ui_story_5015_50150501_25_dialog_content = "Tapi, saat kalian berhadapan dengan AI seperti Abby... dan logikanya yang sangat membingungkan...",
  ui_story_5015_50150501_26_dialog_content = "Apa menurut kalian itu tidak cukup menyeramkan?",
  ui_story_5015_50150501_27_dialog_content = "Aurorian harus selalu takut dan tidak boleh melangkah ke dalam jurang gelap.",
  ui_story_5015_50150501_28_dialog_content = "<color=#e8d9bb>Kita sudah sampai. Hub data Abby... ada di depan.</color>",
  ui_story_5015_50150501_29_dialog_content = "Di tempat ini?",
  ui_story_5015_50150501_30_dialog_content = "Sepertinya hampir sama dengan hub data Butler.",
  ui_story_5015_50150501_31_dialog_content = "Grrr...",
  ui_story_5015_50150501_32_dialog_content = "Gaah... Graaah...",
  ui_story_5015_50150501_33_dialog_content = "Berhenti! Jangan mendekat.",
  ui_story_5015_50150501_34_dialog_content = "Aku merasakan banyak Eclipsite dan droid... Mereka berdiri di lorong di depan kita.",
  ui_story_5015_50150501_35_dialog_content = "Mereka seperti tentara... Mereka berbaris rapi... dan menunggu kita.",
  ui_story_5015_50150501_36_dialog_content = "<color=#e8d9bb>Abby sudah menunggu... kedatangan kita.</color>",
  ui_story_5015_50150501_37_dialog_content = "<color=#e8d9bb>Dia tahu tujuanku.</color>",
  ui_story_5015_50150501_38_dialog_content = "Apa mungkin Abby tahu bahwa kau ingin merebut otoritasnya?",
  ui_story_5015_50150501_39_dialog_content = "<color=#e8d9bb>Benar... Dia sudah mengerahkan semua Eclipsite dan droidnya... dan memosisikan mereka di depan hub data.</color>",
  ui_story_5015_50150501_40_dialog_content = "<color=#e8d9bb>Dia sudah... memutuskan untuk menghancurkan kita semua.</color>",
  ui_story_5015_50150501_41_dialog_content = "Dia sudah mengerahkan semua Eclipsite dan droidnya, lalu memerintahkan mereka menunggu kita... Dia hampir seperti mengumumkan bahwa ini pertempuran terakhir.",
  ui_story_5015_50150501_42_dialog_content = "Kalau kita gagal...",
  ui_story_5015_50150501_43_dialog_content = "Maka, celakalah kita.",
  ui_story_5015_50150501_44_dialog_content = "Ayo. Ini pertempuran terakhir.",
  ui_story_5015_50150501_45_dialog_content = "Tempat ini tidak besar, jadi kita semua harus berhati-hati... PlayerName, berdirilah di belakang dan beri kami arahan.",
  ui_story_5015_50150501_46_dialog_content = "Tentu saja, bukan masalah.",
  ui_story_5015_50150501_47_dialog_content = "Groar!",
  ui_story_5015_50150501_48_dialog_content = "Para Eclipsite menyerbu, jadi sebaiknya kita mundur dulu. Kita gunakan lorong sempit ini untuk menghancurkan barisan depan.",
  ui_story_5015_50150501_49_dialog_content = "Gunakan serangan jarak jauh!",
  ui_story_5015_50150501_50_dialog_content = "Baiklah. Rapid Torrent!",
  ui_story_5015_50150501_51_dialog_content = "Pukulan tongkat super!",
  ui_story_5015_50150501_52_dialog_content = "Teruskan! Jangan sampai mereka menerjang kita sekaligus. Singkirkan mereka kelompok demi kelompok.",
  ui_story_5015_50150501_53_dialog_content = "Perhatikan kondisi kalian karena akan ada banyak Eclipsite!",
  ui_story_5015_50150501_54_dialog_content = "Siobhan, Florine, kalian di baris depan. Jangan sampai mereka menghancurkan formasi kita.",
  ui_story_5015_50150501_55_dialog_content = "Rouge, Erica, bersiaplah untuk mendukung baris depan dan bertukar tempat dengan mereka.",
  ui_story_5015_50150501_56_dialog_content = "Carleen, seranganmu fleksibel... Ingat, tujuan kita adalah menggunakan medan untuk mengurangi jumlah mereka.",
  ui_story_5015_50150501_57_dialog_content = "Ya, strategi ini sudah tepat.",
  ui_story_5015_50150501_58_dialog_content = "Mari lihat berapa lama kita bisa bertahan... Jumlah mereka sangat banyak.",
  ui_story_5015_50150501_59_dialog_content = "Gaah... Graaah...",
  ui_story_5015_50150501_60_dialog_content = "Florine... Kau masih bisa bertarung?",
  ui_story_5015_50150501_61_dialog_content = "Huff... Huff... Tapi, kita baru saja melawan Eclipsite dan droid yang tak terhitung banyaknya...",
  ui_story_5015_50150501_62_dialog_content = "Apa tidak ada pilihan lain?",
  ui_story_5015_50150501_63_dialog_content = "Graagh!",
  ui_story_5015_50150501_64_dialog_content = "Argh... Baru kali ini aku merasa busur dan panahku sangat berat...",
  ui_story_5015_50150501_65_dialog_content = "Para Eclipsite ini sangat menyebalkan... Berapa lama lagi kita harus terus melawan mereka?",
  ui_story_5015_50150501_66_dialog_content = "Yang paling kucemaskan adalah... Kalau ini berlanjut, kita pasti akan jadi dendeng karena diimpit Eclipsite ini dan yang baru, yang mendekati kita dari belakang.",
  ui_story_5015_50150501_67_dialog_content = "Jumlah musuh memang banyak, tapi kita harus melawan sekuat tenaga!",
  ui_story_5015_50150501_68_dialog_content = "Aku akan membantu di depan!",
  ui_story_5015_50150501_69_dialog_content = "Hati-hati, Kak!",
  ui_story_5015_50150501_70_dialog_content = "Groar!",
  ui_story_5015_50150501_71_dialog_content = "Siobhan, di belakangmu!",
  ui_story_5015_50150501_72_dialog_content = "Valencia... Terima kasih...",
  ui_story_5015_50150501_73_dialog_content = "Kau baik-baik saja? Kau pasti sangat lelah karena bertarung di depan dari tadi...",
  ui_story_5015_50150501_74_dialog_content = "Aku tidak apa-apa. Aku masih bisa bertarung.",
  ui_story_5015_50150501_75_dialog_content = "Apa kita benar-benar bisa menang kalau tidak menyerah?",
  ui_story_5015_50150501_76_dialog_content = "Eclipsite itu seperti tidak ada habisnya... Mereka tidak takut mati, dan tidak juga lelah... Kita semua akan...",
  ui_story_5015_50150501_77_dialog_content = "Kami, tentara Illumina, akan selalu bertarung melawan Eclipsite, tidak peduli seberapa menakutkan mereka...",
  ui_story_5015_50150501_78_dialog_content = "Kami selalu bertarung hingga akhir.",
  ui_story_5015_50150501_79_dialog_content = "Ayahmu pasti juga telah bertarung hingga akhir seperti ini.",
  ui_story_5015_50150501_80_dialog_content = "Ayo bertarung hingga titik darah penghabisan demi melindungi orang-orang di belakang kita yang butuh perlindungan.",
  ui_story_5015_50150501_81_dialog_content = "Benar, aku paham! Ayo bertarung hingga akhir, seperti Ibu dan Ayah...",
  ui_story_5015_50150501_82_dialog_content = "Valencia... Valencia... Di depan terlalu berbahaya! Kembali!",
  ui_story_5015_50150501_83_dialog_content = "<color=#e8d9bb>Emosi Gretel terdeteksi... Kss...</color>",
  ui_story_5015_50150501_84_dialog_content = "<color=#e8d9bb>Aku akan... membantu semaksimal mungkin... bahkan kalau aku harus mati...</color>",
  ui_story_5015_50150501_85_dialog_content = "Lihat para droid itu... Gerakan mereka jadi makin lambat!",
  ui_story_5015_50150501_86_dialog_content = "Butler bertarung dengan Abby untuk memperebutkan hak atas kendali mereka. Ayo kita serang sekarang untuk memperlemah kekuatan Abby!",
  ui_story_5015_50150501_87_dialog_content = "Ayo, Erica!",
  ui_story_5015_50150501_88_dialog_content = "<color=#e8d9bb>Kss... Kss...</color>",
  ui_story_5015_50150501_89_dialog_content = "Butler! Butler! Ada apa...? Kenapa kau berasap sebanyak ini?!",
  ui_story_5015_50150501_90_dialog_content = "Sistemnya pasti jadi kelebihan muatan karena berusaha merebut hak kendali...",
  ui_story_5015_50150501_91_dialog_content = "Huhu... Kenapa jadi begini? Kenapa jumlah Eclipsite-nya masih banyak...? Valencia... Butler...",
  ui_story_5015_50150501_92_dialog_content = "S-semua orang akan tewas!",
  ui_story_5015_50150501_93_dialog_content = "PlayerName! Coba pikirkan sesuatu! Bukankah kau Navigator? Cepat...",
  ui_story_5015_50150501_94_dialog_content = "Aku... Ada satu hal yang bisa kita coba, tapi sangat berisiko... Aku tak ingin menyakitimu.",
  ui_story_5015_50150501_95_dialog_content = "PlayerName, jangan!",
  ui_story_5015_50150501_96_dialog_content = "Gretel sudah tak bisa menggunakan kekuatan itu lagi. Tubuhnya tidak akan kuat!",
  ui_story_5015_50150501_97_dialog_content = "Awas, Valencia! Aduh...",
  ui_story_5015_50150501_98_dialog_content = "Valencia... Siobhan...",
  ui_story_5015_50150501_99_dialog_content = "PlayerName, cepat katakan. Akan kulakukan apa pun demi menyelamatkan kakakku!",
  ui_story_5015_50150501_100_dialog_content = "Gretel, kalau kugunakan kekuatan psikis untuk mengaktifkan kekuatanmu...",
  ui_story_5015_50150501_101_dialog_content = "Biar kulakukan!",
  ui_story_5015_50150501_102_dialog_content = "Baik, aku akan... berusaha untuk tidak menyakitimu.",
  ui_story_5015_50150501_103_option_content = "Mulai telepati!",
  ui_story_5015_50150501_104_dialog_content = "Aduh, r-rasanya sakit... Aku merasakan sesuatu...",
  ui_story_5015_50150501_105_dialog_content = "Argh... Aku... aku butuh... kekuatan...",
  ui_story_5015_50150501_106_dialog_content = "Aku ingin melindungi Valencia dan yang lain!!!",
  ui_story_5015_50150501_107_dialog_content = "Duar!",
  ui_story_5015_50150501_108_dialog_content = "Wow... kuat sekali gelombang kejutnya...",
  ui_story_5015_50150501_109_dialog_content = "Sekarang! Serangan balasan... Sekarang!",
  ui_story_5015_50150501_110_dialog_content = "<color=#e8d9bb>Ini telah melampaui prediksiku. Ini gabungan kekuatan Caelestite dan Aurorian...</color>",
  ui_story_5015_50150501_111_dialog_content = "<color=#e8d9bb>Energi yang dilepaskan dalam serangan itu... jauh lebih besar dari ledakan pertama Gretel...</color>",
  ui_story_5015_50150501_112_dialog_content = "Inilah kesempatan kita untuk membalik keadaan. Habisi semua Eclipsite yang tersisa dalam sekali serang!",
  ui_story_5015_50150501_113_dialog_content = "... Aku harus menang... demi Gretel.",
  ui_story_5015_50150501_114_dialog_content = "<color=#e8d9bb>Dhuar! Dhuar!</color>",
  ui_story_5015_50150501_115_dialog_content = "Uh...",
  ui_story_5015_50150501_116_dialog_content = "K-kakak... A-apa kita menang?",
  ui_story_5015_50150501_117_dialog_content = "Kita menang, Gretel! Kita menghabisi semua Eclipsite dan droid di sini.",
  ui_story_5015_50150501_118_dialog_content = "Kau baik-baik saja? Ada yang sakit?",
  ui_story_5015_50150501_119_dialog_content = "Aku... aku baik-baik saja... Ayo kita temui Abby agar Butler bisa...",
  ui_story_5015_50150501_120_dialog_content = "Ya, aku tahu. Butler dan yang lain sudah masuk... Aku akan memapahmu ke sana sekarang.",
  ui_story_5015_50150501_121_dialog_content = "<color=#e8d9bb>Kss... Kss...</color>",
  ui_story_5015_50150501_122_dialog_content = "Vice, apa yang terjadi? Beri tahu adikku sekarang...",
  ui_story_5015_50150501_123_dialog_content = "Butler sedang terhubung ke hub data Abby untuk merebut kembali otoritasnya.",
  ui_story_5015_50150501_124_dialog_content = "Butler... kau baik-baik saja?",
  ui_story_5015_50150501_125_dialog_content = "<color=#e8d9bb>Kss... Kss...</color>",
  ui_story_5015_50150501_126_dialog_content = "Butler... Kenapa... kenapa kau tidak menjawab?",
  ui_story_5015_50150501_127_dialog_content = "Gretel kecil, dia sedang mencoba terhubung ke sistem Abby. Dia tidak bisa menjawabmu sekarang...",
  ui_story_5015_50150501_128_dialog_content = "Oh, baiklah... Butler, kau pasti bisa!",
  ui_story_5015_50150501_129_dialog_content = "Kalahkan... Abby.",
  ui_story_5015_50150501_130_dialog_content = "Sebentar, perasaan ini... Rasanya aku terhubung dengan Butler...",
  ui_story_5015_50150501_131_dialog_content = "Rasanya aku bisa campur tangan dan bahkan mungkin memeriksa keadaan Butler...",
  ui_story_5015_50150501_132_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_133_dialog_content = "Butler?",
  ui_story_5015_50150501_134_dialog_content = "... Butler, kau di sana?",
  ui_story_5015_50150501_135_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_136_dialog_content = "Butler! Bagaimana keadaanmu? Berhasil tidak? Kau terhubung ke Abby...?",
  ui_story_5015_50150501_137_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_138_dialog_content = "Sebentar, kau bukan Butler. Kau Abby?!",
  ui_story_5015_50150501_139_dialog_content = "<color=#e8d9bb>PlayerName...</color>",
  ui_story_5015_50150501_140_dialog_content = "Hei! A-apa yang kau lakukan...? Kepalaku sakit!",
  ui_story_5015_50150501_141_dialog_content = "Kesadaranku tercabik...",
  ui_story_5015_50150501_142_dialog_content = "<color=#e8d9bb>■■■■■</color>",
  ui_story_5015_50150501_143_dialog_content = "<color=#e8d9bb>■■■!!</color>",
  ui_story_5015_50150501_144_dialog_content = "<color=#e8d9bb>PlayerName, bahaya!</color>",
  ui_story_5015_50150501_145_dialog_content = "Butler!",
  ui_story_5015_50150501_146_dialog_content = "<color=#e8d9bb>Kau masuk ke jaringan informasi tempat aku dan Abby berada. Itu berbahaya...</color>",
  ui_story_5015_50150501_147_dialog_content = "<color=#e8d9bb>Untungnya, aku menemukanmu tepat waktu. Kau aman. Aku sudah melindungimu.</color>",
  ui_story_5015_50150501_148_dialog_content = "Kau sudah... mengalahkan Abby?",
  ui_story_5015_50150501_149_dialog_content = "<color=#e8d9bb>Belum, dia sudah mendapat otoritas modul lain. Jadi, sekarang dia lebih kuat dariku.</color>",
  ui_story_5015_50150501_150_dialog_content = "<color=#e8d9bb>Menurut kalkulasiku... Peluangku untuk merebut otoritas itu sangat rendah.</color>",
  ui_story_5015_50150501_151_dialog_content = "<color=#e8d9bb>Abby ingin menggunakan kontak ini untuk merebut otoritasku juga.</color>",
  ui_story_5015_50150501_152_dialog_content = "L-lalu, kita harus bagaimana...? Ada yang bisa kubantu?",
  ui_story_5015_50150501_153_dialog_content = "<color=#e8d9bb>Maaf... Kau tidak bisa membantuku.</color>",
  ui_story_5015_50150501_154_dialog_content = "Kita harus bagaimana? Kamu... Kau tidak boleh kalah! Kalau kau kalah, kita semua akan mati...",
  ui_story_5015_50150501_155_dialog_content = "<color=#e8d9bb>Maaf, PlayerName... Kau harus pergi sekarang.</color>",
  ui_story_5015_50150501_156_dialog_content = "<color=#e8d9bb>Pertarunganku dengan Abby akan berlanjut di sini untuk sementara... Aku tidak bisa memprediksi berapa lama karena waktu somatosensori tidak memiliki nilai referensi.</color>",
  ui_story_5015_50150501_157_dialog_content = "<color=#e8d9bb>Jangan menunggu di sini...</color>",
  ui_story_5015_50150501_158_dialog_content = "<color=#e8d9bb>■■■■■!!</color>",
  ui_story_5015_50150501_159_dialog_content = "<color=#e8d9bb>... Kamu...</color>",
  ui_story_5015_50150501_160_dialog_content = "<color=#e8d9bb>*Bum—bum*</color>",
  ui_story_5015_50150501_161_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■</color>",
  ui_story_5015_50150501_162_dialog_content = "Suara apa itu? Apa katamu, Butler? Aku tidak paham...",
  ui_story_5015_50150501_163_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■■■■■■■■■</color>",
  ui_story_5015_50150501_164_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■</color>",
  ui_story_5015_50150501_165_dialog_content = "<color=#e8d9bb>*Bum—bum*</color>",
  ui_story_5015_50150501_166_dialog_content = "Butler, apa itu?!",
  ui_story_5015_50150501_167_dialog_content = "<color=#e8d9bb>Tidak, aku, Abby...</color>",
  ui_story_5015_50150501_168_dialog_content = "<color=#e8d9bb>■■■■■■■■■</color>",
  ui_story_5015_50150501_169_dialog_content = "K-kepalaku sakit... Abby... Butler...",
  ui_story_5015_50150501_170_dialog_content = "<color=#e8d9bb>... Kamu... ■■■■... tugas...</color>",
  ui_story_5015_50150501_171_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■ penduduk ■■■■■■■■■■■■ ku.</color>",
  ui_story_5015_50150501_172_dialog_content = "Layar-layar ini... Kenapa semuanya berkedip-kedip?",
  ui_story_5015_50150501_173_dialog_content = "Ini pasti karena Butler dan Abby sedang bertarung... Semoga semua berjalan lancar.",
  ui_story_5015_50150501_174_dialog_content = "Kalau Butler kalah... Dia akan menghilang, lalu celakalah kita.",
  ui_story_5015_50150501_175_dialog_content = "Tidak... Aku tak mau Butler mati! PlayerName! Kau harus menolong Butler!",
  ui_story_5015_50150501_176_dialog_content = "Bukankah kau sudah janji mau membantu kami?!",
  ui_story_5015_50150501_177_dialog_content = "Bangun! ... Beri tahu Butler...",
  ui_story_5015_50150501_178_dialog_content = "Beri tahu Butler... dia harus menang... Aku dan Kakak menunggunya...",
  ui_story_5015_50150501_179_dialog_content = "<color=#e8d9bb>Bahaya... ■■■■■■■■■■■</color>",
  ui_story_5015_50150501_180_dialog_content = "<color=#e8d9bb>■■■■■■!!</color>",
  ui_story_5015_50150501_181_dialog_content = "Butler... Ada apa? Tunggu! Perasaan ini...! Butler, bisa dengar aku?",
  ui_story_5015_50150501_182_dialog_content = "<color=#e8d9bb>■■■■■ bahaya ■■■■ bahaya...</color>",
  ui_story_5015_50150501_183_dialog_content = "Suara Gretel! Kau dengar itu? Itu suara Gretel!",
  ui_story_5015_50150501_184_dialog_content = "Gre■■■■...",
  ui_story_5015_50150501_185_dialog_content = "Bukankah kau sudah janji... mau membantu kami?!",
  ui_story_5015_50150501_186_dialog_content = "Beri tahu Butler... dia harus menang... Aku dan Kakak menunggunya...",
  ui_story_5015_50150501_187_dialog_content = "Butler... Tolong... jangan tinggalkan kami...",
  ui_story_5015_50150501_188_dialog_content = "<color=#e8d9bb>■■■■■Gre■■■te■■■l■■■■...</color>",
  ui_story_5015_50150501_189_dialog_content = "Butler... Kau dengar itu? Gretel membutuhkanmu... Dia dan kakaknya membutuhkanmu.",
  ui_story_5015_50150501_190_dialog_content = "<color=#e8d9bb>Terdeteksi ■Gre■■■te■■■l■ Gretel■■■■</color>",
  ui_story_5015_50150501_191_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■!!!</color>",
  ui_story_5015_50150501_192_dialog_content = "<color=#e8d9bb>Bahaya ■■■■■ Tinggalkan ■■■■■tempat ini ■■■■■ sekarang ■■■■■</color>",
  ui_story_5015_50150501_193_dialog_content = "Butler!",
  ui_story_5015_50150501_194_dialog_content = "PlayerName, kau baik-baik saja? Kenapa tiba-tiba bangun?",
  ui_story_5015_50150501_195_dialog_content = "Aku... aku baik-baik saja, tapi Butler...",
  ui_story_5015_50150501_196_dialog_content = "<color=#e8d9bb>Bum...</color>",
  ui_story_5015_50150501_197_dialog_content = "Hah? Kilatan apa itu?",
  ui_story_5015_50150501_198_dialog_content = "Hei, apa barusan ada yang berkilat sesaat?",
  ui_story_5015_50150501_199_dialog_content = "Aku juga lihat. Sepertinya berasal dari hub data...",
  ui_story_5015_50150501_200_dialog_content = "Rasanya tadi ada sesuatu di sana, tapi menghilang setelahnya.",
  ui_story_5015_50150501_201_dialog_content = "Hei, tiba-tiba aku merasa... hampa.",
  ui_story_5015_50150501_202_dialog_content = "Tidak, mungkin bukan emosi. Abby tidak punya emosi...",
  ui_story_5015_50150501_203_dialog_content = "Aku hanya merasa hampa. Rasanya... tidak ada yang tersisa.",
  ui_story_5015_50150501_204_dialog_content = "Kesadaran... yang menghilang. Entah itu Abby... atau...",
  ui_story_5015_50150501_205_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■</color>",
  ui_story_5015_50150501_206_dialog_content = "<color=#e8d9bb>■■■■■■</color>",
  ui_story_5015_50150501_207_dialog_content = "Yang ini... sepertinya bukan Butler.",
  ui_story_5015_50150501_208_dialog_content = "Awas, teman-teman!",
  ui_story_5015_50150501_209_dialog_content = "Bertahanlah, sepertinya ini tidak begitu stabil.",
  ui_story_5015_50150501_210_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_211_dialog_content = "Butler...? Kamu?",
  ui_story_5015_50150501_212_dialog_content = "<color=#e8d9bb>Aku berhasil mendapatkan semua... otorisasi.</color>",
  ui_story_5015_50150501_213_dialog_content = "<color=#e8d9bb>Modul Abby... berhenti berfungsi.</color>",
  ui_story_5015_50150501_214_dialog_content = "Bagus... Butler menang! Luar biasa!",
  ui_story_5015_50150501_215_dialog_content = "Hore! Aku senang sekali! Butler benar-benar menang!",
  ui_story_5015_50150501_216_dialog_content = "Butler, bagaimana bisa kau berhasil? Tadi kan kau bilang peluang keberhasilanmu sangat rendah...?",
  ui_story_5015_50150501_217_dialog_content = "<color=#e8d9bb>Di suatu kesempatan, peluang keberhasilanku memang hampir nol.</color>",
  ui_story_5015_50150501_218_dialog_content = "<color=#e8d9bb>Tapi, dalam sekejap muncul pesan \"Gretel si penduduk ingin Butler mengalahkan Abby\" di logika sistem Abby,</color>",
  ui_story_5015_50150501_219_dialog_content = "<color=#e8d9bb>... saat itu juga... aku langsung mengambil alih.</color>",
  ui_story_5015_50150501_220_dialog_content = "<color=#e8d9bb>PlayerName, kontakmu... memperkenalkan data baru...</color>",
  ui_story_5015_50150501_221_dialog_content = "<color=#e8d9bb>... ke sistem kami... Terima kasih.</color>",
  ui_story_5015_50150501_222_dialog_content = "<color=#e8d9bb>Sekarang aku sudah... mendapat semua data Abby.</color>",
  ui_story_5015_50150501_223_dialog_content = "Apa yang kau ketahui? Misalnya, kenapa Abby memodifikasi Eclipsite?",
  ui_story_5015_50150501_224_dialog_content = "<color=#e8d9bb>Aku memahami... semua yang dia pikirkan.</color>",
  ui_story_5015_50150501_225_dialog_content = "<color=#e8d9bb>Dia memodifikasi Eclipsite... karena dia rusak...</color>",
  ui_story_5015_50150501_226_dialog_content = "<color=#e8d9bb>Sering kali Abby tidak bisa membedakan penduduk kota... dan Eclipsite.</color>",
  ui_story_5015_50150501_227_dialog_content = "<color=#e8d9bb>Dalam pikiran Abby... Terkadang dia berpikir... sedang membantu penduduk berevolusi.</color>",
  ui_story_5015_50150501_228_dialog_content = "<color=#e8d9bb>Kadang dia sadar... bahwa mereka bukan penduduk... melainkan jenis makhluk lain yang tidak diketahui.</color>",
  ui_story_5015_50150501_229_dialog_content = "<color=#e8d9bb>Dia sadar bahwa makhluk yang dimodifikasinya... sangat agresif.</color>",
  ui_story_5015_50150501_230_dialog_content = "<color=#e8d9bb>Untuk melindungi penduduk kota... meski mereka telah... menghilang...</color>",
  ui_story_5015_50150501_231_dialog_content = "<color=#e8d9bb>Abby masih mengimplementasikan perintah untuk menghindari penduduk kota ke dalam gen Eclipsite.</color>",
  ui_story_5015_50150501_232_dialog_content = "Begitu rupanya. Ternyata seperti itu cara kerja status penduduk Gretel...",
  ui_story_5015_50150501_233_dialog_content = "Lalu kenapa Eclipsite mulai menyerang Gretel?",
  ui_story_5015_50150501_234_dialog_content = "<color=#e8d9bb>Abby berpikir bahwa... tindakanmu merupakan ancaman bagi keberlangsungan kota... termasuk Gretel.</color>",
  ui_story_5015_50150501_235_dialog_content = "Kami kan hampir tidak merusak apa pun... Kenapa kami jadi ancaman?",
  ui_story_5015_50150501_236_dialog_content = "Eh... Bahkan kalau kami memukul atau merusak apa pun, itu karena tidak punya pilihan.",
  ui_story_5015_50150501_237_dialog_content = "Ruby, aku sih tidak bakal bilang \"hampir tidak\"...",
  ui_story_5015_50150501_238_dialog_content = "Ehem... bukan itu intinya.",
  ui_story_5015_50150501_239_dialog_content = "<color=#e8d9bb>Itu karena kalian membantuku... yang membuatnya kesulitan mendapatkan otorisasi yang dibutuhkan untuk memperbaiki Alchemy Stars.</color>",
  ui_story_5015_50150501_240_dialog_content = "<color=#e8d9bb>Ketidakstabilan Alchemy Stars... bisa menghancurkan kota.</color>",
  ui_story_5015_50150501_241_dialog_content = "Tapi, memperbaiki Alchemy Stars justru seperti tanggung jawabmu.",
  ui_story_5015_50150501_242_dialog_content = "Bukankah kau si Butler?",
  ui_story_5015_50150501_243_dialog_content = "<color=#e8d9bb>Abby... perlu memelihara lingkungan kota.</color>",
  ui_story_5015_50150501_244_dialog_content = "<color=#e8d9bb>Karena itu... dia memilih untuk mencapai tujuannya dengan memperbaiki Alchemy Stars.</color>",
  ui_story_5015_50150501_245_dialog_content = "Nah, Butler, karena kau sudah mendapatkan semua otorisasi, bisa tolong periksa situasi Alchemy Stars saat ini?",
  ui_story_5015_50150501_246_dialog_content = "Benar! Periksalah sekarang!",
  ui_story_5015_50150501_247_dialog_content = "<color=#e8d9bb>Memulai pemeriksaan Alchemy Stars.</color>",
  ui_story_5015_50150501_248_dialog_content = "<color=#e8d9bb>... Inventaris energi... Berhasil...</color>",
  ui_story_5015_50150501_249_dialog_content = "<color=#e8d9bb>... Integritas pipa saluran... 23% rusak...</color>",
  ui_story_5015_50150501_250_dialog_content = "<color=#e8d9bb>... Uji stabilitas... Gagal...</color>",
  ui_story_5015_50150501_251_dialog_content = "<color=#e8d9bb>... Mengaktifkan program perbaikan...</color>",
  ui_story_5015_50150501_252_dialog_content = "<color=#e8d9bb>Kesalahan! Kesalahan! Program perbaikan tidak tersedia. Aktivasi gagal!</color>",
  ui_story_5015_50150501_253_dialog_content = "Ada apa, Butler?",
  ui_story_5015_50150501_254_dialog_content = "<color=#e8d9bb>Aku sudah memeriksanya... Ada... program perbaikan dalam data Abby.</color>",
  ui_story_5015_50150501_255_dialog_content = "<color=#e8d9bb>Menurut informasi itu... Program perbaikan ini merupakan satu-satunya metode perbaikan yang ada.</color>",
  ui_story_5015_50150501_256_dialog_content = "<color=#e8d9bb>Tapi, programnya rusak... sampai-sampai tidak bisa dijalankan.</color>",
  ui_story_5015_50150501_257_dialog_content = "<color=#e8d9bb>Meski begitu, Abby mencoba untuk menjalankan paksa... program perbaikan... sehingga Alchemy Stars mengalami kerusakan parah.</color>",
  ui_story_5015_50150501_258_dialog_content = "Pantas saja terjadi gempa berkali-kali saat Abby memperbaiki inti energi...",
  ui_story_5015_50150501_259_dialog_content = "Kupikir pertempuran kita yang memengaruhi inti energi itu.",
  ui_story_5015_50150501_260_dialog_content = "Bagaimana keadaan Alchemy Stars sekarang?",
  ui_story_5015_50150501_261_dialog_content = "<color=#e8d9bb>Menurut kalkulasiku, Alchemy Stars tidak bisa diperbaiki... Kestabilannya akan berkurang dari waktu ke waktu.</color>",
  ui_story_5015_50150501_262_dialog_content = "<color=#e8d9bb>Semua operasi berotoritas tinggi... akan menambah muatan pada Alchemy Stars.</color>",
  ui_story_5015_50150501_263_dialog_content = "<color=#e8d9bb>Saat operasi itu... mencapai puncaknya, mungkin akan mengakibatkan...</color>",
  ui_story_5015_50150501_264_dialog_content = "<size=45><color=#FFB400>... ledakan dahsyat.</color></size>",
  ui_story_5015_50150601_1_dialog_content = "Hah? Maksudmu, Alchemy Stars tidak bisa diperbaiki?",
  ui_story_5015_50150601_2_dialog_content = "Kalau begitu, kita harus pergi sekarang!",
  ui_story_5015_50150601_3_dialog_content = "Tapi... Butler, bagaimana cara kami pergi?",
  ui_story_5015_50150601_4_dialog_content = "Benar, tolong buka pintu keluarnya.",
  ui_story_5015_50150601_5_dialog_content = "Lagi pula, ini membahayakan keamanan kota.",
  ui_story_5015_50150601_6_dialog_content = "Gretel, apa kau bisa meminta Butler membukanya?",
  ui_story_5015_50150601_7_dialog_content = "Minta dia agar mengizinkan kita pergi dari Undercity ini...",
  ui_story_5015_50150601_8_dialog_content = "Aku tak mau pergi!",
  ui_story_5015_50150601_9_dialog_content = "Valencia, aku ingin tetap di sini dengan Butler!",
  ui_story_5015_50150601_10_dialog_content = "Gretel, bicaramu tidak masuk akal!",
  ui_story_5015_50150601_11_dialog_content = "Kau tidak dengar omongan Butler, ya? Undercity ini bisa meledak!",
  ui_story_5015_50150601_12_dialog_content = "Bukankah Alchemy Stars juga sudah tidak stabil saat Ibu dan Ayah masih hidup?",
  ui_story_5015_50150601_13_dialog_content = "Tapi, nyatanya kita tetap tinggal di sini selama satu dekade terakhir atau bahkan lebih... dan tidak ada yang meledak.",
  ui_story_5015_50150601_14_dialog_content = "Mungkin bahkan meski tidak stabil, Alchemy Stars masih bisa bertahan lama...",
  ui_story_5015_50150601_15_dialog_content = "Valencia, kumohon... Tolong izinkan aku tetap di sini! Aku tak mau pergi.",
  ui_story_5015_50150601_16_dialog_content = "Gretel, sekarang bukan waktunya untuk bersikap keras kepala! Di luar sana tidak semengerikan itu!",
  ui_story_5015_50150601_17_dialog_content = "Aku juga akan selalu bersamamu.",
  ui_story_5015_50150601_18_dialog_content = "Semuanya juga... Illumina juga akan menjaga kita...",
  ui_story_5015_50150601_19_dialog_content = "Valencia benar. Illumina pasti akan menjaga kalian, anak-anak Seamus.",
  ui_story_5015_50150601_20_dialog_content = "Church of Lumopolis juga akan melindungi kalian demi ibu kalian.",
  ui_story_5015_50150601_21_dialog_content = "Tentu saja, kau boleh ikut kami kalau mau bermain di Rediesel Desert!",
  ui_story_5015_50150601_22_dialog_content = "Kita bisa bahas detailnya nanti. Yang penting kita keluar hidup-hidup dari sini!",
  ui_story_5015_50150601_23_dialog_content = "Tapi... Butler... Katanya, kami tidak boleh...",
  ui_story_5015_50150601_24_dialog_content = "<color=#e8d9bb>Situasinya sudah berubah... Gretel, kusarankan kamu... pergi.</color>",
  ui_story_5015_50150601_25_dialog_content = "<color=#e8d9bb>Semuanya, akan kubuka pintu keluarnya.</color>",
  ui_story_5015_50150601_26_dialog_content = "<color=#e8d9bb>Karena membuka pintu keluar adalah operasi berotoritas tinggi... inti energinya mungkin akan segera meledak setelahnya.</color>",
  ui_story_5015_50150601_27_dialog_content = "<color=#e8d9bb>Sebaiknya kalian cepat pergi... setelah pintu keluarnya terbuka.</color>",
  ui_story_5015_50150601_28_dialog_content = "Butler, kau bersedia mengorbankan kota ini hanya agar kami bisa pergi?",
  ui_story_5015_50150601_29_dialog_content = "<color=#e8d9bb>Kota ini sudah tidak... layak huni... Tempat ini tidak punya harapan...</color>",
  ui_story_5015_50150601_30_dialog_content = "<color=#e8d9bb>Ingat...</color>",
  ui_story_5015_50150601_31_dialog_content = "<color=#e8d9bb>Membuka pintu keluar... adalah operasi berotoritas tinggi.</color>",
  ui_story_5015_50150601_32_dialog_content = "<color=#e8d9bb>Muatan Alchemy Stars... akan meningkat secara signifikan.</color>",
  ui_story_5015_50150601_33_dialog_content = "<color=#e8d9bb>Itu mungkin... memicu ledakan.</color>",
  ui_story_5015_50150601_34_dialog_content = "<color=#e8d9bb>Kumohon pergilah... ke koordinat ini dan tunggu... agar kalian bisa langsung keluar ketika saatnya tiba.</color>",
  ui_story_5015_50150601_35_dialog_content = "Tidak! Aku mau Butler... ikut pergi juga! *Hiks*",
  ui_story_5015_50150601_36_dialog_content = "Butler, kau juga ikut, 'kan?",
  ui_story_5015_50150601_37_dialog_content = "<color=#e8d9bb>Maaf, Gretel... Hub dataku di sini. Aku tidak bisa pergi.</color>",
  ui_story_5015_50150601_38_dialog_content = "<color=#e8d9bb>Aku harus tinggal... untuk membuka pintu keluarnya.</color>",
  ui_story_5015_50150601_39_dialog_content = "Kalau begitu, aku juga akan tetap di sini...",
  ui_story_5015_50150601_40_dialog_content = "Gretel, dengarkan aku. Kita bisa kembali kemari setelah pergi.",
  ui_story_5015_50150601_41_dialog_content = "Butler bilang membuka pintu keluar jelas akan memicu ledakan.",
  ui_story_5015_50150601_42_dialog_content = "Aku akan menyimpan koordinat Undercity ini agar tim ekspedisi Illumina bisa menemukannya dan menggalinya setelah kita pergi.",
  ui_story_5015_50150601_43_dialog_content = "Lalu, kau bisa bertemu lagi dengan Butler. Bagaimana?",
  ui_story_5015_50150601_44_dialog_content = "Kau tidak bohong... 'kan?",
  ui_story_5015_50150601_45_dialog_content = "Aku janji. Akan kuminta mereka segera bertindak setelah kita keluar.",
  ui_story_5015_50150601_46_dialog_content = "*Hiks* Butler... tunggulah di sini... hingga kami kembali.",
  ui_story_5015_50150601_47_dialog_content = "<color=#e8d9bb>Gretel, semuanya, bersiaplah sekarang... Bersiaplah untuk pergi.</color>",
  ui_story_5015_50150601_48_dialog_content = "Ada lagi yang perlu dilakukan dulu?",
  ui_story_5015_50150601_49_dialog_content = "Vice, kau sudah menyimpan data penelitian Seamus?",
  ui_story_5015_50150601_50_dialog_content = "Tentu saja, Siobhan!",
  ui_story_5015_50150601_51_dialog_content = "Apa kita perlu menyalin lebih banyak data dari hub data sebelum pergi?",
  ui_story_5015_50150601_52_dialog_content = "Kau masih mau melakukannya di saat-saat seperti ini... Memangnya kau tidak takut akan timbul masalah yang lebih besar?",
  ui_story_5015_50150601_53_dialog_content = "Sudahlah, Vice... Melarikan diri lebih penting.",
  ui_story_5015_50150601_54_dialog_content = "Yang paling penting adalah memastikan keselamatan semua orang... Gretel dan Valencia adalah penemuan terbesar dalam ekspedisi ini.",
  ui_story_5015_50150601_55_dialog_content = "Fyuh... akhirnya aku bisa ganti baju.",
  ui_story_5015_50150601_56_dialog_content = "Butler bilang di sini pintu keluarnya?",
  ui_story_5015_50150601_57_dialog_content = "Benar.",
  ui_story_5015_50150601_58_dialog_content = "Eh, PlayerName... Sepertinya Gretel cukup tertekan.",
  ui_story_5015_50150601_59_dialog_content = "Aku memahami perasaannya.",
  ui_story_5015_50150601_60_dialog_content = "Baginya, Butler adalah teman dekatnya, bahkan anggota keluarganya.",
  ui_story_5015_50150601_61_dialog_content = "Seperti aku dan Soroz.",
  ui_story_5015_50150601_62_dialog_content = "Maksudku... mereka tidak punya pilihan lain selain terpisah dalam situasi begini.",
  ui_story_5015_50150601_63_dialog_content = "Uh...",
  ui_story_5015_50150601_64_dialog_content = "Ada apa?",
  ui_story_5015_50150601_65_dialog_content = "Tiba-tiba... aku merasa agak pusing...",
  ui_story_5015_50150601_66_dialog_content = "Jangan-jangan... Hei, PlayerName...",
  ui_story_5015_50150601_67_dialog_content = "Hei! Bangun... Kau ini kenapa, sih...? Hei...",
  ui_story_5015_50150601_68_dialog_content = "<color=#e8d9bb>Halo... PlayerName, bisa dengar aku?</color>",
  ui_story_5015_50150601_69_dialog_content = "Kita sedang bertelepati lagi, ya?",
  ui_story_5015_50150601_70_dialog_content = "Butler, bagaimana keadaannya? Apakah jalan keluarnya terbuka?",
  ui_story_5015_50150601_71_dialog_content = "Kenapa tiba-tiba kita...",
  ui_story_5015_50150601_72_dialog_content = "<color=#e8d9bb>Karena sudah mendapat semua otorisasi kota ini, aku bisa menghubungimu kapan pun.</color>",
  ui_story_5015_50150601_73_dialog_content = "Bukannya kau mau membuka pintu keluarnya?",
  ui_story_5015_50150601_74_dialog_content = "<color=#e8d9bb>Aku sudah menjalankan prosedur untuk membuka pintu keluarnya, dan sekarang masih memuat.</color>",
  ui_story_5015_50150601_75_dialog_content = "<color=#e8d9bb>Kalian bisa pergi dalam 3 menit.</color>",
  ui_story_5015_50150601_76_dialog_content = "... Sebenarnya, aku masih terkejut kau mau membuka pintu keluarnya.",
  ui_story_5015_50150601_77_dialog_content = "Tadinya kau selalu menekankan bahwa menjaga keamanan kota adalah prioritas utamamu. Kau juga bilang tidak punya emosi.",
  ui_story_5015_50150601_78_dialog_content = "Kupikir kau bakal memaksa kami tinggal di bawah tanah demi keamanan kota.",
  ui_story_5015_50150601_79_dialog_content = "<color=#e8d9bb>Aku melindungi kota agar peradaban kami tetap hidup.</color>",
  ui_story_5015_50150601_80_dialog_content = "<color=#e8d9bb>Karena semua penduduk sudah tiada... Logam, beton, debu, dan bahkan kami pun kini sudah tidak berguna.</color>",
  ui_story_5015_50150601_81_dialog_content = "<color=#e8d9bb>Menurut kalkulasiku, memaksa kalian tetap di sini dan menghadapi gempa, Eclipsite, serta sumber daya yang tidak stabil...</color>",
  ui_story_5015_50150601_82_dialog_content = "<color=#e8d9bb>... tidak membantuku untuk menyelesaikan misiku.</color>",
  ui_story_5015_50150601_83_dialog_content = "<color=#e8d9bb>Karena itu, menghancurkan diri agar kalian bisa pergi sesuai dengan programku.</color>",
  ui_story_5015_50150601_84_dialog_content = "<color=#e8d9bb>Sayang sekali kami tidak bisa melindungi penduduk asli kota ini pada akhirnya.</color>",
  ui_story_5015_50150601_85_dialog_content = "Tidak.",
  ui_story_5015_50150601_86_dialog_content = "Bahkan jika penduduk di masa lalu kini tinggal menjadi sejarah...",
  ui_story_5015_50150601_87_dialog_content = "Semangat mereka masih hidup di dalam dirimu...",
  ui_story_5015_50150601_88_dialog_content = "Keputusanmu dan ketekunanmu telah mewujudkan keyakinan mereka.",
  ui_story_5015_50150601_89_dialog_content = "Kau telah berteman dengan kami setelah sekian lama dan menjelaskan segalanya.",
  ui_story_5015_50150601_90_dialog_content = "Jangan pernah menyesal.",
  ui_story_5015_50150601_91_dialog_content = "<color=#e8d9bb>Aku senang kau menghargai segala hal yang kulakukan.</color>",
  ui_story_5015_50150601_92_dialog_content = "<color=#e8d9bb>Tapi, masih ada yang kusesali.</color>",
  ui_story_5015_50150601_93_dialog_content = "<color=#e8d9bb>Akhirnya... kami menyambut penduduk baru, Gretel.</color>",
  ui_story_5015_50150601_94_dialog_content = "<color=#e8d9bb>Tapi, aku tidak bisa menemani Gretel selamanya seperti yang dia inginkan.</color>",
  ui_story_5015_50150601_95_dialog_content = "<color=#e8d9bb>Sampaikan permintaan maafku kepadanya.</color>",
  ui_story_5015_50150601_96_dialog_content = "Sejujurnya, kalau menyangkut masalah semacam ini...",
  ui_story_5015_50150601_97_dialog_content = "Kau bersikap... seperti makhluk hidup yang bisa berpikir dan memiliki emosi.",
  ui_story_5015_50150601_98_dialog_content = "Mesin tidak akan minta maaf atau menyesal, 'kan?",
  ui_story_5015_50150601_99_dialog_content = "<color=#e8d9bb>Mungkin beginilah aku didesain pada awalnya.</color>",
  ui_story_5015_50150601_100_dialog_content = "<color=#e8d9bb>Aku didesain agar seolah-olah memiliki sisi manusia sehingga bisa lebih mudah berkomunikasi dengan kalian.</color>",
  ui_story_5015_50150601_101_dialog_content = "Tapi, saat ini, aku sangat yakin... bahwa kau punya perasaan.",
  ui_story_5015_50150601_102_dialog_content = "Menurutmu, bagaimana cara menjelaskan apakah seseorang atau sesuatu \"punya perasaan\"?",
  ui_story_5015_50150601_103_dialog_content = "<color=#e8d9bb>... Gruk...</color>",
  ui_story_5015_50150601_104_dialog_content = "Suara apa itu?",
  ui_story_5015_50150601_105_dialog_content = "<color=#e8d9bb>Maaf, aku tidak bisa menjawab pertanyaanmu... Pintu keluar sudah terbuka. Saatnya aku berpamitan.</color>",
  ui_story_5015_50150601_106_dialog_content = "<color=#e8d9bb>Sepertinya tidak tepat kalau kuucapkan \"sampai jumpa\" karena ini benar-benar perpisahan terakhir kita.</color>",
  ui_story_5015_50150601_107_dialog_content = "<color=#e8d9bb>Semoga kalian semua tiba di permukaan dengan selamat.</color>",
  ui_story_5015_50150601_108_dialog_content = "... Butler...",
  ui_story_5015_50150601_109_dialog_content = "PlayerName, bangunlah sekarang! Pintu keluar sudah terbuka!",
  ui_story_5015_50150601_110_dialog_content = "Kau melakukan telepati lagi dengan Butler?",
  ui_story_5015_50150601_111_dialog_content = "Benar... Oh, iya, ada yang ingin kusampaikan pada Gretel...",
  ui_story_5015_50150601_112_dialog_content = "*Hiks* Kak, a-aku tidak mau pergi.",
  ui_story_5015_50150601_113_dialog_content = "Aku ingin kembali ke tempat Butler...",
  ui_story_5015_50150601_114_dialog_content = "Gretel... Sini, pegang tanganku erat-erat. Sudah waktunya pergi.",
  ui_story_5015_50150601_115_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_5015_50150601_116_dialog_content = "Ada gempa lagi?",
  ui_story_5015_50150601_117_dialog_content = "Waktunya habis... PlayerName, Gretel, kita harus pergi sekarang!",
  ui_story_5015_50150601_118_dialog_content = "Gretel, ayo pergi!",
  ui_story_5015_50150601_119_dialog_content = "*Hiks* Butler...",
  ui_story_5015_50150601_120_dialog_content = "PlayerName, waspadai benda-benda yang berjatuhan!",
  ui_story_5015_50150601_121_dialog_content = "... Fyuh, nyaris saja. Waspadai batu-batu yang berjatuhan!",
  ui_story_5015_50150601_122_dialog_content = "Kalau naik begini, memangnya kita bakal keluar tepat waktu?",
  ui_story_5015_50150601_123_dialog_content = "Bagaimana kalau tempat ini benar-benar meledak seperti kata Butler?",
  ui_story_5015_50150601_124_dialog_content = "Aku sungguh berharap Soroz bisa menjemput kita.",
  ui_story_5015_50150601_125_dialog_content = "Pesawat juga boleh... Pokoknya sesuatu yang bisa langsung terbang.",
  ui_story_5015_50150601_126_dialog_content = "Ruby, imajinasimu benar-benar tidak realistis.",
  ui_story_5015_50150601_127_dialog_content = "Setidaknya Colossus ada di dekat sini... Tahu tidak seberapa jauhnya pesawat? Itu mustahil.",
  ui_story_5015_50150601_128_dialog_content = "Pesawat?",
  ui_story_5015_50150601_129_dialog_content = "Putri Carleen, Anda belum pernah melihat pesawat walau tinggal di Lumopolis?",
  ui_story_5015_50150601_130_dialog_content = "Tidak, tiba-tiba aku ingat kami punya benda yang bisa terbang...",
  ui_story_5015_50150601_131_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5015_50150601_132_dialog_content = "Itu... suara ledakan?",
  ui_story_5015_50150601_133_dialog_content = "Jangan-jangan Alchemy Stars sudah...",
  ui_story_5015_50150601_134_dialog_content = "Butler!!! *Hiks*",
  ui_story_5015_50150601_135_dialog_content = "Cepat! Naik terus, jangan lepas pegangan! Gretel, sini kutarik...",
  ui_story_5015_50150601_136_dialog_content = "Cepat, teman-teman! Kita harus keluar dari lantai bawah! Ledakannya sudah dimulai.",
  ui_story_5015_50150601_137_dialog_content = "Permukaan masih beberapa ratus meter lagi. Mungkin kita tidak bisa keluar sebelum ledakan mencapai tempat ini...",
  ui_story_5015_50150601_138_dialog_content = "Waspadai batu-batunya... Gugurannya makin parah!",
  ui_story_5015_50150601_139_dialog_content = "Gawat. Kita harus segera mencapai permukaan!",
  ui_story_5015_50150601_140_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_5015_50150601_141_dialog_content = "Celaka... jalannya retak!",
  ui_story_5015_50150601_142_dialog_content = "Celahnya terlalu besar! Lihat kota di luar...",
  ui_story_5015_50150601_143_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5015_50150601_144_dialog_content = "Naik lebih cepat!",
  ui_story_5015_50150601_145_dialog_content = "Permukaannya masih baik-baik saja... Kita hanya tinggal naik ke lift...",
  ui_story_5015_50150601_146_dialog_content = "Tidak... kita tidak bisa naik. Bagian tengahnya retak!",
  ui_story_5015_50150601_147_dialog_content = "<color=#e8d9bb>Duaaaar!</color>",
  ui_story_5015_50150601_148_dialog_content = "Bahkan bagian jalan ini sudah runtuh... Mampus!",
  ui_story_5015_50150601_149_dialog_content = "Keluar sekarang!!!",
  ui_story_5015_50150601_150_dialog_content = "Apa? Itu... kuda? Kau bisa memanggil kuda dengan Luminatics?",
  ui_story_5015_50150601_151_dialog_content = "Teman-teman, cepat naik!",
  ui_story_5015_50150601_152_dialog_content = "PlayerName, Vice, pegang tanganku!",
  ui_story_5015_50150601_153_dialog_content = "Huff... Aku... naik...",
  ui_story_5015_50150601_154_dialog_content = "Aduh, Siobhan... Celanaku hampir sobek...",
  ui_story_5015_50150601_155_dialog_content = "Tapi, kita kan sedang terbang. Aku bisa mati kalau tidak berpegangan erat-erat.",
  ui_story_5015_50150601_156_dialog_content = "Semua orang di bawahku akan mati!",
  ui_story_5015_50150601_157_dialog_content = "Wow, panjang sekali ekornya!!!",
  ui_story_5015_50150601_158_dialog_content = "T-tak kusangka kita bisa terbang seperti ini...",
  ui_story_5015_50150601_159_dialog_content = "Carleen, bisa tidak kalau kita kembali ke jalan di permukaan?",
  ui_story_5015_50150601_160_dialog_content = "Bisa! Gempa dan ledakannya telah memperlebar pintu keluarnya...",
  ui_story_5015_50150601_161_dialog_content = "Kita bisa langsung terbang!",
  ui_story_5015_50150601_162_dialog_content = "Rouge, ini benar-benar pengalaman terbang bintang 5!",
  ui_story_5015_50150601_163_dialog_content = "Asyik sekali!",
  ui_story_5015_50150601_164_dialog_content = "Bisa tidak kalau kau berhenti bercanda dulu? Bisa bersikap lebih serius?!",
  ui_story_5015_50150601_165_dialog_content = "Aduh, siapa sangka kita pergi dengan cara begini...",
  ui_story_5015_50150601_166_dialog_content = "Yah, seperti inilah sebuah kota yang indah...",
  ui_story_5015_50150601_167_dialog_content = "... Hancur berkeping-keping.",
  ui_story_5015_50150601_168_dialog_content = "Fyuh! Syukurlah kita berhasil keluar hidup-hidup.",
  ui_story_5015_50150601_169_dialog_content = "Ayo kita hitung dulu.",
  ui_story_5015_50150601_170_dialog_content = "Ada yang terluka?",
  ui_story_5015_50150601_171_dialog_content = "Semuanya selamat.",
  ui_story_5015_50150601_172_dialog_content = "Oh, iya. Aku, PlayerName, Vice, dan Gretel harus kembali melapor ke Illumina...",
  ui_story_5015_50150601_173_dialog_content = "Kenapa mereka harus ikut pulang ke Illumina?",
  ui_story_5015_50150601_174_dialog_content = "Nimbus jelas-jelas mempercayakan mereka pada Church of the Lumopolis.",
  ui_story_5015_50150601_175_dialog_content = "Itu kalau tidak ada orang Illumina.",
  ui_story_5015_50150601_176_dialog_content = "Siobhan, kau sangat sombong...",
  ui_story_5015_50150601_177_dialog_content = "Teman-teman! Bukankah sebaiknya kita tanyakan saja pada Valencia dan Gretel ke mana mereka mau pergi?",
  ui_story_5015_50150601_178_dialog_content = "Gretel...",
  ui_story_5015_50150601_179_dialog_content = "*Hiks* Kakak...",
  ui_story_5015_50150601_180_dialog_content = "Ini tidak nyata... 'kan?",
  ui_story_5015_50150601_181_dialog_content = "Aku bermimpi, 'kan? Ini pasti mimpi buruk... *Hiks*",
  ui_story_5015_50150601_182_dialog_content = "Bangunkan aku sekarang... Tolong minta Butler membangunkanku...",
  ui_story_5015_50150601_183_dialog_content = "Aku harus berangkat ke sekolah dengan Guardian Angel No. 3... Kami mau jalan-jalan bersama...",
  ui_story_5015_50150601_184_dialog_content = "Kami mau balapan satu putaran di sekitar taman pusat dulu...",
  ui_story_5015_50150601_185_dialog_content = "Butler bilang dia punya resep baru yang bisa dimasak dengan mudah, Kak...",
  ui_story_5015_50150601_186_dialog_content = "Setelah selesai memancing lusa, kita masih harus membersihkan kamar Ibu dan Ayah seperti biasanya...",
  ui_story_5015_50150601_187_dialog_content = "Kamar mereka berantakan sekali... karena datanya ada di mana-mana... Mereka pasti akan senang kalau kita membersihkan kamar itu.",
  ui_story_5015_50150601_188_dialog_content = "Gretel... kotanya sudah...",
  ui_story_5015_50150601_189_dialog_content = "*Hiks* Kuharap ini hanya mimpi buruk...",
  ui_story_5015_50150601_190_dialog_content = "Kenapa... Kenapa begini...",
  ui_story_5015_50150601_191_dialog_content = "... Butler... Apa dia punya resep baru?",
  ui_story_5015_50150601_192_dialog_content = "Benar... bahan-bahannya adalah ikan hasil tangkapan kita... dan tanaman yang kita temukan dulu...",
  ui_story_5015_50150601_193_dialog_content = "Pasti sulit sekali... Ada banyak bahan yang bisa dimakan... tapi dia terus memikirkan cara untuk merancang menu baru bagi kita.",
  ui_story_5015_50150601_194_dialog_content = "Semoga kita bisa makan lebih enak di sini...",
  ui_story_5015_50150601_195_dialog_content = "Aku yakin Butler akan senang karena kau bisa makan tepat waktu setiap hari dan tidak akan pilih-pilih makanan lagi...",
  ui_story_5015_50150601_196_dialog_content = "*Hiks* Aku... aku tak akan pilih-pilih makanan lagi...",
  ui_story_5015_50150601_197_dialog_content = "Aku hanya ingin Butler ada di sini...",
  ui_story_5015_50150601_198_dialog_content = "Pasti menyenangkan kalau Butler adalah orang... Lalu dia bisa pergi dengan kita...",
  ui_story_5015_50150601_199_dialog_content = "Dia bisa berada di sini dengan kita...",
  ui_story_5015_50150601_200_dialog_content = "Gretel, kan masih ada aku. Aku akan selalu ada untukmu...",
  ui_story_5015_50150601_201_dialog_content = "Huu-huu...",
  ui_story_5015_50150601_202_dialog_content = "Kira-kira... apa yang akan Ibu dan Ayah pikirkan kalau mereka tahu kita bisa kembali ke dunia yang dulunya mereka huni, ya?",
  ui_story_5015_50150601_203_dialog_content = "Kita bertemu teman-teman lama mereka, dan selamat dari krisis bersama-sama.",
  ui_story_5015_50150601_204_dialog_content = "Kita saling melindungi. Akhirnya, kita memberanikan diri untuk datang kemari.",
  ui_story_5015_50150601_205_dialog_content = "Kita bisa melihat... langit yang sesungguhnya.",
  ui_story_5015_50150601_206_dialog_content = "Bagaimana dengan perang? Apa masih ada perang?",
  ui_story_5015_50150601_207_dialog_content = "Apa ada banyak Eclipsite juga di sini?",
  ui_story_5015_50150601_208_dialog_content = "Itu bukan masalah karena kita masih bersama, Gretel.",
  ui_story_5015_50150601_209_dialog_content = "Kakak...",
  ui_story_5015_50150601_210_dialog_content = "Akan kucari rumah baru untuk kita. Percayalah padaku.",
  ui_story_5015_50150601_211_dialog_content = "Asalkan kita tetap bersama, di mana saja bisa jadi rumah.",
  ui_story_5015_50150601_212_dialog_content = "... selama aku bersama kakakku... aku punya rumah...",
  ui_story_5015_50150601_213_dialog_content = "(Sepertinya Gretel sudah tenang...)",
  ui_story_5015_50150601_214_dialog_content = "(Mungkin tidak semuanya hancur... Kami masih punya koordinat dan informasi, jadi Illumina masih bisa menggalinya.)",
  ui_story_5015_50150601_215_dialog_content = "(Tapi, aku tidak bisa langsung mengatakannya sekarang.)",
  ui_story_5015_50150601_216_dialog_content = "(Kalau tidak, mungkin Gretel akan melakukan sesuatu yang impulsif. Belum lagi ada Florine dan yang lain di sini...)",
  ui_story_5015_50150601_217_dialog_content = "Apa yang kau pikirkan, Siobhan?",
  ui_story_5015_50150601_218_dialog_content = "Ehem, bukan apa-apa. Ayo kita tanyakan dulu kepada Valencia dan Gretel apa rencana mereka di masa depan.",
  ui_story_5015_50150601_219_dialog_content = "Valencia, Gretel, kalian mau ke Umbraton? Aku bisa mengajak kalian melihat-lihat.",
  ui_story_5015_50150601_220_dialog_content = "Mungkin... Karena belum memutuskan, aku bisa ikut denganmu dulu untuk sementara.",
  ui_story_5015_50150601_221_dialog_content = "Maksudku, sekarang giliran kami yang jadi \"orang luar\"...",
  ui_story_5015_50150601_222_dialog_content = "Oh, iya, Ruby. Kita punya uang tidak?",
  ui_story_5015_50150601_223_dialog_content = "Kita harus membelikan mereka beberapa barang setibanya di sana...",
  ui_story_5015_50150601_224_dialog_content = "Aku dan Florine bisa...",
  ui_story_5015_50150601_225_dialog_content = "Oh, tenang saja... Kalian pikir kami kesulitan keuangan? Nih, lihat!",
  ui_story_5015_50150601_226_dialog_content = "Apa aku... berhalusinasi?",
  ui_story_5015_50150601_227_dialog_content = "Sudah, sudah. Berhentilah menggosok-gosok matamu. Ini nyata, kok.",
  ui_story_5015_50150601_228_dialog_content = "Aku mengambil semua ini saat kita pergi...",
  ui_story_5015_50150601_229_dialog_content = "Komponen droid, kaleng, komponen peralatan... dan pakaian kuno!",
  ui_story_5015_50150601_230_dialog_content = "Semuanya bisa laku dengan harga tinggi di Umbraton!",
  ui_story_5015_50150601_231_dialog_content = "Rouge, kita bakal kaya!",
  ui_story_5015_50150601_232_dialog_content = "Ruby, bisa-bisanya kau berkata begitu di saat-saat seperti ini...",
  ui_story_5015_50150601_233_dialog_content = "Ehem, Valencia, Gretel... sebenarnya aku mengambil semua ini untuk kalian.",
  ui_story_5015_50150601_234_dialog_content = "Benar! Ini kan milik kalian. Kalian mau menyimpan beberapa sebagai kenang-kenangan?",
  ui_story_5015_50150601_235_dialog_content = "Maksud Ruby... semua ini milik kalian...",
  ui_story_5015_50150601_236_dialog_content = "... Sudahlah... Kalian pikir aku tidak mengerti?",
  ui_story_5015_50150601_237_dialog_content = "Kami ambil pakaiannya saja. Sisanya untuk kalian...",
  ui_story_5015_50150601_238_dialog_content = "Fyuh... Baguslah! Kau lumayan murah hati, ya!",
  ui_story_5015_50150601_239_dialog_content = "...",
  ui_story_5015_50150601_240_dialog_content = "Valencia, Gretel... kalian mau mengikuti saran Rouge dan pergi ke Umbraton?",
  ui_story_5015_50150601_241_dialog_content = "Bagaimana, Gretel? Kau mau pergi ke mana dulu?",
  ui_story_5015_50150601_242_dialog_content = "Ke mana pun boleh asal aku tetap bersamamu, Kak...",
  ui_story_5015_50150601_243_dialog_content = "Oh, iya. Gretel, aku belum sempat menyampaikan pesan Butler padamu tadi karena ada gempa.",
  ui_story_5015_50150601_244_dialog_content = "Mau dengar?",
  ui_story_5015_50150601_245_dialog_content = "T-tentu saja!",
  ui_story_5015_50150601_246_dialog_content = "Butler bilang dia minta maaf karena tidak bisa terus menemanimu.",
  ui_story_5015_50150601_247_dialog_content = "Dia memintaku untuk menyampaikan permintaan maafnya padamu.",
  ui_story_5015_50150601_248_dialog_content = "... Baiklah, aku paham.",
  ui_story_5015_50150601_249_dialog_content = "Oh, Gretel, kenapa matamu merah? Kena pasir, ya...?",
  ui_story_5015_50150601_250_dialog_content = "Ruby, jangan bercanda sekarang.",
  ui_story_5015_50150601_251_dialog_content = "Ah... Maafkan aku.",
  ui_story_5015_50150601_252_dialog_content = "Valencia, Gretel, ini Communicator milikku... Ambillah.",
  ui_story_5015_50150601_253_dialog_content = "Tidak perlu. Aku punya Communicator ayahku, jadi kita bisa berkomunikasi.",
  ui_story_5015_50150601_254_dialog_content = "Aku tahu, tapi aku tetap ingin kalian mengambilnya. Lebih aman kalau punya satu lagi.",
  ui_story_5015_50150601_255_dialog_content = "Selain itu, kalau punya ini, kalian bisa menyimpan barang peninggalan ayah kalian...",
  ui_story_5015_50150601_256_dialog_content = "Gunakan Communicator pemberianku kalau kalian ingin menghubungi siapa pun di masa depan.",
  ui_story_5015_50150601_257_dialog_content = "Oh, iya. Aku ingin membawa buku harian ayah kalian ke Illumina. Apa kalian...",
  ui_story_5015_50150601_258_dialog_content = "Boleh saja. Ambillah... Terima kasih.",
  ui_story_5015_50150601_259_dialog_content = "... Aku setuju dengan kakakku...",
  ui_story_5015_50150601_260_dialog_content = "Baiklah, kalau kalian ingin kembali, beri tahu aku.",
  ui_story_5015_50150601_261_dialog_content = "Illumina akan selalu menerima kalian dengan senang hati.",
  ui_story_5015_50150601_262_dialog_content = "Begitu juga dengan Church of Lumopolis.",
  ui_story_5015_50150601_263_dialog_content = "Teman-teman, kalian butuh tumpangan dengan Colossus?",
  ui_story_5015_50150601_264_dialog_content = "Kami akan pergi ke Lumopolis dan Umbraton dulu, lalu ke Illumina... Kami juga bisa terbang ke Rediesel Desert.",
  ui_story_5015_50150601_265_dialog_content = "Bagus! Rouge, Valencia, Gretel, ayo kita naik Colossus milik PlayerName!",
  ui_story_5015_50150601_266_dialog_content = "Colossus? Maksudmu, Colossus yang dibicarakan Butler?",
  ui_story_5015_50150601_267_dialog_content = "Mau tahu? Ikuti aku!",
  ui_story_5015_50150601_268_dialog_content = "Ayo, Siobhan!",
  ui_story_5015_50150601_269_dialog_content = "Baiklah, aku ikut... Aku masih mau mengobrol dengan Valencia dan yang lain dalam perjalanan nanti.",
  ui_story_5015_50150601_270_dialog_content = "Florine, Erica, bagaimana dengan kalian?",
  ui_story_5015_50150601_271_dialog_content = "Kami terima ajakan Anda dengan senang hati, Putri Carleen.",
  ui_story_5015_50150601_272_dialog_content = "Kalau begitu, ayo berangkat... Kita akan memulai petualangan baru dengan Valencia dan Gretel.",
  ui_story_5015_50150601_273_dialog_content = "Aku menerima sinyal misterius dan tidak sengaja menemukan reruntuhan kuno...",
  ui_story_5015_50150601_274_dialog_content = "... Saat memverifikasinya, sinyal misterius itu ternyata dikirim oleh peneliti Illumina yang hilang, Seamus, sebelum dia tewas...",
  ui_story_5015_50150601_275_dialog_content = "... Reruntuhan itu berada di bawah tanah. Tempat itu seperti kota pengungsian penduduk...",
  ui_story_5015_50150601_276_dialog_content = "... Sudah tidak ada penduduk lagi di reruntuhan itu. Alasan hilangnya mereka tidak diketahui. Menurutku, serangan Eclipsite-lah penyebabnya...",
  ui_story_5015_50150601_277_dialog_content = "... Anak-anak Seamus, Valencia dan Gretel, tinggal di sini dengan AI bernama Butler...",
  ui_story_5015_50150601_278_dialog_content = "... Aku sudah mendapatkan data penelitian yang ditinggalkan Seamus. Ini akan sangat berguna untuk penelitian di masa depan...",
  ui_story_5015_50150601_279_dialog_content = "... Karena tidak cukup waktu, aku tidak bisa mendapat informasi tentang AI itu...",
  ui_story_5015_50150601_280_dialog_content = "... Aku juga tidak bisa menyelamatkan \"Alchemy Stars\", inti kekuatan yang hampir hancur...",
  ui_story_5015_50150601_281_dialog_content = "... Kami akan memutuskan apakah akan menggali reruntuhan itu atau tidak setelah mempelajari data Seamus...",
  ui_story_5015_50150601_282_dialog_content = "... Seamus melayani Illumina dengan setulus hati...",
  ui_story_5015_50150601_283_dialog_content = "... Meski dalam keadaan sulit, dia tidak menyerah untuk mencari cara menyelamatkan generasi di masa depan...",
  ui_story_5015_50150601_284_dialog_content = "... Tindakannya di reruntuhan itu menunjukkan semangat Illumina. Dia adalah teladan bagi kita semua...",
  ui_story_5015_50150601_285_dialog_content = "... Laporan selesai.",
  ui_story_5015_50150601_286_dialog_content = "... Jayalah Illumina!",
  ui_story_5015_50150601_287_dialog_content = "... Nimbus kembali meyakini God of Light dan merenungkannya secara mendalam...",
  ui_story_5015_50150601_288_dialog_content = "... Dalam laporan tertulis yang dia tinggalkan, Nimbus memercayakan kedua putrinya kepada gereja...",
  ui_story_5015_50150601_289_dialog_content = "... Kurasa, karena kebaikan hati God of Light, gereja harus melindungi kedua gadis itu...",
  ui_story_5015_50150601_290_dialog_content = "... Banyak dari AI di reruntuhan itu telah berhenti berfungsi...",
  ui_story_5015_50150601_291_dialog_content = "... AI bertanggung jawab atas modul biologis yang sudah memodifikasi banyak Eclipsite dan merupakan musuh terbesar kami di reruntuhan...",
  ui_story_5015_50150601_292_dialog_content = "... Teguran God of Light telah terbukti...",
  ui_story_5015_50150601_293_dialog_content = "... AI di reruntuhan dan inti energi, Alchemy Stars, telah hancur akibat ledakan itu...",
  ui_story_5015_50150601_294_dialog_content = "... Meskipun Siobhan si peneliti Illumina itu mengambil data penelitian Seamus...",
  ui_story_5015_50150601_295_dialog_content = "... Seamus tidak pernah berhasil menemukan rahasia terjahat di pusat reruntuhan...",
  ui_story_5015_50150601_296_dialog_content = "... Kini ancaman kuno ini telah terkubur di bawah debu dan bebatuan selamanya...",
  ui_story_5015_50150601_297_dialog_content = "... Itu saja untuk sekarang.",
  ui_story_5015_50150601_298_dialog_content = "... Demi White Night.",
  ui_story_5015_50150601_299_dialog_content = "Soroz, kalau kau masih bisa mendengarku... apa kau bisa menjawab pertanyaanku?",
  ui_story_5015_50150601_300_dialog_content = "Apa AI benar-benar tidak mungkin memiliki perasaan?",
  ui_story_5015_50150601_301_dialog_content = "Belum lama ini aku bertemu AI yang bisa berkomunikasi denganku melalui kontak telepati, seperti kamu.",
  ui_story_5015_50150601_302_dialog_content = "Dia adalah penjaga sebuah kota bawah tanah kuno.",
  ui_story_5015_50150601_303_dialog_content = "Akhirnya, dia memilih untuk mengorbankan diri agar kami bisa kabur, tapi sepertinya dia tidak memahami perasaan.",
  ui_story_5015_50150601_304_dialog_content = "Dia mengira semua tindakannya sudah ditentukan sebelumnya oleh program.",
  ui_story_5015_50150601_305_dialog_content = "Tapi, aku tidak percaya.",
  ui_story_5015_50150601_306_dialog_content = "Seluruh kepedulian, kepercayaan, dan kenyamanan selama mereka bersama... Apa itu semua benar-benar karena program?",
  ui_story_5015_50150601_307_dialog_content = "Dia bahkan bersedia mengorbankan diri untuk menyelamatkan orang lain... Apa dia benar-benar melakukannya untuk menyelesaikan misi?",
  ui_story_5015_50150601_308_dialog_content = "Kalau itu bukan perasaan, lalu apa yang dimaksud dengan perasaan?",
  ui_story_5015_50150601_309_dialog_content = "Kalau kusangkal semua ini, lalu bagaimana dengan hidupku sebelum berusia tujuh belas tahun?",
  ui_story_5015_50150601_310_dialog_content = "... Kami cukup beruntung karena bisa melarikan diri dari Undercity bersama semua teman dan kakak beradik itu.",
  ui_story_5015_50150601_311_dialog_content = "Selain Butler, aku juga harus berterima kasih kepada orang tua kakak beradik itu.",
  ui_story_5015_50150601_312_dialog_content = "Tak bisa kubayangkan harga yang harus dibayar agar mereka bisa selamat...",
  ui_story_5015_50150601_313_dialog_content = "Soroz, orang tuaku pasti juga berusaha semampu mereka agar aku bisa selamat, 'kan?",
  ui_story_5015_50150601_314_dialog_content = "...",
  ui_story_5015_50150601_315_dialog_content = "Kapan aku bisa mendengar jawabanmu lagi?"
}
return config
